window.__D("text/zohar/c041",{"p":[[9520012789,"<p><Noneb>סִתְרֵי תּוֹרָה</b> וַיוֹלֶד בִּדְמוּתּוֹ כְּצַּלְמוֹ וַיִּקְרָא אֶתּ שְׁמוֹ שֵׁתּ אוֹלִיפְּנָא מֵהָכָא דְאֲחַרִינָן לָא הֲווּ בְּדִיּוּקְנָא דִילֵיהּ וְדָא בִּדְמוּתּוֹ כְּצַּלְמוֹ אִתְּעֲבִיד בְּתִּיקוּנא דְּגוּפֵּיהּ וּבְתִּיקוּנָא דְּנַפְּשָׁא בְּאוֹרַח מֵישַׁר כְּדְקָא יִאוֹתּ. תּא חֲזֵי נָחָשׁ אַטִיל זוֹהֲמָא בְּחַוָּה וְהַהוּא זוֹהֲמָא הֲוָה מֵכַּשְׁכֵּשָׁא בִּמְעָהָא וְלָא יָכִיל לְאִצְּטַיְירָא</p>\n<p>בְּגִין דְּעַד לָא חַטָא אָדָם הֲווּ אַתְּוָון בְּאַלְפָּא בֵּיתָּא מִתְּתַּקְנֵי בֵּיה וְאִתְּצַּיְּירָן בֵּיה בְּהַאי עַלְמָא עַד דְמַטָתּ לְאָתּ כ\"ף אִתְּתְּקָנוּ דְכָר וְנוּקְבָא בְּחַבִיבוּ בְּגִנְתָּא וּמַלְאֲכֵי עִלָּאֵי קַמַּיְיהוּ מִיָד אֲבְאִישׁ לְסמ\"אל בִּרְקִיעָא וְנָחַתּ וְרָכָב עַל נָחָשׁ תַּקִיף וְאַחְזִי קַמֵּיהּ מַיָא אִתְּעֲרְבוּ אַתְּוָון</p>\n<p>כְּדֵין אִתְּחַבָּר סמ\"אל בְּהַהוּא נָחָשׁ וְאִתְּעֲבִידוּ חַד, וְנָטְלוּ אַתְּוָון וְעָבִידוּ מִתַּמָּן וַהֲלְאָה אוּמָנוּתָּא בִּישָׁא בְּאַתְּוון צּ\"ד צּי\"ד וְהַיְינוּ צּ\"ץ וְצָּדוּ לְהוּ בְּפִּתּוּיָא בִּישָׁא וַעֲבְדוּ אוּמָנוּתָּא יַתִּיר בְּאַתְּוון ק\"ר אוּמָנוּתּ דְשִׁקְרָא בְּגִין דְאִתְּהֲדָרוּ לְאַפְּכָא (להפכא) אַתְּוָון בְּאוּמָנוּתָּא בִּישָׁא. קו\"ף דְלָא יָכִיל לְקַיְימָא דְּלֵיתּ לָהּ רַגְלִין קוֹפָּא קַמֵּיהּ בְּנֵי נָשָׁא לֵיתּ לֵיהּ קִיוּמָא. רי\"ש רָע, אִלֵּין אִתְּהֲפָּכוּ בְּאוּמָנוּתָּא בִּישָׁא עַל דְנַפְּלוּ אָדָם וְאִתְּתֵּיהּ</p>\n<p>וּבְאִלֵּין אַתְּוָון ק\"ר אוֹלִידוּ בְּנִין ולא הֲווּ בְּקִיּוּמָא בְּדִיל זוֹהֲמָא דְנָחָשׁ דְאִשְׁתָּאִיב בְּחַוָּה מֵהַהוּא זוֹהֲמָא מַמָּשׁ אִתְּיְלִיד קַיִן וּבְגִין דָּא אִשְׁתְּכַח קָטוֹלָא בְּגִין דְנָחָשׁ אוּמָנוּתָּא דִּילֵיהּ קָטוֹלָא הוּא וְאִתְּעֲכְּבוּ אַתְּוָון עַד הָכָא.</p>\n<p>בְּשַׁעֲתָא דְּתָּב אָדָם בְּתִּיּוּבְתָּא וְאַהֲדַר כְּמִלְקַדְמִין לְשָׁמְשָׁא בְּנוּקְבֵיהּ מָה כְּתִּיב וַיוֹלֶד בּדמוּתּוֹ כְּצַּלְמוֹ דָּא הֲוָה מֵתִּיקוּנָא דְרוּחָא וְגוּפָּא כְּדְקָא יֵאוֹתּ וּכְדֵין כְּתִּיב (קהלת ה') יְשִׁ הֶבֶל אֲשֶׁר נַעֲשָׂה על הָאָרֶץ ואֲהַדְרוּ אַתְּוָון בְּשֵׁירוּתָּא דשי\"ן ותּי\"ו דִּכְתִּיב (בראשית ד׳:כ״ה) כִּי שָׁתּ לִי אֱלהִים זְרַע אַחֵר תַּחַתּ הֶבֶל שֵׁתּ הוּא בְּצֶּלֶם וּדְמוּתּ דְקַדְמָאֵי לָאו הֲכִי וּמֵהָכָא אִתְּבְּנֵי עַלְמָא בְּגווָֹנָא אַחָרָא דְאַלְפָּא בֵּיתָּא, קֵינָן וּמַהֲלַלְאֵל יֶרֶד, אִתּוֹסַף לְאַתְּקְנָא</p>\n<p>סִידוּרָא דְעַלְמָא בְּשֶׁבַע קִטְרִין סְגָלְגֶלָן. שֶׁבַע אַרְצּוֹתּ אִינוּן דּא לְעֵילָא מִן דָּא כְּמָה דְּאִינּוּן שִׁבְעָה רְקִיעִין דָּא לְעֵילָא מִן דָּא וְאִינּוּן אֶרֶץ אֲדָמָה אַרְקָא גֵיא נְשִׁיָּה צִּיָּה תֵּבֵל. תֵּבֵל לְעֵילָא מִכֻּלְּהוּ, דִכְתִּיב (תהלים ט') והוּא יִשְׁפּוֹט בְּצֶּדֶק</p>\n<p>כַּד נָפַּק אָדָם מִגִּנְתָּא דְעֵדֶן וְאִתְּתַּרַךָ מִתַּמָּן אִתְּרַמֵי לְהַהוּא דְאִיקְרֵי אֶרֶץ ואִיהוּ אֲתַּר חשוּךְּ דְּלֵיתּ תַּמָּן נְהִירוּ כְּלָל וְלָא מְשַׁמֵּשׁ כְּלוּם וְכֵיוָן דְּאָדָם עָאל תַּמָּן דָחִיל דְּחִילוּ סַגִּי ולהַט הַחֶרֶב הַמִּתְּהַפֶּכֶתּ הֲוָה מֵלָהַטָא בְּכָל סִטְרִין גּוֹ אֶרֶץ.</p>\n<p>כֵּיוָן דְּנָפַּק שַׁבָּתּ וְהִרְהֵר תְּשׁוּבָה אַפִּיק קוּדְשָׁא בְּרִיךָ הוּא לֵיהּ לְהַהוּא אֲתַּר דְאִקְּרֵי אֲדָמָה דִּכְתִּיב (בראשית ג׳:כ״ג) לַעֲבוֹד אֶתּ הָאֲדָמָה, בְּהַאי אִיתּ נְהִירוּ דְנָהִיר וְדִיּוּקְנִין דְכֹכְבַיָּא וּמַזָּל,</p>\n<p>וְתַּמָּן יוֹמָא וְצִּיּוּרִין דִּבְנֵי נַשָׁא עִלָּאִין גַבְרִין דְּנַפְּקוּ מֵאָדָם בְּמֵאָה וּתְּלָתִּין שְׁנִין דְּקָא הֲוָה משמּש בְּרוּחֵי נוּקְבֵי ואִינּוּן עֲצִּיבִין תָּדִיר, תַּלְיָא בְּהוּ חֶדְוָה ואִלֵּין מֵשָׁטְטֵי וְנָפְּקֵי לְעַלְמָא דָּא וּמִתְּהַפְּכָן לְסִטְרָא בִּישָׁא וּמִתְּהַדְרָן תַּמָּן וְצָּלַאן צְּלוֹתָּא וּמִתְּיָישְׁבָן בְּדוּכְתָּיְיהוּ תַּמָּן, וְזַרְעִין זַרְעִין בְּרֵיחִין, ואַכְלֵי. וְחִטִין לֵיתּ תַּמָּן וְלָא חַד מִז' מִינֵי תְּבוּאָה. בְּהַאי אֲתַּר אִתְּיְלִיד קַיִן וְהֶבֶל,</p>\n<p>כֵּיוָן דְחָטָא קַיִן אָחִיתּ לֵיהּ קוּדְשָׁא בְּרִיךָ הוּא מֵהַהוּא אֲתַּר דְאִקְּרֵי <Nonei></i>אֲדָמָה כְּתִּיב (בראשית ד׳:י״ד) הֵן גֵרַשְׁתָּ אוֹתִּי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה מֵהַהוּא אֲתַּר דְאִקְרֵי אֲדָמָה והֲיִיתִּי נָע ונָד בָּאָרֶץ בְּגִין דְּתַּמָּן אִתְּדַחָא וְאִתְּתַּרַךָ. וְהָיָה כָּל מוֹצְּאִי יַהֲרְגֵנִי בְּהַהוּא לַהַט הַחֶרֶב הַמִּתְּהַפֶּכֶתּ</p>\n<p>וַהֲוָה דָחִיל וְהִרְהֵר תְּשׁוּבָה וְסָלִיק לֵיהּ קוּדְשָׁא בְּרִיךָ הוּא לְאַרְקָא וַהֲוָה תַּמָּן וְאוֹלִיד בְּנִין בְּאַרְקָא וּבְאַרְקָא אִיתּ נְהִירוּ דְנָהִיר מִגּוֹ שִׁמְשָׁא, וְזַרְעִין זַרְעִין וְנָטְעִין אִילָנִין וְלֵיתּ תַּמָּן חִטִין ולא מֵאִינוּן שֶׁבַע זִינֵי תְּבוּאָה.</p>\n<p>כָּל אִינוּן דְּתַּמָּן אִינוּן מִתּוֹלָדִין דְּקַיִן וְאִינּוּן בִּתְּרֵין רֵישִׁין מִנְּהוֹן גַבְרִין עִלָּאִין וּמִנְהוֹן גַבְרִין זְעִירִין וְלֵיתּ בְּהוּ דַּעְתָּא שְׁלִים כִּשְׁאָר בְּנֵי נַשָׁא דְהָכָא, לְזִמְנִין אִינוּן זַכָּאִין ואִתְּהֲדְרָן לְסִטְרָא טָבָא וּלְזִמְנִין אִתְּהֲדְרָן לְסִטְרָא בִּישָׁא וּמוֹלִידִין וּמֵתִּין כִּשְׁאַר בְּנֵי נָשָׁא.</p>\n<p>אָדָם הֲוה בְּאֲדָמָה (וארקא) עַד דְּאוֹלִיד שֵׁתּ וּמִתַּמָן סָלִיק לְעֵילָא ד' דַרְגִּין וְסָלִיק לְהַאי אֲתַּר דְאִקְּרֵי תֵּבֵל וְדָא תֵּבֵל אִיהוּ עִלָּאָה דְכֻלְּהוּ דַרְגִּין. כֵּיוָן דְסָלִיק סָלִיק לַאֲתָּר בֵּיתּ מַקְדְּשָׁא דְאִקְּרֵי בְּאִינוּן שְׁמָהָן דַהֲוָה דִּיוֹרֵיהּ בָּהּ אֶרֶץ אֲדָמָה דְהַכִי אִקְרֵי</p>\n<p>דָּלִיג אָדָם תְּלָתּ דוּכְתֵּי גֵיא, נְשִׁיָּה, צִּיָּה, גֵיא אִיהוּ אֲתַּר וְדּוּכְתָּא סַגִּי כְּהַאי פּוּתְּיָא וְאַרְכָּא דִּגֵיהִנָּם בַּגַּיא וּנְשִׁיָּה וְצִּיָּה אִתְּבַּדָּרוּ דְבָּנוּ מַגְדְּלָא ואוֹלִידוּ תַּמָּן על דְאַרְגִיזוּ לְמַלְכָּא עִלָּאָה בְּגִין דָּא קָרִיב לְנוּרָא דְּדָלִיק. וְאִיתּ בְּנֵי נָשָׁא יְקִירֵי בְּכָל עוּתְּרָא וְעֲפְּרוֹתּ זָהָב וְאַבְנִין יְקִירִין מָאן דְּעָאל תַּמָּן וַהֲוָה מִתֵּבֵל בְּחַמִידוּ דְּהַהוּא עוּתְּרָא יָהֲבִין לֵיהּ וְסָלִיק לְזִמְנִין לְדּוּכְתָּא דְאִקְּרֵי נְשִׁיָּה כְּגוֹן דְּאִתְּנָשׁוּ תַּמָּן ונָחִיתּ לְהַאי גֵיא וְלָא יָדַע אֲתַּר דַּהֲוָה מִתַּמָּן.</p>\n<p>גֵיא דָּא הוּא בְּאֶמְצָּעוּתָּא דְּעֵילָּא וְתַּתָּא וְדָא אִיקְּרֵי גֵיא בֵּן הִנוֹם. וּרְצּוּעָה חֲדָא נָפְּקָא מִתַּמָּן לְעֵילָא לְהַאי תֵּבֵל וְאִיקְּרֵי אוּף הֲכִי גֵיא בֵּן הִנוֹם וְתַּמָּן פִּתְּחָא דְּגֵיהִנָּם. אִינוּן בְּנֵי נָשָׁא דְּתַּמָּן כּוּלְהוּ יָדְעֵי חַרְשִׁין וחַכָּמָאן יְקִירִין וְתַּמָּן זַרְעֵי ונַטְעֵי אִילָנִין ולֵיתּ תַּמָּן חִטִין וְלָא חַד מִשִׁבְעַתּ הַמִינִים.</p>\n<p>בִּנְשִׁיָה אִיתּ בְּנֵי נָשָׁא כּוּלְהוּ קְטִיעִין זְעִירִין וְלֵיתּ לְהוֹן חוֹטְמִין בָּר תְּרֵין נוּקְבִין דְנָפִּיק בְּהוּ רוּחָא וְכָל מָה דְּעַבְדֵי מִיָד מִשִׁתַּכְּחֵי וְעַל דָּא אִיקְרֵי נְשִׁיָּה וזַרְעֵי ונַטְעֵי אִילָנִין ולֵיתּ תַּמָּן חִטִין ולֹא מִשִׁבְעַתּ הַמִינִים.</p>\n<p>צִּיָ\"ה אִיהוּ אֲתַּר כִּשְׁמֵיהּ בֵּיה יְבֵשׁוּתָּא בְּכוֹלָא וְתַּמָּן בְּנֵי נָשָׁא שַׁפִּירָן בְּחֵיזוּ וּמִגוֹ דְאִיהוּ צִּיָּה כַּד יַדְעֵי אֲתַּר דִּמְקוֹרָא דְּמַיִין נָבְעִין עָאלִין תַּמָּן וּלְזִמְנִין דְּסָלְקִין מִגּוֹ אֲתַּר דְמַיָּא וְסָלְקִין לְהַאי תֵּבֵל וְאִינּוּן בְּנֵי מְהֵימְנוּתָּא יַתִּיר מִבְּנֵי נָשָׁא אָחֳרָנִין וּבֵינַיְיהוּ דִיוּרִין טָבִין וְעוּתְּרָא סַגִּי וְזַרְעֵי מִגּוֹ יְבֵשׁוּתָּא דְּהָתָּם וְנַטְעֵי אִילָנִין ולא מַצְּלִיחִין וְתִּיאוּבְתָּא דִילְהוֹן לִבְנֵי נָשָׁא דְהָכָא.</p>\n<p>וּמִכֻּלְּהוּ לֵיתּ דְאַכְלֵי נַהֲמָא כַּד (ס\"א בר) אִלֵּין דְהָכָא דְבְּתֶּבֶל הַכָא לְעֵילָא מִכָּל אִלֵּין תֵּבֵל וּכְתִּיב (תהילים ט׳:ט׳) והוּא ישְׁפּוֹט תֵּבֵל בְּצֶּדֶק. כְגַוְונָא דְכָל אִלֵּין אַרְעָאן אִיתּ בְּהַאי תֵּבֵל וְכָל אִלֵּין שְׁמָהָן אִיתּ לָהּ אוּף הֲכִי בְּגִין דְאִיהִי שְׁבִיעָאָה אִיתּ הָכָא כְּגווֹנָא דְּאִינּוּן דוּכְתֵּי תְּחוּמִין וְדוּכְתֵּי הָכָא וְאִיקְּרֵי כּל חַד וְחַד כְּגווָֹנָא דְּהַהוּא דּוּכְתָּא דִלְתַּתָּא. וְכָל אִלֵּין בְּדִיוּרִין דִבְנֵי נָשָׁא מְשַׁנְיָין אִלֵּין מֵאִלֵּין (תהילים ק״ד:כ״ד) מָה רָבּוּ מַעֲשֶׂיךָ יְיָ כֻּלָּם בְּחָכְמָה עָשִׂיתָּ מָלְאָה הָאָרֶץ קִנְיָנְךָ ע\"כ:</p>"],[9520012790,"<p>רַבִּי חִזְקִיָּה אָמַר זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוֹן וְיָהַב לְהוֹן אוֹרַיְיתָא קַדִּישָׁא וְאַזְהָר לוֹן וְיָהַב לוֹן עֵיטָא לְאִסְתַּמְרָא מֵעֵילָא וְתַתָּא בְּגִין דְלָא יִשְׁלוֹט בְּהוּ בָּר קוּדְשָׁא בְּרִיךְ הוּא וְאִינּוּן יַדְעֵי לְדַּחֲיָא מִנַּיְיהוּ כָּל מְקַטְרְגִין וְכָל קַסְטִירִין בְּגִין דִיְהוֹן חוּלָקָא דְעֲדְבֵיהּ וְאַחֲסַנְתֵּיהּ כְּמָא דְאַתְּ אָמֵר (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>\n<p>תָּא חֲזֵי בְּיוֹמָא דְּרֹאשׁ הַשָׁנָה קוּדְשָׁא בְּרִיךְ הוּא יָתִיב בְּדִינָא עַל עַלְמָא וְכָל בְּנֵי עַלְמָא יַתְבֵי בְּחוּשְׁבָּנָא וְלָא אִית מָאן דְלָא עָאל בְּחוּשְׁבָּנָא וְסִפְרִין דְּחַיִין וּמֵתִין פְּתִיחָן בְּהַהוּא יוֹמָא וְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דְאִתְרָעֵי בְּהוּ יָהַב לוֹן עֵיטָא לְאִשְׁתֵּזָבָא מִכָּל קִטְרוּגִין דִלְעֵילָא דְּאִינּוּן אִתְמָנָן וְכֵן בְּכָל זִמְנָא דְּדִינָא שַׁרְיָיא עַל עַלְמָא.</p>\n<p>בְּהָאי יוֹמָא אִזְדָמְנָן יִשְׂרָאֵל לְאִתְעָרָא רַחֲמֵי עָלַיְיהוּ וּבְמָה בְּשׁוֹפָר. דְּהָא קָלָא דְנָפִיק סָלִיק לְעֵילָא וְאִתְעַר שׁוֹפָר דִלְעֵילָא כְּדֵין (מתערי) אִתְעֲרוּ רַחֲמֵי מֵאַתְרַיְיהוּ וְקוּדְשָׁא בְּרִיךְ הוּא קָם מִכּוּרְסַיָּיא דְּדִינָא וְיָתִיב בְּכוּרְסַיָּיא דְּרַחֲמֵי וְרָחִים עָלַיְיהוּ דְּיִשְׂרָאֵל וְלָא אִתְיְיהִיב רֵשׁוּ לְמְקַטְרְגָא. וְיִשְׂרָאֵל יַתְבֵי קַמֵי קוּדְשָׁא בְּרִיךְ הוּא בְּתִיּוּבְתָּא וְתַקְעֵי שׁוֹפָר (ומתערי) וְאִתְעֲרוּ רַחֲמֵי דְּהָא הַהוּא קָלָא דְנָפִיק אִתְעָרוּתָא דְּרַחֲמֵי אִיהוּ וּכְדֵין דַלְטוּרָא לָא יָכִיל לְקַיְימָא קַמֵי כוֹרְסַיָּיא דְּרַחֲמֵי דְּהָא לָא אָתֵי מֵהַהוּא סִטְרָא וְלָא אִשְׁתְּכַח קַטֵיגוֹרְיָיא.</p>\n<p>בְּיוֹמָא דְכִּפּוּרֵי דְּאִיהוּ חַתִימָא דְּדִינָא וְקַיְימֵי יִשְׂרָאֵל בִּקְדוּשָׁתָא דְמָרַיְיהוּ בְּהַהוּא יוֹמָא בְּגִין דְלָא יִקְרָב דַלְטוּרָא לְמַקְדְּשָׁא יָהֲבִין לֵיהּ שָׂעִיר דְאָתֵי מִסִּטְרָא דְרוּחָא מְסָאָבָא וְהוּא מְסָאָבָא וְרוּחַ מְסָאָבָא אִתְהַנֵי בֵּיהּ (והוא) הוּא אִתְעַסַּק בֵּיהּ וְלָא אִתְקַרָב לְמַקְדְּשָׁא לְסָאַבָא (מסאבא) וּכְדֵין אַנְפִּין נְהִירִין וְיִשְׂרָאֵל מִשְׁתַזְבִין מִנֵּיהּ.</p>\n<p>בְּזִמְנָא אַחֲרָא כַּד סָגִי (סגיין) חוֹבֵי בְּנֵי נָשָׁא הַאי דַלְטוּרָא בְּשַׁעְתָּא דְּדִינָא אִתְעָר עַל חוֹבֵי עַלְמָא <Nonei></i>כְּדֵין אִיהוּ אָתֵי וְאִשְׁתְּכַּח דַלְטוּרָא קַמֵי קוּדְשָׁא בְּרִיךְ הוּא וְיִסְתָאַב מַקְדְּשָׁא וְכָל אַנְפִּין עֲצִיבִין וְדִינָא אִשְׁתְּכַח וְעַל דָּא (בראשית ו׳:י״ג) קֵץ כָּל בָּשָׂר בָּא לְפָנַי, בָּא לְפָנַי וַדָאי לְמִתְבַּע חוֹבֵי עַלְמָא בְּגִין דְּאִינּוּן גָּרְמוּ:</p>"],[9520012791,"<p>צִוָּה ה'. אָמַר רַבִּי יוֹסֵי זַכָּאִין אִינוּן יִשְׂרָאֵל דְאִתְיְיהִיב לְהוֹן אוֹרַיְתָא קַדִּישָׁא וְאִינּוּן מִשְׁתַּדְלֵי בָּהּ יְמָמָא וְלֵילֵי. תָּא חֲזֵי דְהָא מַשְׁמַע דְאִלוּלֵי דְאִשְׁתַּכַּח נֹחַ עִם תֵּיבוּתָא בְּאִתְחַבְּרוּתָא כַּחֲדָא לָא אִשְׁתֵּזִיב (ובגין כך) אַסְתִּים מִן עֵינָא בְּגוֹ תֵּיבוּתָא. קָמוּ וְאָזְלוּ. אָמַר הַהוּא יוּדָאי בְּוַדַּאי כְּתִיב עֲשֵׂה לְךָ תֵּיבַת עֲצֵי גוֹפֶר, לְךָ לְגַרְמָךְ בְּגִין לְאִתְחַבְּרָא בַּהֲדָהּ וּלְאִשְׁתֵּזָבָא בָּהּ מָה כְּתִיב וַיַּעֲשֹׁ נֹחַ כְּכָל אֲשֶׁר צִוָהוּ וְגוֹ'.</p>"],[9520012792,"<p><Noneb>סִתְרֵי תּוֹרָה</b> (מזוהר ישן) מָה הֵשִׁיב הַקָּדוֹשׁ בָּרוּךָ הוּא לְנֹחַ כְּשֶׁיָּצָּא מִן הַתֵּיבָה וְרָאָה אֶתּ הָעוֹלָם חָרֵב והִתְּחִיל לִבְכּוֹתּ לְפָּנָיו וְאָמַר רִבּוֹנוֹ שֶׁל עוֹלָם נִקְרֵאתָּ רַחוּם הָיָה לְךָ לְרַחֵם עַל בְּרִיוֹתֶּךָ וְכוּ'. הֶשִׁיבוֹ הַקָּדוֹשׁ בָּרוּךָ הוּא וְאָמַר. רַעֲיאָ שָׁטְיָיא, הַשְׁתָּא אֲמַרְתָּ דָּא, לָמָה לֹא אֲמַרְתָּ בְּשַׁעְתָּא דְאֲמָרִיתּ לָךָ, כִּי אוֹתְּךָ רָאִיתִּי צַּדִּיק לְפָּנַי וְגוֹ'. וְאַחַר כָּךָ, הִנְנִי מֵבִיא אֶתּ הַמַּבּוּל מַיִם. וְאַחַר כָּךָ, עשה לְךָ תֵּיבַתּ עֲצֵּי גוֹפֶּר. כָּל הַאי אִתְּעֲכָּבִיתּ ואֲמָרִיתּ לָךָ בְּגִין דְּתַּבְעֵי רַחֲמִין עַל עַלְמָא. וּמִכְּדֵין שְׁמָעְתָּא דְתִּשְׁתְּזִיב בְּתֵּיבוּתָּא לָא עָאל בְּלִבָּךָ לְמִבְעֵי רַחֲמִין על יִשׁוּבָא דְעַלְמָא ועֲבָדְתּ תֵּיבוּתָּא וְאִשְׁתְּזִיבַתּ וּכְעַן דְּאִתְּאֲבִיד עַלְמָא פַּתָּחְתּ פּוּמָךָ לְמַלְּלָא קֳדָמָי בַּעְיָין וְתַּחֲנוּנִים. כֵּיוָן דְחָזָא נֹחַ כָּךָ, אַקְרִיב קָרֵבָּנִין ועֲלָוָון דִּכְתִּיב (בראשית ח׳:כ׳) וַיִּקַּח מִכָּל הַבְּהֵמָה הַטְהוֹרָה וּמִכָּל הַעוֹף הַטָהוֹר וְגוֹ'.</p>\n<p>אָמַר רַבִּי יוֹחָנָן בֹּא וּרְאֵה מָה בֵּין צַּדִּיקִים שֶׁהָיוּ לָהֶם לְיִשְׂרָאֵל אַחַר נֹחַ וּבֵין נֹחַ, נֹחַ לא הֵגִין עַל דוֹרוֹ וְלֹא הִתְּפָּלֵל עֲלֵיהֶם כְּאַבְרָהָם, דְּכֵיוָן דְּאָמַר קוּדְשָׁא בְּרִיךָ הוּא לְאַבְרָהָם (בראשית י״ח:כ״ג) זַעֲקָתּ סְדוֹם וַעֲמוֹרָה כִּי רַבָּה מִיָד וַיִּגַּשׁ אַבִרָהָם וַיֹּאמַר וְגוֹ' וְהִרְבָּה תַּחֲנוּנִים לִפְּנִי הַקָּדוֹשׁ בָּרוּךָ הוּא עַד שְׁשָׁאל שְׁאִם יִמְצָּא עֲשָׂרָה צַּדִּיקִים שֶׁיְכַפֶּר לְכָל הַמָּקוֹם בַּעֲבוּרָם, וְחַשָׁב אַבְרָהָם שֶׁהָיוּ בָּעִיר עִם לוֹט וְאִשְׁתּוֹ וּבְנוֹתָּיו עֲשָׂרָה צַּדִּיקִים וּלְפִּיכָךָ לא הִתְּפָּלֵל.</p>\n<p>אַחַר כַּךָ בָּא מֹשֶׁה וְהִתְּפָּלֵל וְהֵגִין עַל דוֹרוֹ כֵּיוָן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךָ הוּא (שמות ל״ב:ח׳) סָרוּ מָהֵר מִן הַדֶּרֶךָ. מִיָד עֲמָד מֹשֶׁה בַּתְּפִּלָה וַיְּחַל משֹה וְגוֹ' עַד שֶׁאַחַזָתּוֹ חַלְחַלָה. רָבַּנָן אַמְרֵי, לֹא הִנִּיחַ משהֹ לְקוּדְשָׁא בְּרִיךָ הוּא עַד שֶׁנָתַּן נַפְּשׁוֹ עֲלֵיהֶם מִן הָעוֹלָם הַזֶּה וּמִן הָעוֹלָם הַבָּא דִּכְתִּיב (שם) וְאִם אַיִן מְחֵנִי נָא מִסִּפְּרֶךָ אשר כַּתָּבְתָּ אָמַר רַבִּי יוֹסֵי מֵהָכָא (תהילים ק״ו:כ״ג) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵא מֹשֶׁה בְּחִירוֹ עָמָד בַּפֶּרֶץ לְפָּנָיו.</p>\n<p>אָמַר רַבִּי יְהושֹֹעַ, מָה רָאָה נֹחַ שֶׁלּא בִּיקֵשׁ רַחֲמִים עַל דוֹרוֹ. אָמַר בְּלִבּוֹ אוּלַי לֹא אַמָלֵט דִּכְתִּיב (בראשית ז׳:א׳) כִּי אוֹתְּךָ רָאִיתִּי צַּדִּיק לְפָּנַי בָּדוֹר הַזֶּה כְּלוֹמַר לְפִּי הַדוֹר וּלְפִּיכָךָ לא בִּיקֵשׁ רַחֲמִים עֲלֵיהֶם. אָמַר רַבִּי אֶלְעָזָר אֲפִּילוּ (הכי) הֵכִּיר הֲוָה לֵיהּ לְמִבְעֵי רַחֲמִין עַל עַלְמָא בְּגִין דְּנִיחָא לֵיהּ לְקוּדְשָׁא בְּרִיךָ הוּא, מָאן דְיֵימָר טָבָא עַל בְּנוֹי. מְנָא לָן מִגִדְעוֹן בָּר יוֹאַשׁ דְלָא הֲוָה זַכָּאי וְלָא בָּר זַכָּאי וּמִשׁוּם דְּאָמַר טִיבוּתָּא עַל יִשְׂרָאֵל, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךָ הוּא, (שופטים ו׳:י״ד) לֵךָ בְּכֹחַךָ זְה וְהוֹשָׁעְתָּ אֶתּ יִשְׂרָאֵל מִיָּד מִדְיָן. מָהוּ בְּכֹחַךָ זֶה טִיבוּתָּא דְּאַמָרַתּ עַל בָּנַי.</p>"],[9520012793,"<p>עוֹד פָּתַח הַהוּא יְנוֹקָא וְאָמַר (שיר השירים א׳:ג׳) לְרֵיחַ שְׁמָנְיךָ טוֹבִים. לְרֵיחַ מָאן, אֶלָּא אִית רֵיחַ וְאִית רֵיחַ. רֵיחַ הַקָּרְבָּן וְרֵיחַ הַקְּטוֹרֶת. רֵיחַ הַקָּרְבָּן מַקְרִיב וּמְיַיחֵד כָּל אִינוּן שִׁבְטַיָּא דְּהֵיכָלָא דְּבֵּית דָוִד וְרֵיחַ הַקְּטוֹרֶת מַקְרִיב וּמְיַיחֵד וְאַנְהִיר אִינוּן בּוֹצִינִין עִלָּאִין נָהִיר (נהרי) אֲפַרְסְמוֹנָא דַכְיָא</p>\n<p>וְעַל דָּא תְרֵין מָדְבְּחִין הֲווּ, מִזְבֵּחַ הַקְּטוֹרֶת וּמִזְבֶּחַ הָעוֹלָה מִזְבַּח הַקְּטוֹרֶת אִיהוּ פְּנִימָאָה מִזְבַּח הָעוֹלָה אִיהוּ לְבַר. רֵיחַ מִזְבַּח הָעוֹלָה מַתְקִין לְאַנְהֲרָא בּוֹצִינִין תַּתָּאִין, רֵיחַ מִזְבַּח הַקְּטוֹרֶת מַתְקִין לְאַנְהֲרָא בּוֹצִינִין עִלָּאִין. וְעַל דָּא לְרֵיחַ שְׁמָנֶיךָ טוֹבִים לְרֵיחַ דְּהַהוּא קְטוֹרֶת שְׁמָנְיךָ טוֹבִים.</p>\n<p>בֹּא וּרְאֵה שְׁתֵּי מִזְבֶּחוֹת הֵן מִזְבֵּחַ פְּנִימִי לְעֵילָא מִזְבֵּחַ חִיצוֹן לְתַתָּא. מִזְבֵּחַ הַפְּנִימִי הוּא שָׁלֵם וְזֶהוּ דִּכְתִיב הַמִּזְבֵּחָה בְּתוֹסֶפֶת הֵ\"א וְכָךְ הוּא בְכָל מָקוֹם. וּמִזְבֵּחַ הַחִיצוֹן הוּא חָסֵר הֵ\"א כְּמוֹ נַעֲרָה נַעַר חָסֵר ה'</p>\n<p>אִשְׁתְּכַח דְמִאִתְעַרוּתָּא דְמִזְבֵּחַ הַפְּנִימִי (ס\"א החיצון) שֶׁל מַטָּה אִתְעָר מִזְבֵּחַ הַפְּנִימִי שֶׁל מַעְלָה וּבְמָה אִתְעָר בְּרֵיחַ (ס\"א דמאתערותא דמזבח החיצון של מטה אתער מזבח החיצון של מעלה ובמה אתער בריח הקרבנות. ובריח הקטורת של מזבח הפנימי של מטה אתער מזבח הפנימי של מעלה, ובמה אתער בריח הקטורת. ועל דא) הַקְּטוֹרֶת. הַקְּטוֹרֶת שֶׁל מַעְלָה וְאִתְעָר רֵיחַ הַקָּרְבָּן שֶׁל מַטָּה וְעַל דָּא (שיר השירים א׳:ג׳) לְרֵיחַ שְׁמָנֶיךָ טוֹבִים אִינוּן בּוֹצִינִין נַהֲרִין וְנָצִיצִין. כְּתִיב הָכָא טוֹבִים וּכְתִיב הֲתָם (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב:</p>"],[9520012794,"<p>וַיְהִי כְּבוֹא אַבְרָם מִצְרַיְמָה, כְּבוֹאָם מִּבָּעֵי לֵיהּ וְשָׂרָה הֵיכָן הָיְתָה. אֶלָּא אַבְרָהָם אַעֲלָה בְּתֵיבוּתָּא וְסָגַר עֲלָהּ כֵּיוָן דְּמָטָא לְמִצְרָיִם אֲמְרוּ לֵיהּ הַב מִכְסָּא <Nonei></i>אָמַר אֲנָא יָהִיב מִכְסָּא. אֲמְרוּ לֵיהּ מָאנִין אַתְּ טָעִין אָמַר אֲנָא יָהִיב דְמָאנִין אָמְרוּ לֵיהּ מַטְכְּסָא אַתְּ טָעִין אָמַר אֲנָא יָהִיב דְּמַטְכְּסָא. אָמְרוּ לֵיהּ מַרְגֶלָאן אַתְּ טָעִין, אָמַר לְהוּ אֲנָא יָהִיב מִכְסָּא דְּמַרְגֶלָאן, אָמְרוּ לֵיהּ אִי אֶפְשָׁר, אֶלָּא לְמִפְתַּח תֵּיבוּתָא וְנֶחזֵי מָה בְּגַוָוהּ. כֵּיוָן דְּפַתְחוּ תֵּיבוּתָא אִתְנָהַרָא אַרְעָא דְמִצְרָיִם מִנְּהוֹרָא דִּילָה הֲדָא הוּא דִּכְתִיב (שם) וַיִּרְאוּ הַמִצְרִים אֶת הַאִשָׁה וְגוֹ' אָמַר רַבִּי יְהוּדָה וַיְהִי בְּבוֹאָם מִצְרַיְמָה, הֲוָה לֵיהּ לְמֵימָר אֶלָּא בַּתֵיבָה וְכוּ':</p>"],[9520012795,"<p>חֲמִשִׁים הֵם כְּנֶגֶד חֲמִשִׁים שַׁעֲרֵי בִּינָה וְהֵם רְאוּיִים לְהַצִּיל כָּל הָעוֹלָם בְּצִּדְקַתָם וַיְיָ הוֹדָה לִדְבַרֶיהָ וּכְשְׁרָאַתָה שֶׁלֹּא מָצְּאָה אָמְרָה (בראשית י״ח:כ״ח) אוּלַי יַחְסְרוּן חֲמִשִׁים הַצַּדִּיקִים חֲמִשָׁה, כְּלוֹמַר אוּלַי יֵשׁ בָּהֶם בְּנֵי אָדָם שְׁעַסְקוּ בִּיְדִיעַת שִׁמְךָ שֶׁהוּא הַשֵׁם בִּמְלוֹאוֹ שֶׁהוּא מָ\"ה יוֹ\"ד הֵ\"א וא\"ו הֵ\"א כְּמִסְפָר אָדָם שֶׁנֶּאֱמַר (דברים י׳:י״ב) וְעַתָּה יִשְׂרָאֵל מָה יְיָ אֱלהֶיךָ שׁוֹאֵל, וּכְשְׁלֹא מָצְּאָה חוֹזֶרֶת לוֹמַר, אוּלַי יִמָצְּאוּן שָׁם אַרְבָּעִים (ככתוב בדפוס)</p>"],[9520012796,"<p>עוֹד פוֹתָחַת וְאוֹמֶרֶת רִבּוֹנוֹ שֶׁל עוֹלָם אוּלַי יִמָצְּאוּן שָׁם שְׁלֹשִׁים כְּלוֹמַר אוּלַי יִשׁ בֵּינֵיהֶם צַּדִּיקִים שְׁעַסְקוּ והִשִּׂיגוּ אוֹתָם הַשְׁלשִֹׁים מַעֲלוֹת הַרְמוּזוֹת בִּנְבוּאַת יְחֶזְקֵאל בַּפָסוּק וַיְהִי בִּשְׁלֹשִׁים (שנה) וְגוֹ' וְהֵם כְּלוּלִים בְּלֵ\"ב נְתִיבוֹת חָכְמָה שֶׁהֵם כ\"ב אוֹתִיּוֹת וי' סְפִירוֹת.</p>\n<p>וכֵן אוּלַי יְשׁ בֵּינֵיהֶם אֲנָשִׁים צַּדִּיקִים יְחִידִי סְגוּלָה הַמְיַחֲדִים שִׁמְךָ ב' פַּעֲמִים בַּיוֹם בַּפָסוּק שְׁמַע יִשְׂרָאֵל שֶׁבָּה כְּלוּלִים י' סְפִירוֹת בְּמִלַּת אֶחָד האל\"ף עִם החי\"ת הֵם תִשְׁעָה וְהַמִלָה א' הֲרֵי עֲשָׂרָה והד' אָמַר דָוִד הַמֶּלֶךְ עָלָיו הַשָׁלוֹם עֲלָהּ (תהילים קי״ח:כ׳) זֶה הַשַׁעַר לַיְיָ צַּדִּיקִים יָבוֹאוּ בּוֹ וְד\"לת מִלָשׁוֹן שַׁעַר וּשְׁנֵי פַּעֲמִים בַּיוֹם הֲרֵי עֶשְׂרִים.</p>\n<p>וּכְשֶאֵינָה מוֹצְּאָה, חוֹזֶרֶת וּפוֹתָחַת וְאוֹמֶרֶת רִבּוֹנוֹ שֶׁל עוֹלָם, אוּלַי יִמָצְּאוּן שָׁם עֲשָׂרָה כְּלוֹמַר אוּלַי יִמָצֵּא בֵּינֵיהֶם מִי שֶׁעוֹסֵק בַּעֲשָׂרָה מַאֲמָרוֹת וּבְעֲשֶׂרֶת הַדִבְּרוֹת בְּכָל יוֹם וְכֵן אוּלַי יִמָצְּאוּן בֵּינֵיהֶם עֲשָׂרָה שֶׁמַקְדִימִים לְבֵית הַכְּנֶסֶת דְהָא תְּנַן כָּל (הנמצא) הַנִמְנָה מֵעֲשָׂרָה רִאשׁוֹנִים בְּבֵית הַכְּנֶסֶת נוֹטֵל שָׂכָר כְּנֶגֶד כּוּלָם שֶׁבָּאִים אַחֲרָיו, מָה כְּתִיב, לא אַשְׁחִית בַּעֲבוּר הַעֲשָׂרָה.</p>\n<p>כָּל זֶה יְשׁ לְנִשְׁמַת הַצַּדִּיק לְלָמֵד סְנֵגוֹרְיָיא וּזְכוּת עַל הָרְשָׁעִים לְהַשְׁקִיט הַאַף וְהַחֵמָה וכֵיוָן שֶׁלֹּא מָצְּאָה שׁוּם זְכוּת לְלָמֵד מָה כְּתִיב (בראשית י״ח:ל״ג) וַיֵּלֶךְ יְיָ כַּאֲשֶׁר כִּלָה לְדַבֵּר אֶל אַבְרָהָם וְאַבְרָהָם שָׁב לִמְקוֹמוֹ. מַהוּ לִמְקוֹמוֹ, לְמָקוֹם מָעַלָתוֹ הַיְדוּעָה. ואָז נִסְתָלַק הֲדָיַין וְנִסְתָלַק הַסָינֵגוֹר וְהַקַטֵיגוֹר מֵקַטְרֵג וזֶהוּ (בראשית י״ט:א׳) וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדוֹמָה בָּעֶרֶב וְגוֹ'</p>\n<p>ולוֹט הוּא שָׂטָן הוּא יִצֶּר הָרָע יוֹשֵׁב בְּשָׁעַר סְדוֹם כִּי שָׁם בֵּיתוֹ דִּכְתִיב (בראשית ד׳:ז׳) לַפֶּתַח חַטָאת רוֹבֵץ. וּמִתְחַבֵּר עִם בְּנִי אָדָם וּמַטְעֵה אוֹתָם עַד שְׁמוֹרִידָם לִבְאֵר שָׁחַת וְהוּא גַּם כֵּן עִמָהֵם נִידוֹן עַל שֶׁהִטְעָה אוֹתָם ויוֹרֵד עַד צָּעֲרָה דְגִהֵינָם וזֶהוּ (בראשית י״ט:כ׳) הִנֵּה נָא הָעִיר הֲזֹאת קְרוֹבָה לָנוּס שָׁמָּה. הַרוֹצֵּחַ, הוּא עֵשָׂו שׁוֹפֵךְ דָּמִים וְהִיא מִצְּעַר ואַף עַל פִּי שֶׁיוֹרֶד ונִידוֹן שָׁם עִם כָּל זְה תַאָוַתוֹ וְחֶשְׁקוֹ לַחֲזוֹר וּלְהַטְעוֹת לַאֲחֵרִים וְזְהוּ (בראשית י״ט:ל׳) וַיָּעַל לוֹט מִצּוֹעַר:</p>"],[9520012797,"<p>לְאַבְרָהָם. זִמְנָא חֲדָא נָפַק רַבִּי שִׁמְעוֹן וְחָמָא (וחזא) עַלְמָא דְחַשִׁיךְ וְאַפִיל וְאִסְתַתָם נְהוֹרֵיהּ. אָמַר לֵיהּ לְרַבִּי אֶלְעָזָר, תָּא וְנֶחֱזֵי מָה בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבָּד בְּעַלְמָא. אָזְלוּ וְאַשְׁכָּחוּ חַד מַלְאֲכָא דְּדָמֵי לְטוּרָא רַבְרְבָא וְאַפִּיק תְּלָתִין שַׁלְהוֹבִין דְּנוּרָא מִפּוּמֵיהּ.</p>\n<p>אָמַר לֵיהּ רַבִּי שִׁמְעוֹן מָה אַתְּ בָּעֵי לְמֵעְבָּד. אָמַר לֵיהּ בָּעֵינָא לְמֵחַרְבֵּיהּ לְעַלְמָא בְּגִין דְלָא שְׁכִיחֵי תְּלָתִין זַכָּאִין בְּדָרָא דְהַכִי גָּזָר קוּדְשָׁא בְּרִיךְ הוּא עַל אַבְרָהָם דִּכְתִיב (בראשית י\"ח) הָיוֹ יִהְיֶה בְּגִימַטְרִיָּא תְּלָתִין. אָמַר לֵיהּ רַבִּי שִׁמְעוֹן בְּמָטוּ מִינָךְ, זִיל קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא וְאִימָא לֵיהּ, בָּר יוֹחָאי שָׁכִיחַ בְּאַרְעָא.</p>\n<p>אֲזַל הַהוּא מַלְאֲכָא קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא וְאָמַר לֵיהּ, מָארֵיהּ דְעַלְמָא גָּלֵי קַמָּךְ מָה דְּאָמַר לִי בָּר יוֹחָאי. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא זִיל אֲחַרְבֵיה לְעַלְמָא וְלָא תַשְׁגָּח בְּבַר יוֹחָאי.</p>\n<p>כַּד אֲתָא חַזְיֵיה ר' שִׁמְעוֹן לְמַלְאֲכָא אָמַר לֵיהּ אִי לָא תֵּיזִיל, גּוֹזַרְנָא עֲלָךְ דְלָא תֵּיעוּל לִשְׁמַיָּיא וְתֶּהֱוֵי בַאֲתַר עֲזָא וְעֲזָאֵל וְכַד תֵּיעוּל קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, אִימָא לֵיהּ אִי לֵית תְּלָתִין זַכָּאִין בְּעַלְמָא לֶיהֱוָון עַשְׂרִין דְהַכִי כְּתִיב לא אֱעֶשֶׂה בַּעֲבוּר הַעֶשְׂרִים וְאִי לֵית עֶשְׂרִים לִיהווּ עֲשָׂרָה דְהַכִי כְּתִיב לא אַשְׁחִית בַּעֲבוּר הַעֲשָׂרָה וְאִי לֵית עֲשָׂרָה לֵיהווּ תְרִין דְּאִינּוּן אֲנָא וּבְרִי, דְהַכִי כְּתִיב (דברים י״ט:ט״ו) עַל פִּי שְׁנַיִם עֵדִים יָקוּם דָּבָר, וְאֵין דָּבָר אֶלָּא עוֹלָם דִּכְתִיב (תהילים ל״ג:ו׳) בִּדְבַר יְיָ שָׁמַיִם נַעֲשׁוֹּ. וְאִי לֵית תְרֵין, הַא אִית חַד וַאֲנָא הוּא דִּכְתִיב (משלי י׳:כ״ה) וְצַדִּיק <Nonei></i>יְסוֹד עוֹלָם. בָּהּ שַׁעְתָּא קָל מִן שְׁמַיָּיא נָפַק וְאָמַר, זַכָּאָה חוּלָקָךְ רַבִּי שִׁמְעוֹן. דְּקוּדְשָׁא בְּרִיךְ הוּא גָּזָר לְעֵילָא וְאָתְּ מְבַטֵּל לְתַתָּא בְּוַדַאי עֲלָךְ אִתְמַר (תהילים קמ״ה:י״ט) רָצוֹן יְרֵאָיו יָעֲשֶׂה:</p>"],[9520012798,"<p>מֵחֲמִשִׁים עַד עֲשָׂרָה דְאִיהוּ שֵׁירוּתָא עַד עֲשָׂרָה דְאִיהוּ עֲשָׂרָה סוֹפָא דְּדַרְגִּין וְכֵיוָן דְּמָטָא עַד עֲשָׂרָה אָמַר, מִכָּאן וּלְתַתָּא לָאו אֲתַר לְקַיְימָא בִּתְשׁוּבָה וְתָב וְאָמַר אַרְבָּעִים בְּגִין דְיִשְׁתַזְבוּן ד' קִרְיָין, וְתַב וְאָמַר שְׁלֹשִׁים בְּגִין דְיִשְׁתַזְבוּן ג' קִרְיָין, וְתַב וְאָמַר עֶשְׂרִים בְּגִין דְיִשְׁתַזְבוּן תְרֵין קִרְיָין, וְתָב וְאָמַר עֲשָׂרָה בְּגִין דְיִשְׁתֵזִיב קַרְתָּא חֲדָא מֵאִינוּן חֲמִשָׁה בְּגִינֵי כָּךְ לָא נָחִית לְתַתָּא מִן עֲשָׂרָה:</p>"],[9520012799,"<p>וַיַּשְׁכֵּם אַבְרָהָם בַבֹּקֶר וכו' רַבִּי בְּרוֹקָא אָמַר, מָהוּ שָׂם עַל שִׁכְמָהּ אֶלָּא שֶׁהִזְהִירָה עַל עוֹל הָאֱמוּנָה וְלַעֲמוֹד בְּמָה שֶׁהָיְתָה בַּתְחִילָה כְּתִיב הַכָא שָׂם עַל שִׁכְמָהּ וּכְתִיב הֲתָם (שמותט\"ו) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט. מָה לְהַלָן עַל הַשְׁכִינָה, אוּף הַכָא עַל הַשְׁכִינָה. מָה עֲשְׂתָה כֵּיוָן שְׁרָאֲתָה עַצְמָהּ יוֹצֵאת מִרְשׁוּתוֹ שֶׁל אַבְרָהָם חָזְרָה לְקִלְקוּלָה דִּכְתִיב וְתֵלֵךְ וַתֵּתָע מָהוּ וַתֵּתָע שֶׁתִעְתֵעָה אַחַר עֲבוֹדָה זָרָה וְגִּלּוּלֵי בֵּית אָבִיהָ כְּתִיב הַכָא וַתֵּתָע וּכְתִיב הֲתָם (ירמיהו י׳:ט״ו) הֶבֶל הֵמָּה מַעֲשֶׂה תִּעְתּוּעִים:</p>"],[9520012800,"<p>כָּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו מִכָּל אֲשֶׁר בְּחֲרַבָה מֵתוּ. שָׁאַל רַבִּי חִיָּיא לְר' אַבָּא אֲמַרְתּוּן דְנִשְׁמָתָא לָא עֲיְילָא בְּבַר נָשׁ עַד דְּאִסְתַכְּלָת בְּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּכְדֵין לֵיהֱוֵי לֵיהּ הַהִיא נִשְׁמָתָא. וְאַמְרִיתוּן דְנִשְׁמָתָא הִיא קַדִּישָׁא מַעַלְיָא עַל כֹּלָּא אִם כֵּן מַאי הוּא דְּאָמַר קְרָא כָּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים וְגוֹ', הוֹאִיל וַהֲוָה לְהוּ נִשְׁמָתָא, הֲוָה לְהוּ לְאִשְׁתֵּזָבָא. לָא הֲוָה בִּידֵיהּ.</p>\n<p>אָתוּ שָׁיְילוּהָ לְר' אֶלְעָזָר בְּרַבִּי שִׁמְעוֹן אָמַר לְהוּ כַּךְ הוּא, וְהָא קְרָא מְסַיֵּיעַ לֵיהּ דְהַכִי אָמַר אֲבוֹי (אבא), דְכִי אֲתָא טוֹפָנָא לָא חַזָא (הוה) בָּר נָשׁ דְּיַעֲבִיד קוּדְשָׁא בְּרִיךְ הוּא בְּגִינֵיהּ, אֶלָּא נֹחַ. וּזְכוּתֶיהּ לָא הֲוָה אֶלָּא לְאַגָּנָא עֲלֵיהוֹן וְעַל בָּתֵיהוֹן דְלָא הֲוָה זְכוּתֵיהּ כָּל כַּךְ לְאַגָּנָא עַל כָּל דָרָא</p>\n<p>וְאִינּוּן דַהֲווּ זַכָּאִין בְקַדְמִיתָא כְּגוֹן חֲנוֹךְ יֶרֶד דַהֲווּ לְהוּ נִשְׁמְתָא קַדִּישָׁא, וְחַזְיָּיאן לְמֶעְבָּד קוּדְשָׁא בְּרִיךְ הוּא בְּגִינֵיהוֹן בְּחַרְבָּא מֵתוּ. וְהַיְינוּ דְּאָמַר כָּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו אִינוּן דְנִשְׁמַתָא קַדִּישָׁא הֲוָה בְּהוֹן וְלָא תֵימָא דְעַל אִינוּן דַהֲווּ בְּטוֹפָנָא אָמַר, אֶלָּא אֲתָא קְרָא וְאָמַר מִכָּל אֲשֶׁר בְּחֲרַבָה מֵתוּ:</p>"],[9520012801,"<p>אוֹסְרִי לַגֶּפֶן עִירֹ\"ה וְלַשׂוֹרֵקָ\"ה בְּנִי אֲתוֹנוֹ כִּבֵּס בָּיַיִן לְבוּשׁוּ וּבְדַם עֲנָבִים סוּתֹה. תְמַנְיָא דַרְגִּין כְּלִילָן בְּהָאי קְרָא. אַרְבַּע מִנְּהוֹן דַּמְיָין אַהֲדָדֵי, תְרֵין מִנְּהוֹן דַּמְיָין אַהֲדָדֵי, וּתְרֵין אָחֳרָנִין דַּמְיָין אַהֲדָדֵי. אַרְבַּע דְּדַמְיָין אַהֲדָדֵי אִינוּן גֶּפֶן שׂוֹרֵקָה, הַיְינוּ גֶּפֶן הַיְינוּ שׂוֹרֵקָה דְּמִנְהוֹן נָפְקִין עֲנָבִים וּמִנְהוֹן מִתְעֲבִיד חַמְרָא דְאִיקְרֵי יַּיִן וְכֻלְּהוּ רָזָא חֲדָא וּמִשָׁרְשָׁא חַד נָפְקִין וְנַגְדִּין. וּתְרֵין דְּדַמְיָין אַהֲדָדֵי עִירֹה אֲתוֹנוֹ, הַיְינוּ עִירֹה הַיְינוּ אֲתוֹנוֹ וְרָזָא חֲדָא נִינְהוּ וּבְדַרְגָּא חֲדָא כְּלִילָן וּמְרָזָא חֲדָא נַגְדִּין.</p>\n<p>לְבוּשׁ\"וֹ סוּתֹ\"ה הַיְינוּ מִלָּה חֲדָא וְרָזָא חַדָא (שמות כ\"ג) כִּי הִיא כְּסוּתוֹ לְבַדָּהּ הִיא שִׂמְלָתוֹ לְעוֹרוֹ. זִמְנָא קַרְיֵיהּ כְּסוּת וְזִמְנָא אַחֲרָא קַרְיֵיהּ לְבוּשׁ וְזִמְנָא אַחֲרָא קַרְיֵיהּ שִׂמְלָה וְכֻלְּהוּ מִשָׁרְשָׁא חֲדָא נַגְדִּין וּמִלָּה חֲדָא עָבְדִין וְחִלוּפָא דִּשְׁמָהָן רָזִין עִלָּאִין כְּלִילָן בְּהוּ, וּמָאן דְדָיִיק טַעִים מִידִי. וּמָאן דְלָא דָיִיק, לָא טַעִים וְלָא מִידִי. וְהָנִי תְמַנְיָא דַרְגִּין רָזִין עִלָּאִין רְמִיזִין בְּהוּ, אֲבָל קְרָא בִּפְשָׁטֵיה קָאֵי.</p>\n<p>תָּא חֲזֵי, יַעֲקֹב שְׁלֵימָא דְאַבָּהָן הֲוָה, כְּמָא דְאַתְּ אָמֵר (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם וְגוֹ' מַאי אִישׁ תָּם דְּאִשְׁתַּכְלַּל מֵחָכְמָתָא דִלְעֵילָא וּמְחָכְמָתָא דִלְתַתָּא וְהַיְינוּ דִכְתִיב יוֹשֵׁב אֹהָלִים, תְרֵין אֹהָלִים נִינְהוּ. אֹהֶל דְאִיקְרֵי לְפָנִים מִן הַפַּרְגּוֹד וְאֹהֶל דְאִיקְרֵי אֲחוֹרֵי הַפַּרְגּוֹד וְכַלִיל הֲוָה מִתְּרֵין סִטְרִין, מִבָּתֵּי גָּוָאי וּמִבָּתֵּי בָּרָאי</p>\n<p>וּמָאן אוֹלִיף לֵיהּ לְיַעֲקֹב כּוּלֵי הַאי. תָּא חֲזֵי דְּהָא אִינוּן שָׁנִי דַהֲוָה טָמִיר וְגָנִיז בַּהֲדַיְיהוּ דְשֵׁם וְעֵבֶר, שֵׁם אוֹלִיף לֵיהּ חָכְמָתָא עִלָּאָה דְּבָתֵּי גָּוָאי. וְעֵבֶר אוֹלִיף לֵיהּ חַרָשָׁתָא (ס\"א חכמתא) תַתָּאָה וְסִימָנִיךְ (יהושע כ״ד:ב׳) בְּעֵבֶר הַנָהָר יַשְׁבוּ אֲבוֹתֵיכֶם מֵעוֹלָם.</p>\n<p>מַאי בְּעֵבֶר הַנָהָר אֶלָּא רָזָא הוּא דְכָל יוֹמֵיהוֹן דְּאִינּוּן קַדְמָאֵי לָא הֲווּ אוּלִיפָן אֶלָּא חָכְמָתָא תַתָּאָה דְּאַתְיָיא מִבָּתֵּי בָּרָאי דְאִיקְרֵי אֲחוֹרֵי הַפַּרְגּוֹד וּבְאִינוּן דְאֲחוֹרֵי הַפַּרְגּוֹד הֲווּ מִתְדַּבְּקִין וַהֲווּ מוֹדִיעִין לוֹן מִילִין דַּעֲתִידִין לְמֵיתֵי לְעַלְמָא בִּישׁ אוֹ טָב וּכְדֵין הֲווּ כָּל אִינוּן דָרִין</p>\n<p>עַד דְּאָתָא הַהוּא סִטְרָא דִקְדוּשָׁא עִלָּאָה וְאֲמְשִׁיךְ לֵיהּ לְאַבְרָהָם וְאוֹדָע לֵיהּ מִלִּין דְשָׁרְשָׁא דְאִתְמָשֶׁכָאן לְעַלְמָא דִלְהוֹן (מנהון) מִבָּתֵּי גָּוָאי וּמִתַּמָן שֹׁאֲבִין כָּל אִינוּן דְאִקְּרוּן בָּתֵּי בָּרָאי וּמִתַּמָן מִתֶהוָון קְצָת מִילִין לָא כֹּלָּא, וְסִימָנִיךְ מִתַּמְצִית גּוּפָה שֶׁל אֶרֶץ יִשְׂרָאֵל הָעוֹלָם שׁוֹתֵה.</p>\n<p>וּמֵהָאי שַׁעְתָּא דְּקָאִים אַבְרָהָם אָבִינוּ <Nonei></i>עָלָיו הַשָׁלוֹם עַל הַהוּא סִטְרָא קַדִּישָׁא דְּמִינֵּיהּ כוּלָא נָפִיק וְנָגִיד וּבֵיהּ כֹּלָא תַלְיָין נָפַק לֵיהּ לְשָׁעֲתֵיה מֵהַאי סִטְרָא דְּאִינּוּן בְּנֵי עֵבֶר הַנָהַר וְאָתָא לֵיהּ לְאִשְׁתַּעְשְׁעָא בְּאַרְעָא קַדִּישָׁא. הָדָא הוּא דִּכְתִיב, (יהושע כ״ד:ג׳) וַאֵקָח אֶת אֲבִיכֶם אֶת אַבְרָהָם מֵעֵבֶר הַנָהָר וָאוֹלֶךְ אוֹתוֹ בְּכָל אֶרֶץ כְּנָעַן אֶרֶץ כְּנָעַן מַמָּשׁ אַרְעָא דִּשְׁאָר חֲיָילִין עִלָּאִין תְבִירִין תְּחוֹתָהּ תַמָּן וְלֵית לְהוֹן קִיוּמָא בַּהֲדָהּ:</p>"],[9520012802,"<p>וְשָׁחֲטוּ הַפֶּסַח אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא מִבְּעֲשוֹר לַחֹדֶשׁ סְבוּ דַחֲלָא דְמִצְרָיִם וְתִפְסוּן לֵיהּ וְיְהֵא אָסוּר וְתָפִיס תְלָתָא יוֹמִין וּבְיוֹמָא רְבִיעִאָה אַפִּיקוּ לֵיהּ לְדִינָא וְאִתְכְּנָשׁוּ עָלֵיהּ לְקַטְלֵיהּ, וְיֵחְמוּן לֵיהּ מִצְרָאֵי הֵיךְ אָתּוּן עַבְדִין בֵּיה דִּינָא. וְדָא קַשְׁיָא לְהוּ מִכָּל מַכְתָּשִׁין דְּעָבַד לוֹן קוּדְשָׁא בְּרִיךְ הוּא, אִינוּן דִינִין דְּעָבְדוּ בְּדָחַלֵיהוֹן.</p>\n<p>לְבָתַר דָיְינִין לֵיהּ בְּנוּרָא בְּגִין דִּכְתִיב (דברים ז׳:כ״ה) פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֶשׁ. אָמַר קוּדְשָׁא בְּרִיךְ הוּא (שמות י״ב:ט׳) אַל תֹאכְלוּ מִמֶּנּוּ נָא, דְלָא יֵימְרוּן בְתִיאוּבְתָּא דְּדָחַלָא אַכְלִין לֵיהּ, אֶלָּא אַתְקִינוּ לֵיהּ צְלִּי וְלֹא מֵבוּשָׁל דְאִילוּ מֵבוּשָׁל יְהֵא טָמִיר וְלָא יְחְמוּן לֵיהּ, אֶלָּא תַקִּינוּ לֵיהּ מוֹקְדָא בְּנוּרָא דְרֵיחֵיהּ נוֹדֶף.</p>\n<p>וְתוּ רֵישֵׁיהּ עָלֵיהּ, דְלָא יֵימְרוּן דְּחַיָּה אוֹ דְמִלָה אַחֲרָא הִיא. וְתוּ עֶצֶם לֹא תִשְׁבֶּרוּ בּוֹ, אֶלָּא דְיֵחְמוּן גָּרְמוֹי רָמָאן בְּשׁוּקָא וְלָא יַכְלִין לְשֵׁזָבָא לֵיהּ וְעַל דָּא כְּתִיב (במדבר ל״ג:ד׳) וּבֵאלֹהֵיהֶם עָשָׂה יְיָ שְׁפָטִים.</p>\n<p>הַהוּא קַדְמָאָה דְאִשְׁתַּכַּח בְּבֵי כְּנִישְׁתָּא וְאָרִיךְ בְּבֵי כְּנִישְׁתָּא זַכָּאָה חוּלָקֵיהּ דְּאִיהוּ קַיָימָא בְּדַרְגָּא דְצַדִיק בַּהֲדֵי שְׁכִינְתָּא, וְדָא אִיהוּ רָזָא (משלי ח׳:י״ז) וּמְשָׁחַרָי יִמְצָאוּנְנִי, דָּא סָלִיק בִּסְלִיקוּ עִלָּאָה. וְאִי תֵימָא הַא תָנֵינָן בְּשַׁעְתָּא דְאָתֵי קוּדְשָׁא בְּרִיךְ הוּא לְבֵי כְּנִישְׁתָּא וְלָא אַשְׁכָּח תַמָּן עֲשָׂרָה מִיָד כּוֹעֵס.</p>\n<p>לְמַלְכָּא דְשָׁלַח לְכָל מַלְכֵי (ס\"א אנשי) מְדִינְתָּא דְּיִשְׁתַּכְּחוּן עִמֵּיהּ בְּיוֹם פְּלַן בְּדוּךְ פְּלַן. עַד דַהֲווּ מְזָמְנֵי גַרְמַיְיהוּ אִינוּן בְּנֵי מַתָּא אַקְדִים חַד וְאָתָא לְהַהוּא אֲתַר בֵּין כַּךְ וּבֵין כַּךְ אֲתָא מַלְכָּא אַשְׁכָּח לְהַהוּא בָּר נָשׁ דְאַקְדִּים תַמָּן. אָמַר לֵיהּ בְּנֵי מַתָּא פְּלוֹנִית אָן אִינוּן. אָמַר לֵיהּ, מָארֵי, אֲנָא אֲקְדִימְנָא מִנַּיְיהוּ וְהָא אִינוּן אַתְיָין אֲבַתְרָאי לְפִקוּדָא דְמַלְכָּא. כְּדֵין טָב בְּעֵינֵי מַלְכָּא וְיָתִיב תַמָּן בַּהֲדֵיהּ וּמִשְׁתָּעֵי עִמֵּיהּ וְאִתְעֲבִיד רְחִימָא דְמַלְכָּא. בֵּין כַּךְ אָתוּ כָּל עַמָּא וְאִתְפַּיָּיס עִמָיְיהוּ. אֲבָל אִי בְנֵי מַתָּא לָא אַתְיָין וְחַד לָא אַקְדִים וְאִשְׁתָּעֵי קַמֵי מַלְכָּא לְאַחֲזָאָה (לאתחזאה) בְּגִינֵהוֹן. מִיָד כַּעָס מַלְכָּא. מָה כְּתִיב (ישעיהו נ׳:ב׳) מַדּוּעַ בָּאתִי וְאֵין אִישׁ.</p>\n<p>וּמָאן דְּאִשְׁתָּעֵי בְּבֵי כְּנִישְׁתָּא וַוי לֵיהּ דְּאַחְזֵי פִּרוּדָא. וַוי לֵיהּ דְּגָרַע מְהֵימְנוּתָא, וַוי לֵיהּ דְּלֵית לֵיהּ חוּלָקָא בֶּאֱלָהָא דְּיִשְׂרָאֵל דְּאַחְזֵי דְּלֵית לֵיהּ אֱלָהָא. וְלָא אִשְׁתְּכַח תַמָּן, וְאַנְהִיג קְלָנָא בְּתַּקִּיפָא עִלָּאָה.</p>\n<p>כָּל גּווָֹנִין טָבִין בְּחֶלְמָא בָּר מִתְכֵלָא בְּגִין דְאִיהוּ כּוּרְסַיָּיא לְמֵידָן דִינִין דְּנִשְׁמָתִין וְהָא דַרְגָּא חֲדָא אִיהוּ. אֶלָּא בְּשַׁעְתָּא דְּקַיְימֵי בְּדִינֵי נַפְשָׁא כְּדֵין אִיהוּ גּווָֹן תְכֵלָא וְהָא אוּקִימְנָא. וּבְשַׁעֲתָא דְּחָמֵי בָּר נָשׁ לְהַאי גּווָֹן אִדְכַּר בָּר נָשׁ לְמֶעְבָּד פִקוּדָא דְּמָארֵיהּ כְּגווָֹנָא דְנָחָשׁ דַהֲווּ חֲמָאן לֵיהּ וַהֲווּ דַּחֲלֵי מִקָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא וּמְנַטְרִין גַרְמַיְיהוּ, וּבְהַהוּא דְּחִילוּ דְּקוּדְשָׁא בְּרִיךְ הוּא סַלְקָא עָלַיְיהוּ מַיָא וְאִתְכַסְּיָין. מָאן גָרַם לוֹן, הַהוּא נָחָשׁ, הַהוּא רְצוּעָה דְּמִסְתָּכְּלָאן בֵּיה אוּף הֲכִי תְּכֵלֶת וּרְאִיתֶם אוֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְוֹת יְיָ מֵהַהוּא דְּחִילוּ דִילֵיהּ: (עד כאן מההשמטות)</p>"],[9520012803,"<p>תָּא חֲזֵי הַאי הַר לִישָׁנָא דְּתַקִיפוּ הוּא. אִינוּן הָרִים לְעֵילָא וְאִלֵּין צַדִּיקִים דַאֲחִידָן בְּכְּנֶסֶת יִשְׂרָאֵל וְאִקְּרוּן הַר צִיּוֹן הָרִים דְסָחְרָנֵי יְרוּשָׁלַיִם בְּגִין דְּאִינּוּן מְצוּיָינִין וְאָמְרִין הָאי לְהָאי בְּסִטְרָא דְּיִחוּדָא לִשְׁפּוֹט אֶת הַר עֵשָׂו דְּקַטְרִיגּוּ מְקַטְרְגָא מִסִּטְרָא דִשְׂמָאלָא</p>\n<p>בְּהַהוּא זִמְנָא (עובדיה א׳:כ״א) וְהָיְתָה לַיְיָ הַמְלוּכָה. בְּקַדְמִיתָא אִקְרֵי מַמְלָכָה בְּגִין דְיַנְקָא לִתְרֵין סִטְרִין לִימִינָא וְלִשְׂמָאלָא. וְהַשְׁתָּא מְלוּכָה אִקְרֵי בְּגִין דְיַנְקָא לִימִינָא. הֲדָא הוּא דִּכְתִיב (הושע ב׳:כ״א) וְאֱרָשְׂתִּיךְ לִי לְעוֹלָם. וּבְגִין דְגַלוּתָא לָאו לְעוֹלָם הוּא דְהָא יַתְבָא בְּגָלוּתָא.</p>\n<p>תָּא חֲזֵי דְסָמִיךְ לֵיהּ (זכריה י״ד:ט׳) וְהָיָה יְיָ לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיוֹם הַהוּא יִהְיֶה יְיָ אֶחָד וּשְׁמוֹ אֶחָד בְּגִין דְּעַד הַשְׁתָּא כַּד יִשְׂרָאֵל בְּגָלוּתָא שְׁכִינְתָּא עִמְּהוֹן וּמַלְכָּא בְּלֹא מַטְרוֹנִיתָא לָאו מַלְכָּא אִיהוּ. אֲבָל הַהוּא זִמְנָא וְהָיָה יְיָ לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיוֹם הַהוּא יִהְיֶה יְיָ אֶחָד וּשְׁמוֹ אֶחָד, כַּד אִתְדַבְּקַת שְׁכִינְתָּא בְּצַדִיק כְּדֵין הוּא יִחוּדָא</p>\n<p><Nonei></i>דְהַכִי אוֹלִיפְנָא בְּרָזָא דִּקְרִיָת שְׁמַע דְּבָעֵי בָּר נָשׁ לְיַחֲדָא לְמָארֵיהּ וּלְקַשְׁרָא קִשְׁרִין דִמְהֵימְנוּתָא בִּרְעוּתָא דְלִבָּא. וְכַד מָטֵי לְאֶחָד אִבָּעֵי לֵיהּ לְכַוְונָא בְּא' סְתִימָא עַתִּיקָא (ס\"א עמיקא) דְּכֹלָּא וְח' תְמַנְיָא דַרְגִּין עִלָּאִין מֵחָכְמָה עִלָּאָה עַד צַדִּיק. וְד' רַבְּתָא אִתְדַבְּקוּתָא דְּכְּנְסֵת יִשְׂרָאֵל דְאִיהִי חוּלָקֵיהּ דְדָוִד דְאִקְּרֵי עָנִי וְאֶבְיוֹן כַּד אִתְדַּבְּקַת לְאִינוּן דַרְגִּין דִלְעֵילָא דִּרְמִיזִין בְּא\"ח. כְּדֵין אִיהִי רַבְּתָא וְעָלְמָא כּוּלֶיהּ יָנִיק מִינָהּ וְאִינּוּן שָׁדַיִם דְּאִינּוּן (שיר השירים ח׳:י׳) כַּמִּגְדָּלוֹת אָז הָיִיתִי בְּעֵינָיו כְּמוֹצֵאת שָׁלוֹם.</p>\n<p>תָּא חֲזֵי הָאי קְרָא עַל כְּנֶסֶת יִשְׂרָאֵל אִתְמַר כַּד אִיהִי בְּגָלוּתָא עִם בְּנָהָא בֵּין אוּמִין דְעַלְמָא אִקְרֵי זְעִירָא הֲדָא הוּא דִּכְתִיב (שם) אָחוֹת לָּנוּ קְטַנָּה וְעַד יִשְׂרָאֵל אִתְדַבָּרוּ בְּאוֹרַיְיתָא וְאַזְלִין בְּאֹרַח קְשׁוֹט כְּדֵין אִתְמָלְיָּיא וְשָׁלוֹם אִתְחַבָּר בְּהוּ. אֲתִיבַת אִיהִי וְאַמְרַת אֲנִי חוֹמָה וְשָׁדַי כַּמִּגְדָּלוֹת. בְּהַהוּא זִמְנָא דְאִתְחַבַּר עִמִי אָ\"ז וְשָׁלוֹ\"ם. א' רָזָא דְעַתִּיקָא קַדִּישָׁא דְכֹלָא, ז' שֶׁבַע דַרְגִּין וְשָׁלוֹ\"ם דְאִקְּרֵי צַדִּי\"ק כֵּיוָן דְּהָנֵי דַרְגִּין מִתְחַבְּרָן כְּדֵין אָ\"ז הֲיִיתִּי בְּעֵינָיו כְּמוֹצֵאת שָׁלוֹם. וּמָאן עַיְינִין. אִינוּן ז' דַרְגִּין דְּאִקְרוּן עֵינֵי יְיָ, פְּנֵי יְיָ, וּכְדֵין שְׁלָמָא לְעַלְמָא וְשַׁרְיָיא טִיבוּ דְעַתִּיקָא בַּאֲתַר דְּדַכָר וְנוּקְבָא וּבְגִין כָּךְ פַּקָּד מֹשֶׁה בְּאוֹרַיְיתָא וְאָמַר (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ אֱלהֵינוּ יְיָ אֶחָד. לְקַשְׁרָא כּוּלְהוּ קִשְׁרִין דִמְהֵימְנוּתָא.</p>\n<p>תָּא חֲזֵי, כָּל הַמַאֲרִיךְ בְּאֶחָד מָאֲרִיכִין לוֹ יָמָיו וּשְׁנוֹתָּיו. מַאי טַעְמָא בְּגִין דְאִיהוּ אֲתַר דְכָל יוֹמִין וּשְׁנִין דְעַלְמָא בֵּיה תַלְיָין בְּרָזָא דְּאִינּוּן דַרְגִּין דִּרְמִיזִין בְּאֶחָד וְאִינּוּן עֲשָׂרָה וְכֻלְּהוּ חַד וְאִתְעָרוּ בֵּיה חַבְרַיָּיא וְאָמְרוּ בדל\"ת וְשַׁפִּיר. בְּגִין דְּהָאי אַתְרָא דְּדל\"ת הִיא וְלֵית לָה נְהוֹרָא מִדִּילֵיהּ. וּבָעֵי בָּר נָשׁ לְאַרָכָא בָּהּ וּלְאַמְשָׁכָא לָה בִּרְכָאָן מֵאִינוּן שִׁית סִטְרִין שִׁית בְּנִין עִלָּאִין עַל יְדֵי דְצַדִיק</p>\n<p>וְאִינּוּן שִׁית סִטְרִין רְמִיזִין בח' בְּרָזָא דִּתְמָנְיָיא. שִׁית אִלֵּין וּתְרֵין לְעֵילָא חָכְמָה וּבִינָה אַבָּא וְאִימָא לְאוֹסָפָא וּלְאַכְלָלָא לְהוּ לְעֵילָא, וּלְמֵיהַב לְהוּ בִּרְכָאָן מֵאַבָּא וְאִימָא עִלָּאָה. דְהָא לָא שַׁרְיָיא טִיבוּ דְעַתִּיקָא אֶלָּא בַּאֲתַר דְשָׁלִים, בַּאֲתַר דְאִשְׁתַּכַּח דְכַר וְנוּקְבָא. הֲדָא הוּא דִכְתִיב (שיר השירים ג׳:י״א) צְאֵינָה וּרְאֵינָה בְּנוֹת צִיּוֹן בַּמֶלֶךְ שְׁלֹמֹה וְגוֹ' בְּיוֹם חֲתוּנָתוֹ וְגוֹ'. בְּיוֹם חֲתוּנָתוֹ דַּיְיקָא.</p>\n<p>וְעַל דָּא אֲמְרוּ וּבִּלְבַד שֶׁלֹּא יַחְטוֹף בַחי\"ת אֶלָּא בָּעֵי לְאַמְשָׁכָא בִּרְכָאָן מֵאֲתַר עִלָּאָה דְכוֹלָא. וּלְאַרָקָא בְּאִינוּן שִׁית בְּנִין. לְבָתָר לְהַאי בַּת דְּלֵית לָה אַחֲסָנָא בְּבֵית אֲבוּהָ וְאִימָא אֶלָּא הַאי בְּרָא. וּמִכָּאן אוֹלִיפְנָא דִּבְרָא יָרִית לְאַבָּא וּלְאִימָא וּבְרַתָּא לָא, אֶלָּא דְּאִית לָה מְזוֹנֵי מִן בְּרָא אֶלָּא בָּעֵי לְאַרָכָא בְּהָאי דל\"ת.</p>\n<p>וְתַמָּן אַמְרֵי כַּמָה בָּעֵי בָּר נָשׁ לְאַרָכָא בַּהּ, כְּשִׁיעוּרָא דְיַמְלִיךְ יָתָהּ לְעֵילָא וּלְתַתָּא וּלְאַרְבַּע זִוְויָין דְעַלְמָא, רָזָא דְשִׁית סִטְרִין עִלָּאִין דְכֻלְּהוּ יִתְחַבְּרוּן עִמָּהּ וְלָא יִתְפָּרְשׁוּן לְעָלְמִין. וְכַד בָּר נָשׁ מַאֲרִיךְ בְּהָאי כָּל אִינוּן יוֹמִין וּשְׁנִין עִלָּאִין מוֹסְרִין בִּרְכָאָן עַל רֵישֵׁיהּ וְקוּדְשָׁא בְּרִיךְ הוּא קָרֵי לֵיהּ (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אַתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאַר.</p>\n<p>תָּא חֲזֵי כְּלָלָא דְאוֹרַיְיתָא בְּהָאי קְרָא רְמִיזִין וּכְלָלָא דְכָל אִינוּן אֲמִירָן דְּאִתְבַּרֵי בְּהוֹן עַלְמָא בְּאֶחָד רְמִיזִין הֲדָא הוּא דִכְתִיב (איוב כ״ג:י״ג) וְהוּא בְּאֶחָד וּמִי יְשִׁיבֵנוּ וְנַפְשׁוֹ אִוְתָהּ וַיַעֲשׂ. וּבְהוֹן אִתְבְּרֵי עַלְמָא וְעַל דָּא תָנֵינָן בַּעֲשָׂרָה מַאֲמָרוֹת נִבְרָא הָעוֹלָם וְכוּ' וְאוֹקִימְנָא דְּכוּלְהוּ י' וְכֻלְּהוּ כְּלִילָן בְּקְרָא קַדְמָאָה דְאוֹרַיְיתָא:</p>"],[9520012804,"<p>בְּרֵאשִׁית רָזָא דְחָכְמָ\"ה. בָּרָא. עִלָּאָה סְתִימָא דְלָא אִתְיְּידָע (כתר) אֱלֹהִי\"ם בִּינָ\"ה. אֶ\"ת כְּלָלָא דְּחֶסֶ\"ד וּגְבוּרָ\"ה. הַשָׁמַיִם תִפְאֶרֶ\"ת וְאֶ\"ת כְּלָלָא דְּנֶצַ\"ח וְהוֹ\"ד. וא\"ו דְּוְאֶת לְאַכְלָלָא צַדִּי\"ק. הָאָרֶץ כְּלָלָא דְּכְּנְסֵת יִשְׂרָאֵל אֶרֶץ הַחַיִּים וּבָתַר פְּרָטָא דְאוֹרַיְיתָא בְּרָזָא דְּאִינּוּן יוֹמִין עִלָּאִין. בְּרֵאשִׁית מַאֲמָר הוּא לָקֳבֵל דַרְגָּא דְחָכְמָ\"ה וְאִקְרֵי רֵאשִׁית.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר לָקֳבֵל דַרְגָּא דְּחֶסֶ\"ד דְאִיהוּ לִימִינָא. דְהָא מִתַּמָּן נָפִיק נְהוֹרָא לְכֻלְּהוּ עָלְמִין בְּרָזָא דְיוֹם, הֲדָא הוּא דִכְתִיב (תהילים נ״ב:ג׳) חֶסֶד אֵל כָּל הַיּוֹם וּלְקֳבְלֵיהּ לְתַתָּא אַבְרָהָם דְאֲחִיד בְּהָאי חוּלָקָא. וּבְגִין כָּךְ כְּתִיב הָכָא יוֹם אֶחָד, וְהָכָא (יחזקאל לג) אֶחָד הָיָה אַבְרָהָם וּבֵיהּ כְּתִיב (ישעיהו מ״א:ב׳) מִי הֶעִיר מִמִּזְרָח בְּרָזָא דְּאוֹר דְנָפִיק מִמִּזְרָח.</p>\n<p>וְתָא חֲזֵי לָא תִשְׁכַּח בְכֻלְּהוּ ז' זַכָּאִין דַאֲחִידָן לְעֵילָא בְּרָזָא דִשְׁמָהַתְהוֹן בְּשֵׁירוּתָא אָלֶף אֶלָּא אַבְרָהָם וְאַהֲרֹן דַאֲחִידָן בְהָאי חֶסֶ\"ד דְהָא כֹּהֲנִים מִסִּטְרָא דְחֶסֶ\"ד אָתוּ. וְאַף עַל גַּב דְאֲחִיד אַהֲרֹן בְּהוֹד, בְּחֶסֶ\"ד נָמֵי אֲחִיד וּמֹשֶׁה אַף עַל גַּב דְאֲחִיד בְּנֶצַח, בְּתִפְאֶרֶת נָמֵי אֲחִיד. לְאַחֲזָאָה דְכוֹלָא חַד וְאַבְרָהָם רֵישָׁא לְכֻלְּהוּ זַכָּאִין וּמִנֵּיהּ אִתַּפְרָשׁוּ לְתַתָּא <Nonei></i>דְאִיהוּ לִימִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא וְאִקְרֵי כֹּהֵן הֲדָא הוּא דִכְתִיב (תהילים ק״י:ד׳) אַתָּה כֹּהֵן לְעוֹלָם עַל דִּבְרָתִי מַלְכִּי צֶדֶק. וְאַהֲרֹן בְּגִין דְאִיהוּ כֹּהֵן אֲחִיד בְּהָאי, אֲבָל דַרְגָּא דִילֵיהּ הוֹ\"ד אִיהוּ:</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל וְכוּ' לָקֳבֵל דַרְגָּא דִּגְבוּרָ\"ה דְאֲחִיד תַמָּן יִצְחָק וּלְקִבְלֵיהּ תִפְאֶרֶת (ס\"א לקבליה. תא חזי) מַיָא אוֹלִידוּ אֶשָׁא בְּגִין כָּךְ יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל. וּבְגִין כָּךְ לְתַתָּא אַבְרָהָם הוֹלִיד אֶת יִצְחָק (ובההוא יומא) וּבְיוֹמָא הַהוּא אִתְבְּרֵי גֵּיהִנָם דְנָפִיק מֵהַהוּא אֶשָׁא תַקִּיפָא בְּהַהוּא מַחֲלוֹקֶת וּבְגִין כָּךְ הַהוּא יוֹמָא, יוֹמָא דְדִינָא:</p>\n<p>וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמָּיִם לָקֳבֵל דָא דַרְגָּא דְּתִפְאֶרֶ\"ת דְאִקְּרֵי קַו הָאֶמְצָעִי וּלְקִבְלֵיהּ דְיַעֲקֹב דְאִיהוּ תְּלִיתָאֵי וְנָטִיל תְרֵין חוּלָקִין בְּהַהוּא דְּאֵשׁ וּמַיִם (דאש השמים) מִשָׁמַיִם וּלְקִבְלֵיהּ יוֹם תְּלִיתָאֵי וְעַל דָא דְאִקְּרֵי יַעֲקֹב (בראשית כ״ה:כ״ז) אִישׁ תָּם יוֹשֵׁב אֹהָלִים. שְׁלִים בְּכוֹלָא. שְׁלִים בְּחֶסֶד. שְׁלִים בְּדִינָא. שְׁלִים בְּמַיָּא שְׁלִים בְּאֶשָׁא. יוֹשֵׁב אֹהָלִים תְרֵין, חֶסֶ\"ד וּגְבוּרָ\"ה וְנָטִיל כֹּלָּא וְאִתְעֲבִיד בִידֵיהּ רַחֲמִין:</p>\n<p>וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע עֵץ פְּרִי וְגוֹ'. דַּרְגָא דְּצַדִּיק דְּאִקְרֵי עֵץ הַחַיִּים וְאִיהוּ עוֹשֶׂה פְּרִי, דְּהָא לֵית בְּכֻלְּהוּ דְּיַעֲבִיד פֶּרִי בָּר אִיהוּ. זַרְעוֹ בּוֹ עַל הָאָרֶץ דַּיְיקָא. וּלְקִבְלֵיהּ לְתַתָּא (בראשית מ״ט:כ״ב) בֵּן פּוֹרָת יוֹסֵף בֵּן פּוֹרָת עֲלֵי עַיִן. וְאִקְרֵי בְּרִית שְׁלָמָא.</p>\n<p>וּבְגִין כָּךְ תְּרֵי זִמְנֵי בְּהַאי יוֹמָא כִּי טוֹב, חַד לְקֳבֵל דַּרְגָא דְּתִפְאֶרֶ\"ת וְחַד לְקֳבֵל דַּרְגָא דְּצַדִּיק דְּאִיהוּ יוֹמָא דְשַׁבְּתָא דִּלְעֵילָא וְעֲבִידְתָּא אַחֲרָא לֵית בֵּיהּ אֶלָּא זִווּג לְאַפָּקָא פֶּרִי נִשְׁמָתִין לְעָלְמָא, פֶּרִי עוֹבָדוֹי דְקוּדְשָׁא בְּרִיךְ הוּא. הָכִי נָמֵי לְתַתָּא דְּזִווּגָא שָׁרֵי בֵּיהּ מִשַׁבָּת לְשַׁבָּת.</p>\n<p>תָּא חֲזֵי רָזָא עִלָּאָה דְּאוֹרַיְיתָא, מַאי עֵץ פֶּרִי עוֹשֶׂה פֶּרִי, לְקֳבֵל יוֹמָא דְשַׁבְּתָא אִיהוּ. ומַאי טַעְמָא אִתְכְּלִיל בְּיוֹם תְּלִיתָאִי, רָזָא עִלָּאָה אִיהוּ. בְּגִין דְּתָנֵינָן רִבִּי שִׁמְעוֹן בֵּן יוֹחָאי אוֹמֶר מַאי טַעְמָא כְּתִיב בְּאוֹרַיְיתָא (דברים כ״ד:א׳) כִּי יִקַּח אִישׁ אִשָּׁה וְלָא כִּי תִּלָקַח אִשָּׁה לְאִישׁ בְּגִין דְּאֹרְחֵיהּ דְּבַּר נָשׁ לְאָהַדְּרָא וּלְמִתְבַּע אִנְתּוּ. מְתַל לְבַּר נָשׁ דְּאִתְאֲבִיד לֵיהּ אַבֵדַתָא מָארֵי דְּאַבֵדַתָא מֵחַזֶר לְמִתְבַּע אַבֵידַתָא דִילֵיהּ,</p>\n<p>וְהַאי צַדִּיק אִישׁ אִקְרֵי. הֲדָא הוּא דִכְתִיב (בראשית מ״ג:י״א) וְהוֹרִידוּ לָאִישׁ מִנְחָה כְּדְּאוֹקִימְנָא. וכְּנֶסֶת יִשְׂרָאֵל דִּרְמִיזָא בְּיוֹם רְבִיעָאִי בְּרָזָא דִמְאֹרֹת חָסֵר סַמְכָא רְבִיעָאָה מַלְכוּתָא דְדָוִד. בְּגִין כָּךְ אַף עַל גַּב דְּאַתְרֵיהּ דְּהַאי צַדִּיק יוֹמָא דְשַׁבְּתָא אִתְכְּלִיל וְאִתְרְמִיז בְּיוֹמָא תְּלִיתָאִי לְמֶהֱוֵי סָמִיךְ לְיוֹם רְבִיעָאִי וְאִיהוּ אִנְתּוּ דִילֵיהּ בְּגִין כָּךְ מָארֵיהּ דְּאַבֵידַתָא מֵחַזֶר עַל אַבֵדָתוֹ וּבְגִין כָּךְ כְּתִיב לְתַתָּא (בראשית מ״ב:ו׳) וְיוֹסֵף הוּא הַשָׁלִיט עַל הָאָרֶץ.</p>\n<p>אֲבָל בְּזִמְנָא דְאָתֵי דְּאִיהוּ בְּאַחֲרִית הַיָּמִים בְּיוֹם שְׁתִיתָאִי דְּאִיהוּ אַלְפָא שְׁתִיתָאָה כַּד יֵיתֵי מְשִׁיחָא, דְּיוֹמָא דְקוּדְשָׁא בְּרִיךְ הוּא אֶלֶף שְׁנִין אַף עַל גַּב דְּכְּנֶסֶת יִשְׂרָאֵל חוּלָקָא דִּידָהּ יוֹמָא רְבִיעָאָה, אַזְלָא וְאִתְרְמִיזָא בְּיוֹמָא שְׁתִיתָאָה לְמֶהֱוֵי סְמִיכָא לְבַעְלָה דְּאִקְרֵי צַדִּיק יוֹמָא דְשַׁבְּתָא לְתַקְנָא לֵיהּ פָתוֹרָא וְהַאי דִכְתִיב (ירמיהו ל״א:כ״ב) כִּי בָּרָא יְיָ חֲדָשָׁה בָּאָרֶץ נְקֵבָה תְּסוֹבֵב גָּבֶר דָא אִיהוּ בְּזִמְנָא דִמְשִׁיחָא דְאִיהִי בְּיוֹמָא שְׁתִיתָאָה</p>\n<p>וּבְגִין כָּךְ כְּתִיב וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם הַשִׁשִׁי. ומַאי טַעְמָא אִתּוֹסַף ה' מָה דְלָא הֲוָה כֵּן בִּשְׁאָר יוֹמֵי. אֲבָל בְכָל אַתְרָא ה' דָא כְּנֶסֶת יִשְׂרָאֵל דְּאַתְיָיא לְאִזְדַּוְּוגָא בְּבַעְלָהּ יוֹמָא דְשַׁבְּתָא, כַּד יֵיתֵי לְבַעְלָהּ (ס\"א לה בעלה) לְאַקָּמָא לָהּ מֵעַפְרָא. וּבְגִין כָּךְ כְּתִיב (ישעיהו כ״ז:י״ג) וָבָאוּ הַאוֹבְדִים בְּאֶרֶץ אַשּׁוּר. דָא צַדִּיק וּכְּנֶסֶת יִשְׂרָאֵל.</p>\n<p>דָבָר אֲחֵר מַאי טַעְמָא אִתְכְּלִיל בְּיוֹם תְּלִיתָאִי רָזָא דְּצַדִּיק בְּגִין דִתְּלַת דַּרְגִּין מִימִינָא וּתְלָתָא מִשְּׂמָאלָא וְאִיהוּ הֲוָה אֱמְצָעִיתָּא דְּגוּפָא לְאַשְׁקָאָה לְכוֹלָא בְּגִין לְמִנְגָד שַׁקְיוּתֵיהּ לְיוֹם רְבִיעָאִי דְאִיהִי כְּנֶסֶת יִשְׂרָאֵל דְּלֵית לָה נְהוֹרָא מִגַּרְמָהּ, סָמִיךְ לְהַאי צַדִּיק. וְתָּא חֲזֵי הַאי יוֹמָא דְשַׁבְּתָא אֲסִיר לְמֶעְבָּד עֲבִידְתָּא בְּגִין כָּךְ אִתְכְּלִילוּ בֵּיהּ תְּרֵין וַיֹּאמֶר, לְקֳבֵל תְּרֵין דַּרְגִּין וְהוּכְפָּל בֵּיהּ כִּי טוֹב.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת לְקֳבֵל דַּרְגָא דְצֶדֶ\"ק, מַלְכוּ\"ת דִּלְעֵילָא דְּלֵית לָה נְהוֹרָא מִדִילָה אֶלָּא מָה דְאִתְיְיהִיב לָה עַל יְדֵי דְּצַדִּיק וּבְגִין כָּךְ דָוִד לְתַתָּא עָנִי וְאֶבְיוֹן אֲחִיד בָּהּ וְאִצְטְרִיךְ לְאוֹסָפָא לֵיהּ יוֹמִין וּשְׁנִין וְהָא אוֹקִימְנָא שִׁבְעִים שָׁנָה דַּיְיקָא וְאִקְרֵי יוֹם רְבִיעָאִי:</p>\n<p>וַיֹּאמֶר אֱלֹהִים יִשְׁרְצוּ הַמָּיִם. לְקֳבֵל דַּרְגָא דְנֶצָ\"ח דְּאִיהוּ סַמְכָא יְמִינָא דְּאוֹרַיְיתָא וּלְקִבְלֵיהּ מֹשֶׁה לְתַתָּא סָמִיךְ לְעָלְמָא בְּאוֹרַיְיתָא הֲדָא הוּא דִכְתִיב (ירמיהו ל״ג:כ״ה) אִם לא בְּרִיתִי יוֹמָם וָלַיְלָה וְגוֹ':</p>\n<p>וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ לְקֳבֵל דַּרְגָא דְהוֹ\"ד דְאֲחִיד אַהֲרֹן וְאִקְרֵי יוֹם שְׁתִיתָאִי. תָּא חֲזִיִ אַהֲרֹן לְתַתָּא אַף עַל גַּב דְאָתֵי מִחֶסֶ\"ד אֲחִיד לְתַתָּא בְּיוֹם שְׁתִיתָאִי דְּאִקְרֵי הוֹ\"ד וְעָבִיד קָרְבָּנִין בְּאִינוּן מִינֵי בְּעִירָן דַּכְיָין וְאִתְבְּרִיאוּ בְּיוֹמָא דִילֵיהּ (לקרבא) לְאַקְרָבָא כְּנֶסֶת יִשְׂרָאֵל דְאִתְרְמִיזָא בֵּיהּ (בצד\"ק) בְּצָדִי\"ק לְקַשְׁרָא דַּרְגִּין דִמְהֵימְנוּתָא וּלְנַחֲתָא רַחֲמֵי לְעָלְמָא:</p>\n<p>וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם. הַאי אֲמִירָא לְקֳבֵל דַּרְגָא עִלָּאָה דְכֹלָא סְתִימָאָה דִּסְתִימִין. בָּעָא לְמֶעְבָּד יְקָרָא לְדִיּוּקְנָא בְּרָזָא דְּאָדָם וּבְכֻלְּהוּ דַּרְגִּין לְתַתָּא יָהִיב חֵילָא לְאַפָּקָא <Nonei></i>כָּל חַד כְּדְקָא חָזֵי לֵיהּ וְעָבַד אָדָם דְּשַׁלִּיט בְּכֹלָּא בְּעִלָּאֵי וְתַתָּאֵי.</p>\n<p>וְתָא חֲזֵי עַד לָא אֲשְׁלִימוּ אִינוּן שֶׁבַע דַּרְגִּין יוֹמִין עִלָּאִין לָא אִשְׁתְּלִים אָדָם לְעֵילָא. כֵּיוָן דְּאִשְׁתְּלִים לְעֵילָא אָדָם עִלָּאָה, אִשְׁתְּלִים לְתַתָּא אָדָם תַּתָּאָה. וְכֻלְהוּ עָלְמִין בִשְׁלִימוּ. בְּגִין כָּךְ שָׁלְטֵיה לְאָדָם תַּתָּאָה עַל כָּל דְּאִתְבַּרֵי בְּעַלְמָא בְּגִין דְּאָדָם עִלָּאָה שָׁלִיט עַל כֹּלָּא. וּבְגִין כָּךְ רָמַז בְּהַאי קְרָא שֶׁבַע דַּרְגִּין. דְּאִית בֵּיהּ שֶׁבַע דַּרְגִּין עִלָּאִין דְּאִקְרֵי בְּהוּ אָדָם דִּלְעֵילָא וְאִשְׁתְּלִים בְּהוּ. בְּגִין כָּךְ נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ, לְמֵיהַב לֵיהּ שֶׁפַע מֵהַהוּא אַתְרָא דְּאִקְרֵי חֶסֶד.</p>\n<p>תָּא חֲזֵי, מַאן דְּהַאי צוּלְמָא עָלֵיהּ, חֶסֶד אֵל לָא אַעְדֵי מִנֵּיהּ וְיַתְבָא עַל רֵישֵׁיהּ וְאִתְחַבְּרַת בֵּיהּ שְׁכִינְתָּא בְסֵיפָא (בסופא) דְיוֹמוֹי בְּגִין דְּהַאי חֶסֶ\"ד יוֹם רִאשׁוֹן וְאִיהוּ רֵישָׁא דְכָל יוֹמִין דִּלְעֵילָא וְהַאי צוּלְמָא דְּאַתְיָא לֵיהּ מִנֵּיהּ לָא אִסְתְּלַק עַד דְּאִשְׁתְּלִימוּ יוֹמוֹי בְּהַהוּא דַּרְגָא דְאִקְּרֵי אַחֲרִית הַיָּמִים וְהוּא דַּרְגָא דְצֶדֶק וְאִיהִי שְׁבִיעָאָה, שְׁנָת הַשְׁמִיטָה בְּהַהוּא דַּרְגָא אַשְׁלִימוּ יוֹמוֹי דְּבָּר נָשׁ כַּד אִשְׁתַּלִּימוּ שִׁבְעִין שְׁנִין לְקֳבֵל שֶׁבַע דַּרְגִּין, עֲשָׂרָה לְכָל דַּרְגָא. הֲדָא הוּא דִכְתִיב (תהילים צ׳:י׳) יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה. מַאן בָּהֶם, בְּאִינוּן יוֹמִין וּשְׁנִין דִּלְעֵילָא.</p>\n<p>וְאִם בִּגְבוּרוֹת שְׁמֹנִים. תָּא חֲזֵי, בְּנֵי חַיֵּי וּמְזוֹנֵי לָאו בִּזְכוּתָא תַלְיָא מִלְּתָא. רָזָא דְּאִינוּן שָׁב בְּדַרְגִּין (לדעתי צ\"ל שבע דרגין) דִבְּהוֹן זְכוּת וְחוֹבָא בְּרָזָא דְחֶסֶ\"ד וּגְבוּרָה. דְּאִי הֲכִי לָא הֲוָה לֵיהּ לְבַר נָשׁ לְמֶהֱוִי חָי בָּר מִשִׁבְעִין. אֶלָּא בְּמַזָּלָא עִלָּאָה עַתִּיקָא דְכֹלָא תַלְיָין. בְּגִין כָּךְ אִיהוּ מוֹסִיף עַל כָּל יוֹמוֹי דְכָל בַּר נָשׁ כִּרְעוּתֵיהּ.</p>\n<p>וְתָּא חֲזֵי הֲכִי אוֹלִיפְנָא בְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא, דְּבֵּלְילְיָא בַּתְרָאָה דְחַגָא, אִי יִסְתָּכַּל בַּר נָשׁ בְּצוּלְמָא דִילֵיהּ וַחֲזֵי לֵיהּ שְׁלִים, לָא אִתְגְּזַר עֲלוֹי מִיתָה. וּמָאי טַעְמָא בְּהַאי לֵילְיָא, בְּגִין דְז' יוֹמִין דְחַגָא לְקֳבֵל שִׁבְעָא יוֹמִין עִלָּאִין אִינוּן. דְכָל יוֹמִין וּשְׁנִין דְּעָלְמָא בְּהוּ תַלְיָין, וְאִינוּן רְמִיזִין בְּקְרָא (דברי הימים א כט) דְּלְךָ יְיָ' הַגְּדוּלָה וְגוֹ' שֵׁירוּתָא דִלְהוֹן חֶסֶ\"ד וְסִיּוּמָא דִלְהוֹן מַמְ\"לָכָה, כְּנֶסֶת יִשְׂרָאֵל, אֲחַרִי\"ת הַיָּמִים. אִשְׁתְּכַח שְׁבִיעָאָה אַחֲרִית. וְכַד אַתְיָא הַאי לֵילְיָא דִשְׁבִיעִי אִתְחֲזֵי אִי אִשְׁתַּלִּימוּ יוֹמוֹי בְּהַאי אַחֲרִית. וְאִי הַאי צוּלְמָא עִלָּאָה חֲזֵי עָלֵיהּ, חֶסֶ\"ד אֵל יִתְהַדָר עָלֵיהּ כְּדִּבְקַדְמֵיתָא וְלָא מִסְתַּפֵּי מֵהָאי דִינָא דְצֶדֶ\"ק וְאִיהִי בַּהֲדֵיהּ בִשְׁלִימוּ בְּחֶדְוָותָא וְאַהְדַּרַת לֵיהּ אַנְפִּין.</p>\n<p>וּבְגִין כָּךְ אַזְהַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל לְאִשְׁתֵּזָבָא מִדִינוֹי דְּהַאי צֶדֶ\"ק, וּלְחַפָאַה סֻכַּת שְׁלָמָא עָלַיְיהוּ וּלְמֵיתַב בְּצִלָא דִמְהֵימְנוּתָא. הֲדָא הוּא דִכְתִיב (ויקרא כ״ג:מ״ב) בַּסֻכּוֹת תְּשְׁבוּ שִׁבְעַת יָמִים לְאַכְלָלָא לְהַאי דַּרְגָא דִּלְעֵילָא וּלְאוֹסָפָא בֵּיהּ בְּרָכָה מַיִּם (ממיין) עִלָּאִין, בְגִין דְּהַאי יוֹמָא שְׁבִיעָאָה אִיהוּ כְּנֶסֶת יִשְׂרָאֵל אֲנָן מָקִיפִין לְהַאי מִזְבֵּחַ עִלָּאָה בְּאִינוּן תְּרֵין לִמּוּדִים דְּאִינוּן עַרְבֵי נַחַל וְעַבְדִין בָּהּ נִסוּךְ הַמָּיִם וְיָהִיב צַדִּי\"ק בְּאִינוּן שִׁתִּין דְּאִינוּן מִו' יְמֵי בְּרֵאשִׁית כֹּלָּא בְּרָזָא דְחָכְמְתָא.</p>\n<p>וּלְבָתָר (במדבר כ״ט:ל״ה) בְּיוֹם הַשְׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. עָבְדוּ כְּנִישְׁתָּא לְאִינוּן שֶׁבַע יוֹמִין עִלָּאִין וְעָבְדוּ יוֹמָא טָבָא, בְּגִין דְאִשְׁתָזְבְתוּן מִדִינוֹי דְּהַהוּא יוֹמָא שְׁבִיעָאָה. בְּגִין כָּךְ כְּתִיב בְּצַלְמֵנוּ</p>\n<p>כִּדְמוּתֵנוּ לְקֳבֵל יוֹמָא תִנְיָנָא גְבוּרָה, חוּלָקֵיהּ דְיִצְחָק. כְּדֵין אִית לְבַּר נָשׁ לְמִשְׁוֵי לְהַאי דְמוּתֵנוּ וּלְאִתְדָמֵי בְּעוֹבָדוֹי לְאִינוּן עִלָּאִין. וְכָל דָא לָמָה בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב בִּידֵי דְּבַר נָשׁ, דְּאִי בָּעֵי בַּר נָשׁ לְמִדְמֵי גַּרְמֵיהּ לְאִינוּן דִּלְעֵילָא אִשְׁתְּלִים בְּהוּ וְלָא מִסְתַּפֵּי מֵהָאי מִדַּת דִינָא עִלָּאָה.</p>\n<p>וְיֵּרְדוּ בִּדְגַת הַיָּם לְקֳבֵל דַּרְגָא דְנֶצָ\"ח דְאֲחִיד בֵּיהּ מֹשֶׁה דְגָּת הַיָּם בְּהַהוּא דַּרְגָא אִתְבְּרִיאוּ וְיָהִיב לוֹן סְתִימָא דִּסְתִימִין חֵילָא לְמִשְׁלַט עָלַיְיהוּ, אִי דָמֵי בָּר נָשׁ לְעִלָּאִין, וְאִי לָא דָמֵי לְעִלָּאִין יֵרְדוּ. וְנוּנִי יַמָּא שַׁלְטִין בְּהוּ בִּבְנֵי נָשָׁא. וּבְגִין כָּךְ אַזְהִירָת לוֹן אוֹרַיְיתָא דְאִתְיְיהִיבַת עַל יְדֵי דְמֹשֶׁה (דברים ל׳:י״ט) וּבָחַרְתָּ בַּחַיִּים.</p>\n<p>תָּא חֲזֵי מֹשֶׁה כַּד אִתְרַמֵי לְיַמָּא לֹא שָׁלְטוּ עָלֵיהּ נוּנֵי יַמָּא וְלֹא אִסְתָפֵי מִנַּיְיהוּ בְּגִין דְּאִיהוּ הֲוָה זַמִּין לִקְרָבָא לְעֵילָא וּלְאִתְדַּבְּקָא בְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְבָתָר כַּד אִתְדַבַּק שָׁלִיט עַל נוּנֵי יַמָּא. וְרָמַז לְאַהֲרֹן אֲחוּי דְּיִמְחֵי יָת יַמָּא וִימוּתוּן נוּנִי וְאִיהוּ לָא עֲבִיד הֲכִי, בְּגִין דְהַהִיא דַּרְגָא דִילֵיהּ שָׁלִיט עָלַיְיהוּ וּבֵיהּ אִתְבְּרִיאוּ וְלא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא דְּיִמְחֵי אִיהוּ, בְּגִין לְאִתְהַפְּכָא לְהוּ לְאוֹיֵב. וְכַד בַּר נָשׁ אֲזִיל בְּאָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא כְּתִיב עָלֵיהּ (ישעיהו מ״ג:ב׳) כִּי תַעֲבוֹר בַּמַיִם אִיתְךְ אֲנִי וְגוֹ'. דְּהָא וְיֵּרְדוּ בִּדְגַת הַיָּם</p>\n<p>וּבְעוֹף הַשָׁמַיִם לְקֳבֵל דַּרְגָא דְּשָׁמַיִם. דְּבְהַהוּא דַּרְגָא שָׁלִיט עָלַיְיהוּ וְדָא תִפְאֶרֶ\"ת. וְאַף עַל גַּב דִּבְדַרְגָּא דְנֶצָ\"ח אִתְעֲבִידוּ כָּל נוּנִי יַמָּא וְעוֹפֵי, לָא כְּתִיב תַמָּן אֶלָּא עוֹף כַּנַף אֲבָל הַשְׁתָּא קָרֵי לְהוּ עוֹף הַשָׁמַיִם בְּגִין דְּבַּר נָשׁ לָא שָׁלִיט עָלַיְיהוּ אֶלָּא מִסִּטְרָא דְּשָׁמַיִם.</p>\n<p>וּבַבְּהֵמָה שָׁלִיט עָלַיְיהוּ בְּרָזָא דְהוֹ\"ד דְּיָהִיב לֵיהּ סִיוּעָא דְּהָא בְּהַהוּא יוֹמָא אִתְבְּרִיאוּ בְּעִירָן. וּבְכָל הָאָרֶץ שָׁלִיט בְּרָזָא דְצָדִי\"ק דְּאִקְרֵי כָּ\"ל וְאִיהוּ שָׁלִיט עַל הָאָרֶץ אַרְעָא עִלָּאָה. הָכִי נָמֵי בַּר נָשׁ לְתַתָּא שָׁלִיט עַל אַרְעָא תַּתָּאָה בְּגִין דְכוֹלָא בֵּיהּ. וּבְכָל הָרֹמֵשֹׁ הַרוֹמֵשׂ עַל הָאָרֶץ שָׁלִיט עָלַיְיהוּ בָּר נָשׁ מִסִיוּעָא דְאִתְיְיהִיב לֵיהּ מֵאֶרֶץ הַחַיִּים מַלְכוּת עִלָּאָה:</p>"],[9520012805,"<p><Nonei></i>וַיֹּאמֶר אֱלֹהִים הִנֵּה נָתַתִּי לָכֶם אֶת כָּל עֵשֶׂב זוֹרֵעַ זֶרַע לְקֳבֵל דַּרְגָא דְבִּינָ\"ה דְּאִקְרֵי אֱלֹהִים דְּכֵיוָן דְּאִימָא עִלָּאָה חָמָאת לוֹן שְׁלֵמִין יָהִיב לוֹן תָּפְנוּקִין מִלְּעֵילָא לְאִתְקַיְימָא בְּעַלְמָא.</p>\n<p>תָּא חֲזֵי, אָדָם קַדְמָאָה קוּדְשָׁא בְּרִיךְ הוּא יָהַב לֵיהּ כָּל עֵשֶׂב זוֹרֵעַ זֶרַע וְלָא יָהַב לֵיהּ רֵשׁוּ לְמֵיכָל בְּעִירֵי וְעוֹפֵי שְׁמַיָא, בְּגִין דְגַלֵּי קַמֵּיהּ דְהוּא זַמִּין לְאִתְפַּתָאַה בְּהַהוּא נָחָשׁ דְּאִיהוּ עֲרוּם מִכָּל חַיַּת הַשָּׂדֶה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֲרְחֵקִינֶיהּ מִנֵּיהּ וְלָא יְהֵא לֵיהּ עֵסֶק בֵּיהּ וְלָא בִּבְעִירֵי וְלָא בְּעוֹפֵי בְּגִין דְקוּדְשָׁא בְּרִיךְ הוּא אָרִים לֵיהּ לְבַּר נָשׁ מִכְשׁוֹל מִקָמֵיהּ, מְאִים יִתְקַיַּים בְּעַלְמָא.</p>\n<p>אֲבָל כַּד אֲתָא נֹחַ דְּאִקְרֵי צַדִּיק מָה כְּתִיב בֵּיהּ (בראשית ח׳:כ׳) וַיִּבֶן נֹחַ מִזְבֵּחַ לַיְיָ וְהָא אוּקִימְנָא הַהוּא מִזְבֵּחַ דְאַקְרִיב בֵּיהּ אָדָם הָרִאשׁוֹן. ומַאי טַעְמָא וַיִּבֶן בְּגִין דְחַיָיבֵי עַלְמָא עַבְדֵי בָּהּ פְּגִימוּ. אֲתָא נֹחַ וְקָרִיב הַהוּא מִזְבֵּחַ בְּבַעְלָהּ הֲדָא הוּא דִכְתִיב וַיָּעַל עֹלֹת בַּמִזְבֵּחַ חָסֵר,</p>\n<p>כַּד חָמָא קוּדְשָׁא בְּרִיךְ הוּא דְאִתְקְרִיב הַהוּא מִזְבֵּחַ וְקָרִיב הַנְהוּ בְּעִירֵי דַכְיֵי יָהַב לֵיהּ רֵשׁוּ לְמֵיכָל כֻּלְּהוּ בְּעִירֵי. מַאי טַעְמָא, בְּגִין דְאַתְקִיף בְּהַהוּא בְּרִית עֵץ הַחַיִּים, וְקָרִיב לֵיהּ בְּעֵץ הַדַּעַת וְעָבַד יִחוּדָא בְּקַדְמִיתָא אֶלָּא דִּלְבָתַר אִתְפָּתָא דְּבָעָא לְמִבְדַּק בְּהַהוּא חוֹבָה וְלָא לְאִתְדַבַּק בֵּיהּ וַאֲפִילּוּ הֲכִי לָא אִשְׁתֵּזִיב מִנֵּיהּ וְנָצִיב הַהוּא כַּרְמָא.</p>\n<p>תָּא חֲזֵי, אָדָם דְּזַמִּין לְאִתְפַּתָאַה בְּאִילָנֵי לָא יָהַב לֵיהּ אִילָנֵי וְאַרְחֶקִינְהוּ מִנֵּיהּ דְּהָא לָא אִדְכָּר לוֹן אֶלָּא דְּאִיהוּ עָבַד גַּרְמֵיהּ חוֹל וְנָצִיב הַהוּא כַּרְמָא דְּאִקְרֵי בֵּית יִשְׂרָאֵל. בְּקַדְמִיתָא אִשְׁתְּלִים בֵּיהּ וְחַפְיָא עָלֵיהּ (ואשתזיב) אִשְׁתֵּזִיב בָּהּ. וּמַאן אִיהִי בֵּית יִשְׂרָאֵל דָא תֵּיבָה דְּאִקְרֵי אֲרוֹן הַבְּרִית.</p>\n<p>וְהַשְׁתָּא כַּד בָּעָא לְמִבְדַּק, מָה כְּתִיב (בראשית ט׳:כ״א) וַיֵּשְׁתְ מִן הַיָּיִן, כְּמָה דְאַתְּ אָמֵר, וַתִּקַּח מִפִּרְיוֹ. לְבָתָר וַיִתְגָּל בְּתוֹךְ אֲהֹלֹה. גָלֵי הַהוּא פִּרְצָה בְּקַדְמִיתָא בְּגוֹ מַשְׁכְּנֵיהּ בְּגוֹ לְגוֹ. וְאִי לָאו הַהוּא מַדְבְּחָא דְאַגִינָת עָלֵיהּ מִשׁוּם דְאִתְדַבָּק בָּהּ בְּקַדְמִיתָא הֲוָה נִתְפָּס מִיָד. וְעִם כָּל דָּא כַּד לָא עֲבַד לֵיהּ אֶלָּא לְמִבְדַּק, כָּסֵי עָלֵיהּ אוֹרַיְיתָא וְלָא פַרְסְמֵיה כְּמָה דְפִרְסֵם לְאָדָם. וְהַהוּא מַדְבְּחָא הוּא כַּפָּרָה עָלֵיהּ.</p>\n<p>תָּא חֲזֵי, מִזְבַּח שֶׁל בֵּית עוֹלָמִים הוּא תְּלָתִין וּתְרֵין עַל תְּלָתִין וּתְרֵין אָמָה (והיא) הִיא רְמִיזָא בִּתְרֵין וּתְלָתִין נְתִיבוֹת פְּלִיאוֹת חָכְמָה. דְּהָא חָכְמָה תַּתָּאָה אִקְרֵי,</p>\n<p>עָלָהּ אָמָה וְכָּנָס אָמָה, זְהוּ יְסוֹ\"ד לְקֳבֵל (צדיק) צֶדֶ\"ק דִּלְעֵילָא דְּהָא כְּגווָֹנָא דְּכוּלְהוּ דַּרְגִּין אִית בָּהּ וְכֻלְּהוּ אִתְחַזְיָין בָּהּ דְּהָא מַרְאָה אִקְרֵי. עֲלָהּ חֲמֵשׁ וְכָּנָס אָמָה, זְהוּ סוֹבֵב לְקֳבֵל הַהוּא דַּרְגָא דְאִתְדַבָּק בָּהּ דְּאִיהוּ סוֹבֵב לְהַהוּא מִזְבֵּחַ הֲדָא הוּא דִכְתִיב, (שיר השירים ב׳:ו׳) וִימִינוֹ תְּחַבְּקֵנִי דְּהָא מִיְסוֹ\"ד עַד הַהוּא דַּרְגָא חֲמִשָׁה דַּרְגִּין אִינוּן.</p>\n<p>עָלָהּ שָׁלשׁ וְכָּנָס אָמָה, אֵלּוּ קְרָנוֹת לְקֳבֵל אִינוּן תְלָתָא דַּרְגִּין דְאַתְיָין לָה מִנַּיְיהוּ תְּקִיפוּ עִלָּאָה וְשֶׁפַע. וּבְגִין כָּךְ דָוִד שְׁנִמְשָׁח בְּקֶרֶן נִמְשְׁכָה מַלְכוּתוֹ בְּגִין דְּאִיהוּ בְּאִינוּן קְרָנוֹת הַמִּזְבֵּחַ תְּקִיפוּ דְמַדְבְּחָא עִלָּאָה.</p>\n<p>תָּא חֲזֵי, אַרְבַּע קְרָנוֹת, אָמָה עַל אָמָה אִית בֵּיהּ בַּמִזְבֵּחַ, בְּגִין דְּאִיהוּ כִּסֵּא דָוִד יוֹם רְבִיעָאִי לָתֵת לָה שֶׁפַע מֵאִינוּן שְׁלֹשׁ אַמּוֹת לְאִינוּן אַרְבַּע קְרָנוֹת.</p>\n<p>וְכַד הֲווּ מַקְרִיבִין כְּהָנֵי מִסִּטְרָא דְחֶסֶ\"ד עֹלַת הַתָּמִיד לְגַבֵּי מִזְבֵּחַ הֲווּ מַקְרִיבִין לֵיהּ הַהוּא אַתְרָא דְּאִקְרֵי מִזְבֵּחַ. וְכַד הֲווּ עַבְדִין מָתָנוֹת מִדָּמָא דְעוֹלָה הֲווּ סָלְקִין וַהֲווּ אַזְלִין בְּהַהוּא סוֹבֵב דְּאִיהוּ דַּרְגָא דִידְהוּ וְחוּלָקֵיהּ דַאֲבוּהוֹן דְיַהֲבִין שְׁתֵּי מָתָנוֹת שְׁהֵן אַרְבַּע לְקֳבֵל הַהוּא אַתְרָא דְּאִקְרֵי עוֹלָה.</p>\n<p>וְלָקֳבֵל שְׁתֵּי מָתָּנוֹת דְּהַהוּא בוּכְרָא דְנָטִיל תְּרֵין חוּלָקִין הֲדָא הוּא דִכְתִיב (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם יוֹשֵׁב אֹהָלִים רַחֲמֵי וְדִינָא וְנָסִיב הַהוּא צַדִּיק תְּרֵין חוּלָקִין דִּידֵיהּ הֲדָא הוּא דִכְתִיב (דברי הימים א ה׳:א׳) נִתָּנָה בְּכֹרָתוֹ לְיוֹסֵף וּתְרֵין חוּלָקִין דְאָבוֹי וְנָסִיב כֹּלָּא הַאי כָּ\"ל וְאַמְלֵי לְהַהוּא אַתְרָא דְאִקְּרֵי יַם. הֲדָא הוּא דִכְתִיב, (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם. הַאי מִזְבַּח הָעוֹלָה הֲוָה גַּבֵּיהּ,</p>\n<p>הַא (האי) ט' אַמּוֹת לְקֳבֵל ט' דַּרְגִּין דְאִיכָּא עַד צַדִּיק תְשִׁיעָאָה דְכוֹלָא טוֹ\"ב וַדַּאי. וְאִיהוּ כְבִּנְיַן אוֹצָר רְחַבָה מִלְמַטָּה וּקְצָרָה מִלְמַעְלָה הֲדָא הוּא דִכְתִיב וַיִּבֶן יְיָ אֱלהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הַאָדָם לְאִשָׁה. וְהַאי מִזְבֵּחַ עִלָּאָה הִיא אִשְׁתּוֹ דְּאָדָם דִּלְעֵילָא וּבְגִין כָּךְ אִקְרֵי מִזְבֵּחַ עוֹלָה כְּמָה דְאַתְּ אָמֵר (יהושע ג׳:ו׳) אֲרוֹן הַבְּרִית וְדָא כְּנֶסֶת יִשְׂרָאֵל וְאִקְרֵי מִזְבֵּחַ</p>\n<p>מַאי טַעְמָא אִקְרֵי הֲכִי בְּגִין דְּכַד בְּנֵי עַלְמָא לָא מַכְשְׁרָן עוֹבַדָיְיהוּ אִיהִי דַבְחָא לוֹן הֲדָא הוּא דִכְתִיב (ויקרא כ״ו:כ״ח) וְהִכְּתִי אֶתְכֶם אַף אֲנִי. דְּהָא כָּל מָאנֵי קְרָבָא דְמַלְכָּא בִּידֵיהּ אִתְמְסָרוּ הֲדָא הוּא דִכְתִיב (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים סָבִיב לָה. וּבְגִין כָּךְ אוֹרַיְיתָא שְׁלֵימָתָא קוּדְשָׁא בְּרִיךְ הוּא יַהֲבָה לוֹן לְיִשְׂרָאֵל לְמִזְכֵּי בָּהּ לְחַיֵּי עַלְמָא לְאִשְׁתֵּזָבָא מִדִינוֹי דְּהַהוּא מִזְבֵּחַ. מָה דְּלֵית רֵשׁוּ לְגַבְרָא אַחֲרָא לְקָרְבָא לְגַבָּהּ.</p>\n<p>וְכִי תֵימָא הָא חֲמֵינָא מֹשֶׁה קָרִיב לְגַבָּהּ שִׁבְעָה יוֹמִין בְּקַדְמִיתָא, תָּא חֲזֵי כְּתִיב (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. הַאי קְרָא עַל <Nonei></i>כְּנֶסֶת יִשְׂרָאֵל אִתְּמָר כַּד אִיהִי שַׁרְיָיא בְּאַרְעָא בְּכָל אִינוּן שִׁבְעָה יוֹמִין כֻּלְּהוּ בִשְׁלִימוּ הֲדָא הוּא דִכְתִיב (ויקרא ח׳:ל״ג) שִׁבְעַת יָמִים יְמָּלֵא אֶת יֵדְּכֶם וּבְגִין כָּךְ אִקְרוּן שִׁבְעַת יְמֵי הַמִלוּאִים דַּיְיקָא.</p>\n<p>וּמֹשֶׁה דְּאִיהוּ לֵוִי מִסִּטְרָא דָא קָרִיב בְּקַדְמִיתָא לְגַבֵּי הַאי מִזְבֵּחַ. הֲדָא הוּא דִכְתִיב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי מַאי רֹאשִׁי אֶלָּא בְּרֵישָׁא כַּד אִתְדַבְּקַת הַאי מִזְבֵּחַ בְּהַהוּא עוֹלָה שְׂמֹאלוֹ אִתְקְרֵי בְּקַדְמִיתָא, וְעִם כָּל דָּא אִתְעָרוּ חַבְרַיָּיא בְּחַלוּק לָבָן שֶׁאֵין בּוֹ אִימְרָא שִׁימֶּשׁ. הֲדָא הוּא דִכְתִיב, (בראשית ל׳:ל״ז) מָחְשׂוֹף הַלָּבָן אֲשֶׁר עַל הַמָקְלוֹת. בְּגִין דְּאַף עַל גַּב דְּאִיהוּ מִסִּטְרָא דְדִינָא אִתְלַבַּשׁ בְּחֶסֶ\"ד וְקָרִיב לְגַבָּהּ וְאִתְעַר חֶסֶ\"ד עִלָּאָה בְּעַלְמָא.</p>\n<p>וּמַאי קָרִיב פָּר בְּרֵישָׁא תָמִיד שֶׁל שָׁחַר עוֹלָה וַדַּאי. וּלְבָתָר קָרִיב פָּר חַטָּאת לְמֵיהַב שְׁלָמָא בֵּין הַהוּא פָּר חַטָּאת וְאַהֲרֹן דְּחָב לְגַבָּהּ כַּד עֲבָד עֶגְלָא (ס\"א עולה) וְדָא כְּנֶסֶת יִשְׂרָאֵל וְהַחֲטָאת לְקֳבְּלָה אִיהוּ. וְדָא פָּר כֹּהֵן מָשִׁיחַ כַּד אִיהוּ חָב לְגַבֵּי מִזְבֵּחַ מָה דְלָא אִית בְּגֶבֶר אַחֲרָא אֶלָּא נוּקְבְתָא לְחַטָּאת וּלְבָתָר קָרִיב עוֹלָה לְגַבָּהּ. כֵּיוָן דְאִתְקְרִיב עוֹלָה לְגַבֵּי הַאי מִזְבֵּחַ כְּדֵין מִלוּאִים הוּא. מִלוּאִים לְעֵילָא מִלוּאִים לְתַתָּא וְכֻלְהוּ עָלְמִין בְּחֶדְוָה, דְּהָא מַטְרוֹנִיתָא אִתְחַבְּרַת בְּבַעְלָהּ וּכְדֵין קָרִיב לְגַבֵּי הַהוּא מִזְבֵּחַ אֵיל הַמִלוּאִים. וְיָהִיב מֵהַהוּא דָּמָא עַל תַנוֹךְ אוּדְנָא דְאֲהַרֹן בְּגִין דְּתְהוֵי רְכִיכָא לְמִשְׁמָע בִּרְכִיכוּ וְלָא בְּקַשְׁיוּ. וִיְקַבֵּל מִלֵּי דְּאוֹרַיְיתָא דְלָא לְאַפְרָדָא תּוֹרָה שֶׁבְּעַל פֶּה מִתּוֹרָה שֶׁבִּכְתָב וּלְאַשְׁלָמָא עָלְמִין כֻּלְּהוּ וְכֵן לִבְנוֹי.</p>\n<p>וּפַקִּיד לוֹן דְּיָתְבוּן בְּהַהוּא תַרְעָא דְּהַהוּא אֹהֶל לְמִיטַר הַהוּא אַתְרָא דְלָא יִתְקְרַב עָרֵל וְטָמֵא וְיִשְׁתַּלְּמוּן (כלהו) כֻּלְּהוֹן שִׁבְעָה יוֹמִין עִלָּאִין וְיִסְתָלְקוּן בְּהַהוּא דַּרְגָא דְחֶסֶ\"ד דְּאִיהוּ מִתַּתָּא לְעֵילָא שְׁבִיעָאָה דְּהָא אִינוּן בְּקַדְמִיתָא אִתְדַבְּקוּ בְּהַהוּא פֶּתַח אֹהֶל מוֹעֵד וּלְבָתָר אִסְתַּלְקוּ לְעֵילָא.</p>\n<p>וּלְבָתָר מָה כְּתִיב וִימִינוֹ תְּחַבְּקֵנִי הֲדָא הוּא דִכְתִיב (ויקרא ט׳:א׳) וַיְהִי בְּיוֹם הַשְׁמִינִי קָרָא מֹשֶׁה לְאַהֲרֹן וּפַקִּיד לֵיהּ לְמִיסַב הַהוּא עֵגֶל דְּחָב בֵּיהּ וִיקַרְבִינֶיה לְגַבֵּיהּ הַהוּא מִזְבֵּחַ וְאִיהוּ הֲוָה כַּסִיף לְקָרְבָא לְגַבֵּיהּ דְדָחִיל מִשָׁלְהוֹבוֹי. אָמַר לֵיהּ מֹשֶׁה (שם) קְרָב אֶל הַמִּזְבֵּחַ וַעֲשֵׂה אֶת חֲטָאתְךָ בְּקַדְמִיתָא וְהַב מֵהַהוּא דָּמָא בְּאִינוּן קְרָנוֹת בְּגִין דְחָב בְּקַדְמִיתָא לְגַבַּיְיהוּ וּמָנַע מִנְּהוֹן בִּרְכָאָן</p>\n<p>וּלְבָתָר (שם) וְאֶת הַדָּם יַצָק אֶל יְסוֹד הַמִּזְבֵּחַ לְאַצְקָא בָּהּ הַהוּא יְסוֹד. מַאי יַצָק כְּמָה דְאַתְּ אָמֵר (מלכים א ז׳:כ״ג) וַיַעֲשׂ אֶת הַיָּם מוּצָק. וּלְבָתָר קָרִיב לְהַהוּא מִזְבֵּחַ הַהוּא עוֹלָה וַעֲבַד בְּקַדְמִיתָא רֹאשׁ וּלְבָתָר רֶגֶל. וּלְבָתָר עַל יִשְׂרָאֵל קָרִיב שֵׂעִיר עִזִים דְּהָא מֵהַהוּא סִטְרָא דְיֶצֶר הַרָע אִתְדַבְּקוּ בַּעֲבוֹדָה זָרָה</p>\n<p>וּלְבָתָר עֵגֶל וְכֶבֶשׂ לְעוֹלָה. תָּא חֲזֵי בְּקַדְמִיתָא עֵגֶל לְחַטָּאת כֵּיוָן דְקָרִיב לֵיהּ בִשְׁלִימוּ לְגַבֵּיהּ אִמֵּיהּ לְבָתָר קָרִיב לֵיהּ לְגַבֵּי אֲבוֹי. הֲדָא הוּא דִכְתִיב לְעוֹלָה, וּלְבָתָר שׁוֹר וַאֲיִל לִשְׁלָמִים דְּהָא שְׁלָמָא בְכֻלְּהוּ עָלְמִין וְהַאי שׁוֹר דְּסִטְרָא דִשְׂמָאלָא. וְאֵילוֹ דְיִצְחָק לָא עַבְדִין דִּינָא אֶלָּא לִשְׁלָמִים שְׁלָמָא לְעֵילָא שְׁלָמָא לְתַתָּא</p>\n<p>וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא פָּתַח עָלַיְיהוּ (תהילים קל״ג:א׳) הִנֵּה מָה טוֹב וּמָה נָעִים שֶׁבֶת אַחִים גַּם יַחַד. שֶׁבֶתשֶׁבֶת אַחִים יְמִינָא וּשְׂמָאלָא מֹשֶׁה וְאַהֲרֹן. גַּם לְאַכְלָלָא לִכְּנְסֶת יִשְׂרָאֵל יַחַד. צַדִּי\"ק כֹּלָּא בְּיִחוּדָא (שלימא) שְׁלֵימָתָא כְּדֵין מָה כְּתִיב כַּשֶׁמֶן הַטּוֹב עַל הָרֹאשׁ יוֹרֵד עַל הַזָּקָן כֵּיוָן דְּאִתְחַבְּרוּ דְכָר וְנוּקְבָא שְׁלִים בְּגִין כָּךְ כַּשֶׁמֶן הַטּוֹב עַל הָרֹאשׁ בְּקַדְמִיתָא עַתִּיקָא דְכוֹלָא רֵישָׁא דְכָל רֵישִׁין. יוֹרֵד עַל הַזָּקָן דָא חֶסֶ\"ד וּגְבוּרָ\"ה וְתִפְאֶרֶת דְּכוּלְהוּ אִקְרוּן זָקֵן. (בראשית כ״ד:א׳) וְאַבְרָהָם זָקֵן. (שם כ\"ז) וַיְהִי כִּי זָקֵן יִצְחָק. (שם מ\"ח) וְעֵינֵי יִשְׂרָאֵל כַּבְדוּ מִזֹקֵן. עַל פִּי מִדוֹתָיו. דָא צַדִּיק וְאִיהִי פִּי מִדוֹתָיו.</p>\n<p>וּלְבָתָר כְּטָל חֶרְמוֹן שֶׁיוֹרֶד עַל הֲרְרֵי צִיּוֹן. אִלֵּין שֶׁבַע הָרִים דְאִקְּרוּן הֲרְרֵי צִיּוֹן. כִּי שָׁם צִוָּה יְיָ אֶת הַבְּרָכָה. כֵּיוָן דְּאִתְחַבְּרוּ. חַיִּים עַד הָעוֹלָם דָא עֵץ חַיִּים בְּהַהוּא עוֹלָם. וְכָל דָא בְּגִין הַנְהוּ קָרְבָּנִין דְּמִתְעָרִין טִיבוּ לְעֵילָא וְתַתָּא.</p>\n<p>וּלְבָתָר הֲכִי כְּהָנֵי דְמִסִטְרָא דְחֶסֶ\"ד קְרֵבִין לְגַבֵּיהּ דְּהַהוּא מִזְבֵּחַ מָה דְּלֵית רֵשׁוּ לִגְבַר אַחֲרָא לְקָרְבָא. וְנַכְסִין נִכְסָת קוּדְשִׁין בִּצְפוֹנָא דְמִזְבֵּחַ, בְּגִין דְבִּסְטָר צְפוֹנָא דְּאִית בָּהּ, כַּד קָרִיב גְבוּרָה לְגַבָּהּ עַבְדָּא אִינוּן נוּקְמִין, בְּגִין כָּךְ עַבְדִין כְּהָנֵי שְׁלָמָא בְּעַלְמָא דְלָא יִתוֹקַד עַלְמָא בְּשַׁלְהוֹבוֹי דְמִזְבֵּחַ. וּכְדֵין חַיִּים נַחְתִּין לְעָלְמָא הֲדָא הוּא דִכְתִיב (מלאכי ב׳:ה׳) בְּרִיתִי הָיְתָה אִתּוֹ הַחַיִּים וְהַשָׁלוֹם. מַאי טַעְמָא חַיִּים בְּגִין דְהוּא עֲבָד שָׁלוֹם.</p>\n<p>וְכַהֲנֵי עַבְדִין שָׁלוֹם בְּקָרְבָּנָא מַאי קָרְבָּנָא לָבָן וְאָדוֹם. חֵלֶב וְדָם. חֵלֶב לְקֳבֵל הַהוּא דַּרְגָא שׁוּפְרָא דְכוֹלָא. חֵלֶב הָאָרֶץ מְתַרְגֶּמִינָן שׁוּפְרָא דְאַרְעָא. דָּם לְקֳבֵל הַהוּא דַּרְגָא דְּאִקְרֵי נֶפֶשׁ דִכְתִיב (ירמיהו נ״א:י״ד) נִשְׁבַּע יְיָ צְבָאוֹת בְּנַפְשׁוֹ (עמוס ו' נשבע יי בנפשו). וּבַר נָשׁ כַּד קָרִיב הַאי דָּמָא כְּאִילוּ מַקְרִיב נַפְשֵׁיהּ הֲדָא הוּא דִכְתִיב (ויקרא י״ז:י״א') כִּי הַדָּם הוּא בַּנֶפֶשׁ יְכַפֵּר.</p>\n<p>וּבְגִין כָּךְ אַזְהַר לוֹן אוֹרַיְיתָא, מַאן דְיֵיכוּל מֵהַהוּא חֵלֶב וְדָם דִּמְקָרְבִין מִנֵּיהּ לְמַדְבְּחָא יִשְׁתְצֵי מֵהַהוּא מַדְבְּחָא, הַאי דִכְתִיב וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מְעַמֵיהָ. מַאי טַעְמָא בְּגִין דַהֲוָה לֵיהּ לְמִקְרֶבֵיהּ לְהַהוּא חֵלֶב עַל מַדְבְּחָא וְהַהוּא דָּם <Nonei></i>בַּיְסוֹד לְאַכְלָלָא מִדַּת יוֹם בַּלַּיְלָה וּמִדָּת לַיְלָה בְּיוֹם. וּבְעוֹלָת הַתָּמִיד דְאִיהִי כְּלָלָא דְכוֹלָא לְכַפָּרָא עַל כָּל יִשְׂרָאֵל עַל עֲשֵׂה וְעַל לֹא תַעֲשֶׂה הַנִיתָּק לַעֲשֵׂה. מַאי טַעְמָא בְּגִין דְּהָא אֲרְבָּא (ס\"ת אתרא) דַּרְגָא דְעוֹלָה עֲשֵׂה אִיהוּ.</p>\n<p>וְעַבְדִין לֵיהּ מָתָּנוֹת לְאַכְלָלָא לְהַהוּא אַתְרָא דְּאִקְרֵי כָּ\"ל וּלְיִשְׂרָאֵל. וּלְאָן אַתְרָא יַהֲבִין אִינוּן מָתָּנוֹת. חֲדָא בְּקֶרֶן מִזְרָחִית צְפוֹנִית לְאַתְעָרָא מִזְרָח דְּאִיהוּ רַחֲמֵי וּלְאִתְעָרָא צָפוֹן בְּחֶדְוָה לְגַבֵּיהּ דְּהַהוּא מִזְבֵּחַ. וּלְבָתָר בְּקֶרֶן מָעֲרָבִית דְּרוֹמִית לְאַכְלָלָא הַהוּא מִזְבֵּחַ דְּאִקְרֵי מַעֲרָב בַּדָּרוֹם דְּאִיהוּ חֶסֶ\"ד. וּבְגִין כָּךְ כֹּלָּא חֲדָא מַתָּנָה הֲדָא הוּא דִכְתִיב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. שְׂמֹאלוֹ דְּמִזְרָח דְּאִיהוּ צָפוֹן תַּחַת לְרֹאשִׁי בְּקַדְמִיתָא. וְהָדָר וִימִינוֹ תְּחַבְּקֵנִי דְּאִיהוּ חֶסֶ\"ד.</p>\n<p>דָבָר אַחֵר מַאי טַעְמָא דְלָא יַהֲבִין מַתָּנָה בְּקֶרֶן דְּרוֹמִית מִזְרָחִית, צְפוֹנִית מַעֲרָבִית. דְּהָא הַהוּא קֶרֶן דְּרוֹמִית מִזְרָחִית אִיהוּ בְּקַדְמִיתָא כַּד סָלְקִין כַּהֲנַיָּא בְּהַהוּא כֶּבֶשׁ דְבַדָּרוֹם סִטְרָא וְחוּלָקָא דִידְהוּ דְּאִיהוּ חֶסֶ\"ד. וְאַמְרִין כָּל פְּנִיוֹת שְׁאַתָּה פוֹנֶה אִיהוּ אֶלָּא דֶּרֶךְ יָמִין לַמִּזְבֵּחַ בְּגִין לְחַבְּרָן סִטְרָא דְּמִזְרָח בְּהַהוּא מִזְבֵּחַ וַהֲוָה לֵיהּ לְכַהֲנָא לְמֵיהַב מַתָּנָה בְּקַדְמִיתָא בְּהַהוּא קֶרֶן דְּרוֹמִית מִזְרָחִית דְּהַאי אִיהוּ קַדְמָאָה לְאִינוּן דַּרְגִּין וְלֹא עוֹד אֶלָּא דְּאִתְעָר לְגַבָּהּ חֶסֶ\"ד בְּקַדְמִיתָא. הָא אִתְעָרוּ חַבְרַיָּיא וְאַמְרִין בְּגִין דִכְתִיב (ויקרא ד׳:ז׳) אֶל יְסוֹד מִזְבַּח הָעוֹלָה מִן יְסוֹד לַמִּזְבֵּחַ שֶׁל עוֹלָם (ס\"א עולה) כְּלוֹמַר קָרֵב יְסוֹד דְּאִיהוּ צַדִּיק לְגַבָּהּ, וְקֶרֶן דְּרוֹמִית מִזְרָחִית לא הָיָה לָה יְסוֹד.</p>\n<p>תָּא חֲזֵי, כְּתִיב בֵּיהּ בִּיהוּדָה (בראשית ל״ז:כ״ז) לְכוּ וְנִמְכְּרֵנוּ לַיִשְׁמְעֱאלִים. וּבְגִין דְּאִיהוּ חָב לְגַבֵּי הַהוּא יְסוֹד וְאַפְרֵשֶׁיה מֵהַהוּא אֶרֶץ עִלָּאָה וְיָהַב עֵצָה לְמִזְבַּן יָתֵיהּ. בְּגִין כָּךְ בְּהַהוּא חוּלָקָא דִּידֵיהּ לָא הֲוָה לֵיהּ יְסוֹד.</p>\n<p>וְהָכִי תָנֵינָן מָה הֲוָה חוּלָקֵיהּ דִיהוּדָה הַר הַבַּיִת וּלְשָׁכָיו בַּעֲזָרוֹת. וּמָה הָיָה חוּלָקֵיהּ דְבִנְיָמִן דְּאִיהוּ צַדִּיק לְתַתָּא אוּלָם וְהֵיכָל וּבֵית קֹדֶשׁ הַקֳּדָשִׁים וּרְצוּעָה נַפְקָא מֵחוּלָקֵיהּ דִיהוּדָה דְאִיהִי כְּלַפֵי מִזְרָח דְּהָא דְּגָלוּ נָמֵי מִמִּזְרָח הֲוָה וְנִכְנֵסָה בְּחוּלָקֵיהּ דְבִנְיָמִן. וְעֲלָה אִתְבְּנֵי מַדְבְּחָא דְּהָא מַדְבְּחָא חוּלָקֵיהּ דִיהוּדָה הֲוָה כְּדְּאוֹקִימְנָא (בראשית ל') וַתָעֲמֹד מִלֵדֶּת דְקַיְימָא כוֹרְסַיָּיא עַל סָמְכוֹהִי וַהֲוָא סַמְכָא רְבִיעָאָה לְקֳבֵל כְּנֶסֶת יִשְׂרָאֵל דְאִיהִי רְבִיעָאָה וּכְתִיב בָּהּ (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וְדָוִד בְּרֵיהּ אֲחִיד בֵּיהּ בְּהַהוּא מִזְבֵּחַ כְּדְּאוֹקִימְנָא בְּרָזָא דִמְהֵימְנוּתָא</p>\n<p>וּבִנְיָמִן הַצַּדִּיק מִצְטָעֵר עָלֵיהּ לְקָרְבָא יָתֵהּ לְגַבֵּיהּ, הֲדָא הוּא דִכְתִיב (דברים ל״ג:י״ב) חוֹפֵף עַלָּיו כָּל הַיּוֹם. בְּגִין כָּךְ זָכָה בִנְיָמִן הַצַּדִּיק לְתַתָּא וְנַעֲשָׂה אוּשְׁפִּיזָא לִגְבוּרָ\"ה הֲדָא הוּא דִכְתִיב (דברים ל״ג:י״ב) וּבֵין כְּתֵפָיו שָׁכֵן דְּאִיהוּ חוּלָקֵיהּ בַּמָעֲרָב</p>\n<p>וְהַשְׁתָּא שְׁכִינְתָּא בֵּין תְּרֵין צַדִּיקִים. צַדִּיק לְעֵילָא יוֹסֵף הַצַּדִּיק. לְתַתָּא בִנְיָמִן. הַאי בַּעְלָהּ דְמַטְרוֹנִיתָא וְהַאי אוּשְׁפִּיזָא. בְּגִין כָּךְ כְּתִיב (תהילים קי״ג:ט׳) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת דָא עַלְמָא דְאִתְכָּלְיָא (ס\"א דאתגלייא) דָא שְׁכִינְתָּא תַּתָּאָה דְאִיהִי עֲקֶרֶת הַבַּיִת. עִיקָרָא דְּהַאי עַלְמָא רָחֵל בֵּין תְּרֵין צַדִּיקִים לְעֵילָא וְתַתָּא.</p>\n<p>בְּגִין כָּךְ אִתְקְרֵי בֵּי מַקְדְּשָׁא בֵּית עוֹלָמִים. מִזְבֵּחַ שֶׁל בֵּית עוֹלָמִים הֲוָה בְּאַחֲסָנָתֵּיה דְבִנְיָמִן. אֲבָל כַּד שַׁרְיָיא שְׁכִינְתָּא בְּאַחֲסָנָתֵּיה דְיוֹסֵף בְּשִׁילֹה לֹא קָארֵי לָה בֵּית עוֹלָמִים דְּהָא עוֹלָם הוֹ\"ד לְעֵילָא וְתַתָּא אֵם הַבָּנִים שֶׂמְחָה דָא שְׁכִינְתָּא בְּגִין כָּךְ הַלְלוּיָהּ.</p>\n<p>תָּא חֲזֵי כַּד אִזְדַּבָּן הַהוּא צַדִּיק לְמִצְרָיִם בִנְיָמִן אֲחוּהִי הֲוָה צַדִּיק לְתַתָּא וְנָטַל אַתְרֵיהּ דְלָא לְאִתְפָּגְמָא וּלְאִינוּן עֲשָׂרָה בְּנִין דַהֲווּ לֵיהּ קָרָא לוֹן עַל שְׁמֵיהּ דְּהַהוּא צַדִּיק כְּדְאוּקְמוּהַ חַבְרַיָּיא בֶּלַע עַל שֵׁם שְׁנִבְלָע בֵּין הָאוּמוֹת</p>\n<p>בְּגִין כָּךְ תָנֵינָן הַיְסוֹד הָיָה מְהַלֵּךְ עַל פְּנֵי כָּל הַמָעֲרָב וְעַל פְּנֵי כָּל הַצָּפוֹן אוֹכֵל בַּמִזְרָח חֲצִי אָמָה וּבַדָרוֹם חֲצִי אָמָה בְּגִין דְּחוּלָקֵיהּ דְבִנְיָמִן הֲוָה מַעֲרָב בְּגִין כָּךְ אִית לֵיהּ יְסוֹד דְּהָא הוּא שָׁלִיט הֲוָה לְגַבֵּי הַהוּא צַדִּיק יְסוֹד עוֹלָם אֲבָל בְּחוּלָקֵיהּ דִיהוּדָה דְּאִיהוּ מִזְרָח לָא הֲוָה לֵיהּ יְסוֹ\"ד דְּהָא אִיהוּ אֲרְחִיקֵיה מִנֵּיהּ דִּיהַב עֵצָה לְמִזְבְּנֵיה לְמִצְרָיִם.</p>\n<p>תָּא חֲזֵי סִדְרָא דְּדְגָלִּים הֲרֵי הוּא סָחְרָנֵי הַהוּא מַדְבְּחָא דְעוֹלָה דְּאִקְרֵי מַשְׁכְּנָא. יְהוּדָה וְדִּסְמִיכִין לֵיהּ בַּמִזְרָח. וּמַאן סְמִיכִין יִשָׂשׂכָר דְּאַגִין עָלֵיהּ בְּחֵילָא דְּאוֹרַיְיתָא. וּלְבָתָר זְבֻלוּן דְסָמִיךְ לְיִשָׂשׂכָר דִּיהַב לוֹן מְלָאי וְחֵילָא לְאִתְעַסְקָא בְּאוֹרַיְיתָא. אֶפְרָיִם וּמְנַשֶׁה וּבִנְיָמִן לְמַעֲרָב. רְאוּבֵן וְדִּסְמִיכִין לֵיהּ בַּדָרוֹם דָן וְדִּסְמִיכִין לֵיהּ בַּצָּפוֹן.</p>\n<p>וְתָּא חֲזֵי כְּתִיב בֵּיהּ בְּהַהוּא צַדִּיק (בראשית ל״ז:ב׳) וְהוּא נַעַר אֶת בְּנֵי בִּלְהָה וּכְתִיב בִּבְנִי לֵאָה (שם) וַיִשְׂנֵאוּ אוֹתוֹ בְּגִין כָּךְ תָנֵינָן הַאי יְסוֹ\"ד הָיָה מְהַלֵּךְ עַל פְּנִי כָּל הַמָעֲרָב דְּהָא חוּלָקֵיהּ דְּאַחוֹי דְּנָטַר הַהוּא אַתְרָא וְדִבְנוֹי הֲוָה. וְעַל פְּנִי כָּל הַצָּפוֹן בְּגִין דְהַנְהוּ דַהֲווּ שָׁרָאָן בַּצָּפוֹן לָא הֲווּ שָׂנְאִין לֵיהּ.</p>\n<p>אוֹכֵל בַּמִזְרָח חֲצִי אָמָה. בְּגִין דְּעָבַד יְהוּדָה פַּלְגוּ הַצָלָה וְאָמַר מָה בֶּצַע וְלֹא שָׁבָק (לון) לְמִקְטְלֵיהּ. וּבַדָרוֹם חֲצִי אָמָה בְּגִין דִרְאוּבֵן אָמַר (בראשית ל\"ז) לְהַצִיל אוֹתוֹ <Nonei></i>מִיַדָּם וְגָד נָמֵי דַהֲוָה שָׁרֵי תַמָּן לָא הֲוָה סָנֵי לֵיהּ.</p>\n<p>תָּא חֲזֵי כַּמָה עֲקִימִין אִינוּן בְּנֵי נָשָׁא דְלָא בָעָאן לְאִשְׁתָּדְלֵי בְּאָרְחָא דְחַיֵי דְאוֹרִית לוֹן קוּדְשָׁא בְּרִיךְ הוּא לִבְנוֹי וְאַזְהָר לוֹן עֲלָהּ וְאָמַר (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה דְּלֵית לָךְ רֵשׁוּ לְאַפְרָשָׁא יוֹם מִּלַּיְלָה. וּבְגִין כָּךְ יְהוּדָה אַף עַל גַּב דְּחוּלָקֵיהּ וְעַדְבֵיהּ הֲוָה מַעֲרָב דְּאִיהוּ לַיְלָה כַּד הֲוָה שָׁארֵי סַחֲרָנֵיהּ הַהוּא מַשְׁכְּנָא אִתְדַבַּק בַּמִזְרָח דְּאִיהוּ יוֹם וְקוּדְשָׁא בְּרִיךְ הוּא רָמַז לֵיהּ וְאָמַר לֵיהּ (דברים ל׳:י״ט) וּבָחַרְתָּ בַּחַיִּים דְלָא לְאַפְרָשָׁא יוֹם מִּלַּיְלָה וּמַאן דְפַרִישׁ לוֹן גָרִים מוֹתָא.</p>\n<p>וּבְהַהוּא חוֹבָה מִיתוּ בְּנוֹי בְּגִין דְחַבִילוּ אוֹרְחֵיהוֹן וְלָא דַבִּיּקוּ יוֹם בַּלַּיְלָה בְּגִין דְלָא אִשְׁתָדְלוּ כְּדְקָא חָזֵי לְחַבְּרָא חִוְורָא בְסֻמָּקָא בְּגִין לְכַפָּרָא הַהוּא חוֹבָה דִילֵיהּ דְאַפְרִישׁ לוֹן בְּקַדְמִיתָא. כַּד זַבִּין לְהַהוּא צַדִּיק דְּאִקְרֵי יוֹם דְאַפְרֵשֶׁיה מכְּנְסֶת יִשְׂרָאֵל דְּאִקְרֵי לַיְלָה. וְרָמַז לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְקָרְבָא מִזְרָח בַּמָעֲרָב וְאָמַר לֵיהּ (במדבר ב׳:ג׳) וְהַחוֹנִים קְדְמָה מִזְרָחָה דֶגֶל מַחֲנֶה יְהוּדָה לְקָרְבָא מִזְרָח לְמַעֲרָב לְמֵיהַב לֵיהּ שֶׁפַע בִּרְכָאָן מִלְּעֵילָא.</p>\n<p>וּבְנֵי יוֹסֵף וּבִנְיָמִן אַף עַל גַּב דְבִנְיָמִן הֲוָה מִתְדַּבָּק בַּמִזְרָח, רָמַז לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמִשְׁרֵי בַּמָעֲרָב לְקָרְבָא כְּנֶסֶת יִשְׂרָאֵל לְגַבֵּי צַדִּיק כֹּלָּא בְּאֹרַח מֵישַׁר הֲדָא הוּא דִכְתִיב (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ וְצַדִּיקִים יֵלְכוּ בָּם. וּרְאוּבֵן דְאִתְדַבָּק בְּסִטְרָא דְחֶסֶ\"ד יִשְׁרֵי בִּדְרוֹמָא. וְדָן בְּגִין לְכַפָּרָא הַהוּא חוֹבָא דְעֶגְלָא דִיקַבְּלוּן בְּנוֹי וְאִיהוּ מִסִּטְרָא דִּצְפוֹנָא יִשְׁרֵי לִצְפוֹנָא לְכַפָּרָא הַהוּא חוֹבָה.</p>\n<p>בְּגִין כָּךְ כְּתִיב בַּיָם שֶׁעָשָׂה שְׁלֹמֹה עֲשָׂרָה עַל עֲשָׂרָה (מלכים א ז׳:כ״ג) וְקַו שְׁלֹשִׁים בַּאָמָה יִסוֹב. כֻלָּא בְּרָזָא דְחָכְמְתָא. כְּתִיב בֵּיהּ עוֹמֵד עַל שְׁנֵים עֲשָׂר בָּקָר שְׁלשָׁה פּוֹנִים צָפוֹנָה וּשְׁלשָׁה פּוֹנִים יָמָּה וּשְׁלשָׁה פּוֹנִים נֶגְבָּה וּשְׁלשָׁה פּוֹנִים מִזְרָחָה וְהַיָּם עֲלֵיהֶם מִלְמַעְלָה הַהוּא יַמָּא דְחָכְמְתָא אִתְתְּקַן בְּהוּ.</p>\n<p>תָּא חֲזֵי כַּד הֲווּ עַבְדִין כַּהֲנַיָּא הַהוּא חַטָּאת לְכַפָּרָה חוֹבִין דְלא תַעֲשֶׂה הֲוָה דְּאִית בְּהוּ כָּרֵת. וְעוֹלֶה לְכַפָּרָה עַל מַאן דְלָא עֲבִיד מִצְוֹת עֲשֵׂה אָתֵי וּמֵהַהוּא סִטְרָא אָתֵי עוֹלָה דְּאִיהוּ זָכָר. וּכְתִיב (שמות כ׳:ח׳) זָכוֹר אֶת יוֹם הַשַׁבָּת מִצְוַת עֲשֵׂה וּבְגִין כָּךְ אָנוּ מַקְרִיבִין בְּשַׁבָּת תְּרֵין אִמְרִין דְּמוּסָף עוֹלָה בְּגִין דְּבְהַהוּא דִיְמִינָא אִתּוֹסַף לְהַהוּא צַדִּיק נְהִירוּ דְעַתִּיקָא קַדִּישָׁא. כַּד אִתְדַבַּק בִּכְּנֶסֶת יִשְׂרָאֵל דְּאִיהִי שָׁמוֹר לֹא תַעֲשֶׂה</p>\n<p>בְּגִין כָּךְ אִית בֵּיהּ בְּשַׁבָּת עֲשֵׂה וְלֹא תַעֲשֶׂה דְּאִית בֵּיהּ כָּרֵת דְּהָא מַאן דְּעָבַד פְּגִימוּ בְּהַהוּא אַתְרָא דְּאִקְרֵי לא תַעֲשֶׂה וְאַפְרֵישׁ זִווּגָא דִילְהוֹן אִשְׁתָצֵי מִתַּמָּן נַפְשָׁא דִילֵיהּ. וּמַאן אִיהוּ, מַאן דְּעָבִיד עוֹבָדִין דְּחוֹל בְשַׁבְּתָא בַּקֹּדֶשׁ דְאִתְדַבָּק בְּשַׁבָּת בְּשַׁבָּתוֹן וְכֻלְּהוּ עָלְמִין בְּחֶדְוָה בִּנְהִירוּ אֲבָל מַאן דְלָא עֲבִיד אֶלָּא בִּשְׁגָגָה מַקְרִיב חַטָּאת לְקֳבֵל הַהוּא דַּרְגָא דְמִזְבֵּחַ.</p>\n<p>וּבְרֹאשׁ חוֹדֶשׁ דְּאִיהוּ חַדְּתוּתָא דְסִיהֲרָא אֲנָן מַקְרִיבִין (במדבר כ״ח:י״א) פָּרִים בְּנֵי בָּקָר שְׁנַיִם דְּהָא מִסִּטְרָא דְפָרָה אֲדוּמָה תְמִימָה אָתוּ וְאִינוּן לְעֵילָא לְאַשְׁלָמָא פְּגִימוּ דִּילָה וּלְמֵיהַב לָהּ שֶׁפַע עַל חַד תְרֵין מֵהַהוּא אֲתַר דְּאִקְרֵי עוֹלָה וְאִתוֹסָף בְּהַהוּא זִמְנָא נְהִירוּ לְסִיהֲרָא אַיִל אֶחָד לְקָרְבָא לָהּ אֵילוֹ דְּיִצְחָק (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי</p>\n<p>כְּבָשִׂים בְּנֵי שָׁנָה שִׁבְעָה לְחַבְּקָא לָהּ יְמִינָא וְשַׁבְעָא דַּכְרִין אִתְקַרְבִין בָּהּ תְמִימִים שְׁלֵמִין בְּכוֹלָא וַאֲנָן מְקָרְבִין שֵׂעִיר עִזִים אֶחָד לְחַטָּאת דְּהַאי חַטָּאת מֵהָאי סִטְרָא דְפָּר חַטָּאת אָתֵי דִכְתִיב שָׁמוֹר. וְשָׁמוֹר לֹא תַעֲשֶׂה אִיהוּ וַאֲנָן מְקָרְבִין שֵׂעִיר חַטָּאת דְאָתֵי עַל לֹא תַעֲשֶׂה. בְּמוּסָף דִּידָהּ בְּרֹאשׁ חוֹדֶשׁ דְאָתֵי לְכַפָּרָה עַל טוּמְאַת מִקְדָּשׁ וְקֹדָשָׁיו דִכְתִיב (יחזקאלמ\"ג) וְלָא יְטָמְאוּ עוֹד בֵּית יִשְׂרָאֵל שֵׁם קָדְשִׁי דְלָא יִתְקַרָב בִּכְנֶסֶת יִשְׂרָאֵל עָרֵל וְטָמֵא.</p>\n<p>אֲבָל מוּסָף דְּשַׁבָּת לֵיכָּא לְקָרְבָא בְּגִין דְּהָא אִתְגְּלֵי עַתִּיקָא קַדִּישָׁא וְנָהִיר בְּהַהוּא רָצוֹן לְכֻלְּהוּ עָלְמִין וְכֹלָּא אִשְׁתְּכַח בִּנְהִירוּ, דְּהָא שַׁבָּת בְלָא דִינָא כְּלָל אִיהוּ וְלָא שָׁלִיט חִוְיָּיא עֲקִימָא וְכַהֲנֵי מִסִּטְרָא דְחֶסֶ\"ד נַכְסִין יָתֵיהּ בִּצְפוֹנָא דְמִזְבֵּחַ וְאֲפִילּוּ יִשְׂרָאֵל יַכְלִין לְמֶעְבָּד, בָּר דְּלֵית לוֹן רֵשׁוּ לְמִקְרַב לְהַהוּא לַמִּזְבֵּחַ לְקָרְבָא אֲבָל לְמֵיכַס שָׁרֵי.</p>\n<p>וּבִצְפוֹנָא אִיהוּ אַתְרֵיהּ דְּהַהוּא שָׂעִיר דְּהָא שָׂעִיר מִצְפוֹנָא יָנִיק וַאֲנָן מְקָרְבִין דָּמָא לְמַדְבְּחָא וְעַבְדִּין ד' מָתָּנוֹת עַל ד' קְרָנוֹת בְּגִין לְאַקַפָא לָהּ מִכָּל סִטְרִין דְלָא יִתְקַרָב מַאן דְלָא חֲזֵי לְקָרְבָא לְקֹדֶשׁ הַקֳּדָשִׁים וְהַאי חַטָּאת דְעֲבְדִינָן מִנֵּיהּ קֹדֶשׁ הַקֳּדָשִׁים, אִיהוּ דְלָא יִתְעֲר סִטְרָא דִמְסָאֲבָא מִנֵּיהּ בְּעַלְמָא.</p>\n<p>וְתָּא חֲזֵי בְּעוֹלָה ב' מָתָּנוֹת שְׁהֵן אַרְבַּע רָזָא דְּיִחוּדָא דְּמִתְיַחֵד עוֹלָה בַּמִזְבֵּחַ. אֲבָל חַטָּאת אַרְבַּע מָתָּנוֹת דְלָאו אִינוּן אֶלָּא לְנַטְרָא וּלְאַקַפָא אִינוּן גִבּוֹרִין דְּאִינוּן מִסִּטְרָא דִגְבוּרָה לְהַהוּא מִטָּה כּוּרְסַיָּיא קַדִּישָׁא וּלְאַשְׁלָמָא הַהוּא פְּגִימוּ דְּעָבְדוּ בָּהּ. וּמַאן דְּגָרִים לוֹן לִבְנִי נָשָׁא לְמֶעְבָּד הַהוּא חוֹבָה מִסִּטְרָא דְּשָׂעִיר אָתֵי, בְּגִין כָּךְ חַטָּאת יָחִיד שְׂעִירָה וְחַטָאת נָשִׂיא שָׂעִיר, וְחַטָאת כֹּהֵן מָשִׁיחַ פָּר, כּוּלְהוּ מִסִּטְרָא דִשְׂמָאלָא.</p>\n<p><Nonei></i>וּלְזִמְנִין קַרִיב יָחִיד כִּשְׂבָּה לְקֳבֵל כְּנֶסֶת יִשְׂרָאֵל וְכֻלְהוּ שְׁאָר מִצְוֹת. אֶלָּא בַּעֲבוֹדָה זָרָה דְּצִבּוּר מְקָרְבִין פָּר לְעוֹלָה וְשָׂעִיר לְחַטָּאת וְהַהוּא חַטָּאת חֲסֵר אִיהוּ בְלֹא אַלֶף. בְּגִין דְּאִיהוּ גְרִיעוּת סַגִּיאָה דְּהָא חַטָּאת לִישָׁנָא דִגְרִיעָא הוּא דִכְתִיב (מלכים א א׳:כ״א) וְהֲיִיתִּי אֲנִי וּבְנִי שְׁלֹמֹה חַטָּאִים. וְכָל חַד עֵז בַּת שְׁנָתוֹ מִסִּטְרָא דִשְׂמָאלָא. וְהַהוּא פָּר דוֹרוֹן לְעֵילָא אִיהוּ לְצַדִּיק דְּאַפְרִידוּ הַהוּא אֲרוֹן מֵהַהוּא בְּרִית. וְשָׂעִיר לְחַטָּאת לְקֳבֵל כְּנֶסֶת יִשְׂרָאֵל דְּמָנְעוּ מִינָהּ בִּרְכָאָן. וְעִם כָּל דָּא יָחִיד כַּד חָב בְּכֻלְּהוּ מִצְוֹת לא תַעֲשֶׂה דְּאִית בְּהוּ כָּרֵת. שְׂעִירָת עִזִים בָּעֵי לְקָרְבָא לְכַתְּחִלָּה, אֶלָּא כַּד לֵית לֵיהּ דְּיַקְרִיב כִּשְׂבָּה.</p>\n<p>וְתָּא חֲזֵי כְּנֶסֶת יִשְׂרָאֵל רְבִיעִית הִיא לְיוֹמֵי וּבְגִין כָּךְ ד' מָתָּנוֹת בַּעְיָא, וְסַלִּיק הַהוּא רֵיחַ נִיחֹחַ מֵאִינוּן אִמְרִין. וּכְדֵין נְיָיחָא לכְּנֶסֶת יִשְׂרָאֵל וְלָא עֲבְדַת נוּקְמִין דְּהָא בְּשׁוֹגֵּג הֲוָה.</p>\n<p>(במדבר כ״ח:ט״ז) וּבַחוֹדֶשׁ הָרִאשׁוֹן דְּאִיהוּ אַרְבָּעָה עַל עֲשַׂר עַבְדִינָן פֶּסַח בְּגִין דְּיֶהוֶי דְכִיר לָן לְעֲלָם הוּא פֶּסַח דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, דְּקָטַל הַהוּא טָלֶה וְאַפִּיק שְׁכִינְתָּא וְיִשְׂרָאֵל מֵאַתְרָא מְסָאָבָא וְאִתְחַבָּר אַרְבָּעָה בְּעֲשוֹר כְּנֶסֶת יִשְׂרָאֵל אִתְחַבְּרָא בְּעֲשוֹר דְּאִיהוּ צַדִּיק וְרָמִיז אַתְרֵיהּ בְּעֶשֶׂר. וּכְדֵין פֶּסַח לַיְיָ,</p>\n<p>וּבְגִין כָּךְ מַאן דְּאִיהוּ טָהוֹר וְיִסְתַּלַּק מִנֵּיהּ הַהוּא עָרְלָה וְיִתְחָזֵי רְשִׁימָא קַדִּישָׁא דְצָדִי\"ק דְּאִיהוּ י' בֵּיהּ וְלָא קָרִיב פֶּסַח לַיְיָ (דאיהו) כְּנֶסֶת יִשְׂרָאֵל לְצַדִּיק דְהוּא חֲזֵי לְקָרְבָא לְמַקְדְּשָׁא וְלֹא עָרֵל וְטָמֵא, דְּאִי לָא קַרִיב אִית בֵּיהּ כָּרֵת.</p>\n<p>וּמַאי טַעְמָא דְּהָא כָּל אוֹרַיְיתָא לָא אִית בָּהּ כָּרֵת אֶלָּא עַל מִצְוֹת לא תַעֲשֶׂה. מַאי (ומאי) טַעְמָא בְּפֶּסַח וּמִילָּה דְּאִינוּן מִצְוֹת עֲשֵׂה כָּרֵת. אֶלָּא בְּגִין דְדַרְגָא קַא גָרִים דְּאִיהִי כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי פֶּסַח, וְאִקְרֵי (אקרי) מִצְוֹת לא תַעֲשֶׂה, בַּעְיָא לְאִתְחַבְּרָא בַּעֲשֵׂה וּלְאִתְכַּלְלָא בֵּיהּ מִדַּת לַיְלָה בְּיוֹם. וּמַאן אִיהוּ דָא צַדִּי\"ק, דְּאִיהוּ מִילָה וּמִצְוֹת עֲשֵׂה וְאִתְכְּלִיל בְּמִצְוֹת לא תַעֲשֶׂה מִדַּת יוֹם בַּלַּיְלָה. וְאִי לָא אִתְגְּזַר בָּר נָשׁ לָא אִתְחֲזֵי לְקָרְבָא לוֹן,</p>\n<p>בְּגִין כָּךְ קַיָימָא מִצְוַת לֹא תַעֲשֶׂה עָלֵיהּ וְדַיְינָת לֵיהּ בְּכָּרֵת, דְּלָא יֵיעוּל נַפְשֵׁיהּ לְמַקְדְּשָׁא. וְכֵן בְּפֶּסַח בַּעְיָא כְּנֶסֶת יִשְׂרָאֵל לְאִתְחַבְּרָא בְּבַעְלָהּ וְאִי לָא עֲבִיד בָּר נָשׁ וְלָא קַרִיב פֶּסַח לַיְיָ, קַיָימָא עָלֵיהּ וְדַיְינָת לֵיהּ וְלָא אַפִּיקַת יָתֵיהּ מִתְּחוֹת יְדָא דְפַרְעֹה וְאִשְׁתַּצִיאַת נַפְשֵׁיהּ מֵאַתְרָא קַדִּישָׁא, וְאִשְׁתָּאַרַת בְּאַתְרָא מְסָאָבָא בְּמִצְרָיִם. דְּהָא יִשְׂרָאֵל אִי לָא עֲבִידוּ הֲנֵי תְּרֵין פִּקּוּדִין לָא נַפְקוּ מִתַּמָּן.</p>\n<p>וּבְגִין כָּךְ כְּתִיב (דבהם י\"ז) שָׁמוֹר אֶת חֹדֶשׁ הָאָבִיב וְעָשִׂיתָ פֶּסַח לַיְיָ אֱלֹהֶיךָ. שָׁמוֹר, כְּלָלָא דְנוּקְבָא לא תַעֲשֶׂה. אֶת, כְּלָלָא דְכוֹלָא. חֹדֶשׁ הָאָבִיב דְּהָא בְּהַהוּא שַׁעְתָּא שְׂעוֹרָה אֲבִיב וּמְקָרְבִין מִנֵּיהּ עוֹמֶר עֲשִׂירִית הָאֵיפָה מִמָחֳרָת הַשַּׁבָּת אִיהוּ, וְסַפְרִין שֶׁבַע שְׁבוּעִין שְׁלֵמִין לְאִסְתַּלְקָא לְעֵילָא וּלְקַבְּלָא מֵאִינוּן חַמְשִׁין יוֹמִין עִלָּאִין דְּאִימָא עִלָּאָה אוֹרַיְיתָא. דְּאִקְרֵי לֶחֶם דִכְתִיב (משלי ט׳:ה׳) לְכוּ לַחֲמוּ בְּלַחְמִי.</p>\n<p>וַאֲנָן מְקָרְבִין בְּיוֹמָא דְּחַמְשִׁין דְאִתְיְיהִיב בֵּיהּ אוֹרַיְיתָא שְׁתֵּי הַלֶּחֶם, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה. וְנָחִית טִיבוּ דְּעַתִּיקָא קַדִּישָׁא דְּאִימָא עִלָּאָה בְּאִינוּן שֶׁבַע שְׁבוּעִין שְׁלִימָן בְּכוֹלָא. וְכָל חַד מֵאִינוּן שֶׁבַע דַּרְגִּין כַּלִיל בְּשִׁבְעָה כְּדְּאוֹקִימְנָא בְּרָזָא דִמְהֵימְנוּתָא.</p>\n<p>בְּגִין כָּךְ (דברים ט״ז:א׳) שָׁמוֹר אֶת חֹדֶשׁ הָאָבִיב וְעָשִׂיתָ פֶּסַח לַיְיָ, קַרִיב לוֹן בְּיִחוּדָא. דְּהָא בֵּיהּ אֲפְּקַךְ מִמִּצְרָיִם לַיְלָה, וְתַשְׁלִים לְהַאי דַּרְגָא דְּאִקְרֵי לֵיל שִׁמּוּרִים, וְתַּקְרִיב דְכוּרָא לְגַבָּהּ וְתִתְקְרֵי לַיְלָה שְׁלֵימָא. וְתָּא חֲזֵי נַעֲרָה בְּתוּלָה עַד לָא אִתְקַרִיב דְכוּרָא לְגַבָּהּ אִקְרֵי נַעַר, לְבָתָר אִקְרֵי נַעֲרָה. הֲדָא הוּא דִכְתִיב (דברים כ״ב:י״ט) וְנָתְנוּ לַאֲבִי הַנַּעֲרָה, שְׁלֵימָא דַּיְיקָא. וְדָא אִיהוּ כַּד אִשְׁתַּכְּחַת שְׁלֵימָא וְלָא אִתְקַרִיב מַאן (ס\"א למאן) דְלָא אִתְחֲזֵי. אוּף הָכָא בְּקַדְמִיתָא לֵיל שִׁמּוּרִים לְבָתָר, הַלַּיְלָה הַזֶּה לַיְיָ, כַּד אִתְקַרִיב זֶה לְזֹאת.</p>\n<p>בְּגִין כָּךְ לָא אִתְחֲזֵי לְאִתְקָרְבָא בְּהַהוּא פֶּסַח עָרֵל וְטָמֵא. וְדָמָהּ טָעוּן מַתָּנָה אַחַת דַּיְיקָא, כְּמָה דָּא אָמֵר (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. הִיא נָטְרָת בְּנָהָא דְלָא יִסְתַּאֲבוּן בְּנִמוּסָיְיהוּ יִשְׂרָאֵל, בְּגִין כָּךְ שִׁבְטֵי יָהּ נַפְקוּ מִתַּמָּן וְאִתְחַבְּרַת יוֹ\"ד בָּה\"א וְלָא בַּאֲתַר אַחֲרָא כְּמָה דְּעָבְדוּ אִינוּן.</p>\n<p>אֲבָל כַּד נַפְקוּ מִבָּבֵל דְּאִסְתָאֲבוּ תַמָּן, סָאִיבוּ מַקְדְּשָׁא. בְּגִין כָּךְ חִוְיָּיא שָׁלִיט בְּהוּ וְלָא אִשְׁתְּכַח שׁוּלְטָנוּתָא לְיִשְׂרָאֵל בְּהַהוּא זִמְנָא, בְּגִין דְּסָאִיבוּ מַקְדְּשָׁא בַּנָּשִׁים נָכְרִיּוֹת. מִכָּאן מַאן דִּמְסָאֵב גַּרְמֵיהּ לְתַתָּא, מְסָאֵב לְעֵילָא. וּמַאן דְּקַדִּישׁ גַּרְמֵיהּ לְתַתָּא מְקַדֵּשׁ לְעֵילָא. וְעַל דָא רְאוּיִּין הֲווּ דְּיִתָעֲבַד לְהוּ נִיסָא בְּהַהִיא שַׁעְתָּא דְּנַפְקוּ מִבָּבֶל כְּשָׁעְתָּא דְּנַפְקוּ מִמִּצְרָיִם. אֶלָּא דְּגָרִים חוֹבָא.</p>\n<p>וּבַחֲמִשָׁה עֲשָׂר לְיָרְחַא קַדְמָאָה חוּלָקָא דְאַבְרָהָם דְּאִיהוּ קַדְמָאָה וְאַחִיד בְּדַרְגָּא דְחֶסֶ\"ד. אֲנָן מַקְרִיבִין לְקוּדְשָׁא בְּרִיךְ הוּא תְּרֵין פָּרִים לְאוֹסָפָא תְּרֵין חוּלָקִין לְדַרְגָּא דְחֶסֶד מֵעַתִּיקָא קַדִּישָׁא. אַיִל אֶחָד לְקֳבֵל דַּרְגָא דְיִצְחָק וּבָעֵינָן אַיִל לִישָׁנָא דְּתַקִיפוּ, בְּגִין דְּחוּלָקַא דִּידֵיהּ תַּקִּיפוּ מַיָא. וּבָעֵינָן דְּיִסְתָּכַּם הַהוּא דַּרְגָא דִּגְבוּרָ\"ה בְּחֶסֶד עִלָּאָה לְמֶעְבַּד טִיבוּ עִם <Nonei></i>כָּל יִשְׂרָאֵל. וּלְאִתְפָּרְעָא מֵאִינוּן דְּעֲאקִין לוֹן וּלְאַסְחֲרָא לֵיהּ סִטְרָא דְּמַיִּין, הַאי דִכְתִיב (בראשית ל׳:ל״ז) מָחְשׂוֹף הַלָּבָן.</p>\n<p>שִׁבְעָה כְּבָשִׂים תְמִימִים. לְקֳבֵל כֻּלְּהוּ דַּרְגִּין דְּיִשְׁתַּלְּמוּן בֵּיהּ. וְכֵן בְּכָל יוֹמָא וְיוֹמָא שִׁבְעָה אִמְרִין בְּיוֹמָא קַדְמָאָה דְּכוּלְהוּ שִׁבְעָה יוֹמִין עִלָּאִין כָּל חַד אִשְׁתְּלִים בְּרָזָא דְשֶׁבַע וִיהוֹן שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת לְקֳבְּלָא נְהִירוּ עִלָּאָה דְּאוֹרַיְיתָא. שֵׂעִיר חַטָּאת לְכַפָּרָה עַל סָאִיבוּ דְּמָקְדְּשָׁא וְלָא יְהֵא לֵיהּ רֵשׁוּ לְהַהוּא שָׂעִיר לְעֲרְבְּבָא וְלָא לְאַסְטָנָא עַל יִשְׂרָאֵל.</p>\n<p>(במדבר כ״ח:כ״ו) וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה. לְקֳבֵל דַּרְגָא דְיַעֲקֹב דְּהָא כְּדֵין אִשְׁתְּלִים עַלְמָא וְאִתְחַדַּשׁ. וַאֲנָן מָנִינָן שֶׁבַע שְׁבוּעִין בְּגִין לְחַבְּרָא כֹּלָּא בְּיוֹבְלָא עִלָּאָה דְּיַהֲבָא לְהַאי בְּרָא בּוּכְרָא עֲטָרָה דְּאוֹרַיְיתָא דְּאִתְכַּלִילָת בְּמ\"ט אַנְפִּין וְנַפְקָא מֵחָכְמָה עִלָּאָה בְּאִינוּן חַמְשִׁין שַׁעֲרֵי בִּינָה. וְאִתְיְּיהִיבַת לְהַאי בְּרָא בּוּכְרָא עַל יְדֵי דְמֹשֶׁה דְאֲחִיד נָמֵי בְּהַאי דַּרְגָא הֲדָא הוּא דִכְתִיב (שיר השירים ג׳:י״א) צְאֵינָה וּרְאֵינָה בְּנוֹת צִיּוֹן בַּמֶלֶךְ שְׁלֹמֹה, בְּמַלְכָּא דִּשְׁלָמָא כֹּלָּא דִילֵיהּ. (והא) דְּהָא אוֹקִימְנָא דְּהַאי דַּרְגָא שְׁלִים מִכָּל סִטְרִין וּשְׁלִים אִקְרֵי בְּרָזָא דִמְהֵימְנוּתָא דִכְתִיב (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם. בְּיוֹם חֲתוּנָתוֹ. דָא כַּד אִתְיְיהִיבַת (אורייתא). וּבְיוֹם שִׂמְחַת לִבּוֹ. כַּד אִתְבַּנֵי בֵּי מַקְדְּשָׁא:</p>\n<p>תָּא חֲזֵי כְּתִיב בַּחֹדֶשׁ הַשְׁלִישִׁי דְאִתְחַבַּר הַאי דַּרְגָא דְּאִקְרֵי שְׁלִישִׁי בַּחֹדֶשׁ וְהִיא חֲתוּנָתוֹ, עַל דָא כְּתִיב (שמות י״ט:ב׳) וַיִּחַן שָׁם יִשְׂרָאֵל נֶגֶד הָהָר. הַאי דַּרְגָא בְּרָא בּוּכְרָא. נֶגֶד הָהָר לְקֳבֵל הַהוּא הַר דְּאִתְיָּידַע דְּאִיהוּ זְעֵיר מִכָּל טוּרַיָּא דִּלְעֵילָא דְּאִיהוּ רָם וְנָשָׂא כַּד אִתְחַבָּר לְעֵילָא וְאִקְרֵי הַר סִינַי דְּהָא ז' טוּרִין וְז' יוֹמִין וְז' אַרְצוֹת בָּרָא קוּדְשָׁא בְּרִיךְ הוּא בְּעַלְמָא דְּאִינוּן לְקֳבֵל שִׁבְעָה יוֹמִין עִלָּאִין וְלָא בָּחָר מִכֻּלְּהוּ לְמֵיהַב אוֹרַיְיתָא אֶלָּא בְּהַר סִינַי דְּאִיהוּ רָזָא דְּכְּנְסֶת יִשְׂרָאֵל,</p>\n<p>וּבְיָם כִּנֶרֶת נָמֵי דְאָתֵי מִתַּמָּן תְּכֵלֶת דְּדָמֵי לְכִּסֵא הַכָּבוֹד. כְּנֶסֶת יִשְׂרָאֵל. כִּנֶרֶת דָא צַדִּי\"ק וְהַאי יָם דְּכִּנֶרֶת הוּא כְּדְאוּקְמוּהַ חַבְרַיָּיא. כִּנּוֹר הָיָה תָּלוּי לְמָעְלָה מִמִּטָתוֹ שֶׁל דָוִד, וּבְשָׁעָה שְׁרוּחַ צְפוֹנִית מְנַשֶׁבֶת בּוֹ מְנַגֵּן מֵאֵלָיו. וְדָוִד קָם לְמִלְעֵי בְּאוֹרַיְיתָא חֲצוֹת לַיְלָה לְאִתְחַבְּרָא בְּכְּנְסֶת יִשְׂרָאֵל. וּבְאֶרֶץ יִשְׂרָאֵל שְׁבִיעָאָה דְכוֹלָא נְקוּדָה אֶמְצָעִיתָּא דְּאַרְעָא תַּתָּאָה, בָּחַר קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהִי לְקֳבֵל נְקוּדָה עִלָּאָה.</p>\n<p>מָאי טַעְמָא בֵּיהּ בְּהַר סִינַי דִּלְעֵילָא לְמֵיהַב בֵּיהּ אוֹרַיְיתָא שֶׁבִּכְתָב וְסִימָנִיךְ בְּהַאי אֲרוֹן לְמֵיהַב בֵּיהּ בְּרִית, בְּגִין דִּבְּהָאי אֲרוֹן מוּנָחִין כָּל גְנִיזִין טָבִין, וְתוֹרָה שֶׁבִּכְתָב דְּאִקְרֵי בְּרִית בֵּיהּ מוּנָחָא. וְכָל מָאנֵי קְרָבָא דְּמַלְכָּא בִּידֵיהּ אִתְמְסָרוּ, וְכֻלְּהוּ עָלְמִין דִּלְתַתָּא מִינָהּ יַנְקִין. זָכוּ יִשְׂרָאֵל לְמֵיטַר אוֹרַיְיתָא כְּדֵין יַהֲבַת לוֹן כָּל טִיבוּ דְּעָלְמָא. וְאִי לָא כְּדֵין יַסְרָת לוֹן, הֲדָא הוּא דִכְתִיב (ויקרא כ״ו:כ״ח) וְיִסַּרְתִּי אֶתְכֶם אַף אֲנִי, דָּא כְּנֶסֶת יִשְׂרָאֵל. וְכַד תְּחַבֵּר בְּאֲנִ\"י דָּלֶ\"ת דִּילָה אִקְרֵי אֲדֹנָ\"י וְדַּיְינָא לְעָלְמָא.</p>\n<p>בְּגִין כָּךְ כְּתִיב (דברים ד׳:מ״ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה. בְּזֹאת אִתְיְיהִיבַת אוֹרַיְיתָא. תָּא חֲזֵי אוֹרַיְיתָא שֶׁבִּכְתָב צַדִּי\"ק אִקְרֵי, וּמוּנָח בְּזֹאת דְּהַאי בְּרִית מָנְחַא בֵּיהּ, דִכְתִיב אֲרוֹן הַבְּרִית בְּגִין דְּמוּנָח בֵּיהּ בְּרִית דְּאִיהוּ צַדִּי\"ק בְּגִין כָּךְ וְזֹאת הַתּוֹרָה אִתְחַבָּר וא\"ו בְּזֹאת וּכְדֵין אֲשֶׁר שָׂם מֹשֶׁה סַם חַיִּין לְעָלְמָא. דְּהָא אִילָנָא דְחַיֵּי אִתְדַבַּק בָּהּ.</p>\n<p>וְכַד לָא מָכְשְׁרִין בְּנֵי נָשָׁא עוֹבַדָיְיהוּ, אִסְתְּלַק וא\"ו מִזֹאת. וּכְדֵין כְּתִיב (ויקרא י״ד:ב׳) זֹאת תִּהְיֶה תּוֹרַת הַמְצוֹרָע, וְזֶהוּ חָשׁוּב כַּמֵּת. וּכְתִיב (במדבר י״ט:י״ד) זֹאת הַתּוֹרָה אָדָם כִּי יָמוּת בְּאֹהֶל אִסְתָּלָק ו' מִזֹאת וְעָבִיד הַאי אֹהֶל נוּקְמִין, הַיְינוּ דִכְתִיב (שם) זֹאת חֻקַת הַתּוֹרָה אֲשֶׁר צִוָּה יְיָ. וּבְגִין דְּלָא אִתְחַבָּר ו' בְּה', גָּרְמוּ דְּסָאִיבוּ מַקְדְּשָׁא וְגָּרִימוּ לוֹן מוֹתָא. דְּהָא מַאן דְאַפְרִישׁ לוֹן, גָרִים מוֹתָא לְנַפְשֵׁיהּ,</p>\n<p>עַד דְּאָתַת פָּרָה וְכִפְּרָה עַל בְּנָהּ. וְעַבְדִין מִינָהּ הַזָּאָה עַל טְמֵאֵי מֵתִים. זֹאת הַתּוֹרָה דְלָא אִתְחַבָּר בָּהּ וא\"ו עַד דְּעָבְדוּ הַזָּאַה לְאִינוּן כְּלֵי מִדְיָן. וּלְבָתָר (דברים ד') וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם וְגוֹ' חַיִּים אִתְדַבַּק בָּהּ.</p>\n<p>(דברים ל״ג:א׳) וְזֹאת הַבְּרָכָה, בְּרָכָה אִתְדַבַּק בָּהּ בְּהַאי זֹאת. אֲבָל כָּל אֲתַר דְּתִשְׁכַּח בְּאוֹרַיְיתָא זֹאת הַתּוֹרָה בְלא וא\"ו, בְּגִין חוֹבָה (ויקרא י״ג:נ״ט) זֹאת תּוֹרַת נְגַע צָרַעַת. (ויקרא י״ד:נ״ד) זֹאת הַתּוֹרָה לְכָל נְגַע הַצָרַעַת (במדבר ה׳:כ״ט) זֹאת תּוֹרַת הַקְנָאוֹת. בְּגִין דְּסָאִיבוּ גָּרְמֵיהוֹן וְסָאִיבוּ מַקְדְּשָׁא. (ויקרא ו׳:ב׳) זֹאת תּוֹרַת הָעוֹלָה, לָא כְּתִיב בֵּיהּ וא\"ו עַד דְּיַעֲבְדוּ לָהּ שְׁלִימוּ בְּנֵי אַהֲרֹן לְחַבְּרָא לְזֹאת בְּבַעְלָהּ.</p>\n<p>(ויקרא ו׳:ז׳) וְזֹאת תּוֹרַת הַמִּנְחָה, לא אַתְיָיא עַל חֵטְא, דְּהָא נְדָבָה הִיא. אוֹ דְּאַתְיָיא עִם עוֹלָה וְהָא עַבְדָּא עוֹלָה שְׁלִימוּ. (ויקרא ו׳:ז׳) זֹאת תּוֹרַת הַחַטָּאת אַתְיָיא עַל חֵטְא דְּסָאִיבוּ לְהַאי זֹאת. וְזֹאת תּוֹרַת הַאֲשָׁם בְּגִין דְלָא עָבְדוּ כָּל כָּךְ פְּגִימוּ, וּבְגִין כָּךְ אַתְיָיא דְכוּרָא וְלָא נוּקְבָא (ויקרא ז׳:י״א) וְזֹאת תּוֹרַת זֶבַח הַשְּׁלָמִים בְּגִין דְאַתְיָין לִשְׁלָמָא אִתְחַבָּר בָּהּ וא\"ו. (שם) זֹאת הַתּוֹרָה לְעוֹלָה לַמִנְחָה וְלַחַטָאת, בְּגִין חַטָּאת דְּאִית בִּקְרָא, וְחוֹטֵּא אֶחָד יְאַבֵּד טוֹבָה הַרְבֵּה.</p>\n<p>דָא אוֹקִימְנָא <Nonei></i>בְּכָל אַתְרָא וא\"ו מוֹסִיף עַל עִנְיָּן רִאשׁוֹן. וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם וְגוֹ' מַאי טַעְמָא וא\"ו, הָא לא אָמַר זֹאת בְּקַדְמִיתָא, אַמָּאי כְּתִיב וְזֹאת, בְּגִין סַם חַיִּים דְאִתְדַבָּק בָּהּ.</p>\n<p>(דברים ל״ג:א׳) וְזֹאת הַבְּרָכָה, בְּגִין בְּרָכָה אַף עַל גַּב דְלָא כְּתִיב זֹאת בְּקַדְמִיתָא, אוֹ מִלָּה עַל מָה דְּיֵיתֵי. אֲבָל בְּכוּלְהוּ מַאי טַעְמָא לָא כְּתִיב וְזֹאת. בְּגִין דְלָא אִתְדַבַּק וא\"ו. וְהַאי דִכְתִיב וְזֹאת תּוֹרַת הַאֲשָׁם בְּגִין דִכְתִיב לְעֵיל זֹאת תּוֹרַת הַחַטָּאת, וא\"ו מוֹסִיף עַל עִנְיָן רִאשׁוֹן.</p>\n<p>בְּגִין כָּךְ אִתְיְיהִיבַת אוֹרַיְיתָא בְּהַאי זֹאת. וּבְגִין כָּךְ כְּתִיב (ויקרא כ״ו:ט״ז) אַף אֲנִי אֶעֱשֶׂה זֹאת, אֲסָלֵק מִינָהּ וא\"ו וְתַּעֲבִיד בְּהוּ נוּקְמִין וְכוּלְהוּ קָרְבָּנִין אַתְיָין לְקָרְבָא לְהַאי זֹאת לְעֵילָא בְּהַאי שְׁלִישִׁי. וַאֲנָן מְקָרְבִין בְּהַאי יוֹמָא תְּרֵין פָּרִים בְּמוּסָף, לְאוֹסָפָא לֵיהּ תְּרֵין חוּלָקִין. אַיִל אֶחָד, לְאִתְחַבְּרָא לֵיהּ אֵילָא דִּגְבוּרָ\"ה. שִׁבְעָה אִמְרִין לְקֳבֵל כּוּלְהוּ דַּרְגִּין דְּיֵּחְדוּן בְּהַאי הִלּוּלָא. שֵׂעִיר עִזִים, לְכַפָּרָא עַל דְּסָאִיבוּ מַקְדְּשָׁא חַיָּיבִין דִּלְתַתָּא.</p>\n<p>(במדבר כ״ט:א׳) בַּחֹדֶשׁ הַשְׁבִיעִי, לְקֳבֵל דַּרְגָא דְּיִצְחָק דְּיִתְחַבָּר בֵּיהּ כְּנֶסֶת יִשְׂרָאֵל בִתְּרֵין פָּרִים. הַאי דִכְתִיב (בראשית ח׳:ד׳) וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְׁבִיעִי בְּשִׁבְעָה עֲשָׂר, דְּאִתּוֹסְפָא כְּנֶסֶת יִשְׂרָאֵל דְּאִיהִי שְׁבִיעִית עַל עֶשֶׂר סְמִיכָא לַעֲשָׂרָה. בְּגִין כָּךְ פָּר אֶחָד לְאוֹסָפָא לֵיהּ חֵילָא דְּאִימָא עִלָּאָה לְמֵידָן עַלְמָא. אֲבָל תְּרֵין לָא, בְּגִין דְלָא יָכִיל עַלְמָא לְמִסְבַּל דִּינָא תַּקִּיפָא. אַיִל אֶחָד, גְּבוּרָה דִילֵיהּ לִישָׁנָא דְּתַקִיפוּ, (תהלים כ\"א) אֱיַּלוּתִי לְעֶזְרָתִי חוּשָׁה. וְהַאי אַיִל תַשְׁכַּח בְּכוּלְהוּ מוּסָפִין, דְּמוֹסִיפִין חֵילָא דִּגְבוּרָה עָלַיְיהוּ. בָּר מְשָׁבְּתָא דְּאִית בֵּיהּ נִיחָא, וְלֵית בֵּיהּ דִּינָא כְּלָל. דְאִתְגַלְיָיא עַתִּיקָא קַדִּישָׁא חֵידוּ וְטָבָאן לְכוּלְהוּ עִלָּאִין (ס\"א עלמין).</p>\n<p>(במדבר כ״ח:ג׳) כְּבָשִׂים בְּנֵי שָׁנָה, לְמֵיהַב חֵילָא לְכוּלְהוּ דַּרְגִּין. שֵׂעִיר עִזִים דְלָא יִתְחָזֵי סָאִיבוּ בְּמַקְדְּשָׁא בְּיוֹמָא דְּדִינָא וּבְהָאי יוֹמָא אִתְחַבָּר גְּבוּרָה עִלָּאָה בְּדִינָא תַּתָּאָה דְּרֹאשׁ חוֹדֶשׁ לְמֵידָן עַלְמָא. תָּא חֲזֵי גְּבוּרָה דִּינָא קַשְׁיָא, כְּנֶסֶת יִשְׂרָאֵל דִּינָא רַפְיָא. אַךְ חוֹבַת הַיּוֹם פָּר אֶחָד, בְּגִין דְּיָכִיל עַלְמָא לְמִסְבַּל.</p>\n<p>וּבְגִין כָּךְ בְּרֵישׁ יַרְחָא תְּרֵין פָּרִים דְהִיא כַּפָרָה. בַּעֲשָׂרָה לְיַרְחָא לְקֳבֵל דַּרְגָא דְמֹשֶׁה, בְּמוּסָף דִילֵיהּ פָּר בֶּן בָּקָר אֶחָד, דְלָא אִתּוֹסַף בֵּיהּ דִּינָא כָּל כַּךְ בְּגִין דְהוּא יוֹמָא דְּכַפָּרָה. אַיִל אֶחָד תַקִיף, לְתַבְרָא רְשִׁיעֵי עַלְמָא, וּבַעֵינָן לְמֶעְבָּד נַיְיחַא לְשָׁכְּכָא רָגְזָא.</p>\n<p>כְּבָשִׂים שִׁבְעָה, לְאוֹסָפָא לְכוּלְהוּ דַּרְגִּין. שֵׂעִיר עִזִים אֶחָד, אִתּוֹסַף הַכָא בְּחוֹבָת הַיּוֹם לְכַפָּרָא עַל סוֹאֲבָת מַקְדְּשָׁא, בְּגִין דְקוּדְשָׁא בְּרִיךְ הוּא מִלְּעֵילָא מְכַפֵּר כֹּלָּא. וְלָא יִשְׁתָּאַר סָאִיבוּ בְּעָלְמָא. בְּגִין כָּךְ, חַד בְּיוֹמָא, לְכַפָּרָא קֹדֶשׁ הַקֳּדָשִׁים חַד זִמְנָא בְּשַׁתָּא, בְּגִין דְלָא אִשְׁתְּכַח כָּל כַּךְ סָאִיבוּ תַמָּן. וְחַד לְבָרָא, לַמִּזְבֵּחַ הַחִיצוֹן, דְלָא יִשְׁתַּכַּח סָאִיבוּ בְּעָלְמָא.</p>\n<p>בַּחֲמִשָׁה עֲשָׂר לְיַרְחָא לְקֳבֵל דַּרְגָא דְאֲהַרֹן דְאֲחִיד בְּהוֹ\"ד וְאִסְתַּלַק נָמֵי בְּחֶסֶ\"ד. וּבְגִין כָּךְ בְּהַאי זִמְנָא אֲפִילוּ עִם כָּל אוּמִין דְּעָלְמָא עֲבִיד קוּדְשָׁא בְּרִיךְ הוּא טִיבוּ. בְּגִין דְּאִתּוֹסַף חֶסֶ\"ד דְאֲהַרֹן עִם חֶסֶ\"ד דְּאַבְרָהָם וְאִינוּן מְקָרְבִין בֵּיהּ בְּשִׁבְעָה יוֹמִין קָרְבָּנִין עֲלָוָון, בְּגִין דְּיְחְדוּ כּוּלֵיהּ עַלְמָא בְּחֶדְוָותָא דְּיִשְׂרָאֵל.</p>\n<p>ע' פָּרִים לְקֳבֵל ע' אוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת דְּעָלְמָא, וּבְיוֹמָא קַדְמָאָה פָּרִים שְׁלשָׁה עֲשָׂר. לְאַחְזָאָה דְלָאו אִינוּן כְּדָאי לְאִתְקַיְימָא בְּעָלְמָא, אֶלָּא בְּטִיבוּ דְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִית בֵּיהּ תְּלֵיסַר מְכִילָן דְּרַחֲמֵי.</p>\n<p>אֵלִים שְׁנַיִם לְמֶהֱוֵי תַּקִּיפוּ לְהַהוּא דַּרְגָא דְחֶסֶ\"ד עִלָּאָה עַל חַד תְּרֵין מִמַּה דִּמְקָרְבִין בְּכוּלְהוּ מוּסָפִין בְּגִין דְּהַאי חַגָא אִיהוּ לְקֳבֵל דַּרְגָא דְאֲהַרֹן דְאֲחִיד בְּדַרְגָּא שְׁתִיתָאִי. וְאִקְרֵי יוֹם שְׁתִיתָאִי. יוֹמָא דְקוּדְשָׁא בְּרִיךְ הוּא אֶלֶף שְׁנִין.</p>\n<p>וּבְהַהוּא יוֹמָא זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאוֹסָפָא עַל חַד תְּרֵין טִיבוּ לְעַמֵּיהּ. הֲדָא הוּא דִכְתִיב (שמות ט״ז:ה׳) וְהָיָה בְּיוֹם הַשִׁשִׁי וְהֵכִינוּ אֶת אֲשֶׁר יָבִיאוּ, אָז וְהָיָה מִשְׁנֶה עַל אֲשֶׁר יִלְקְטוּ יוֹם יוֹם, וּבְכֻלְּהוּ דַּרְגִּין דִּלְעֵילָא אִתּוֹסַף בִּרְכָאָן.</p>\n<p>וּבְהַהוּא יוֹמָא יֵיתֵי מַלְכָּא מְשִׁיחָא וְיִתְקְרֵי חַג הַאָסִיף דְּיַכְנִישׁ קוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ גָּלוּתָא דְּעַמֵּיהּ, הֲדָא הוּא דִכְתִיב (ישעיהו י״א:י״א) וְהָיָה בְּיוֹם הַהוּא יוֹסִיף יְיָ שֵׁנִית יָדוֹ לִקְנוֹת אֶת שְׁאָר עַמּוֹ. וְיִתְקְרֵי חַג הַסֻּכּוֹת, דְּכֻלְּהוּ שִׁבְעָה דַּרְגִּין חַפְיָין עַל יִשְׂרָאֵל כְּסוּכָּה וּבְגִין כָּךְ כּוּלְהוּ עֲנָנֵי כָּבוֹד אַזְלִין עִם יִשְׂרָאֵל בְּמַדְבְּרָא בִּזְכוּתָא דְאֲהַרֹן</p>\n<p>בְּגִין כָּךְ י\"ד אִמְרִין בְּכָל יוֹמָא. וּבְשִׁבְעָה יוֹמִין הָא שִׁבְעָתַיִם וְיַנְהִיר שִׁבְעָתַיִם נְהִירוּ דְשִׁמְשָׁא. וְקוּדְשָׁא בְּרִיךְ הוּא יְרָחֶם עַל עַלְמָא וְשָׂעִיר עִזִים אֶחָד חַטָּאת לְכַפָּרָא עַל סָאִיבוּ מַקְדְּשָׁא דְּסָאִיבוּ אוֹמֵי עַלְמָא עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת בְּיוֹמָא תִּנְיַנָא לְקֳבֵל דַּרְגָא דְּיִצְחָק. בְּיוֹמָא תְּלִיתָאָה לְקֳבֵל דַּרְגָא דְיַעֲקֹב. בְּיוֹמָא רְבִיעָאָה לְקֳבֵל דַּרְגָא דְּיוֹסֵף. בְּיוֹמָא חֲמִישָׁאָה לְקֳבֵל דַּרְגָא דְמֹשֶׁה. בְּיוֹמָא שְׁתִיתָאָה לְקֳבֵל דַּרְגָא דְאֲהַרֹן:</p>\n<p>וְתָא חֲזֵי בְּהַאי חַגָא וּבְחַגָא דִּפְּטִירוּ, שִׁבְעָה יוֹמֵי דִכְלִילָן כּוּלְהוּ יוֹמִין דִּלְעֵילָא בְּהוּ. מָה דְּלֵית כֵּן בִּשְׁאָר חַגִּין דִּמְקָרְבִין בְּהוּ מוּסָף, אֶלָּא הַיְינוּ דְּאוֹקִימְנָא בְּרָזָא דִמְהֵימְנוּתָא (בראשית ל׳:ל״ז) מָחְשׂוֹף הַלָּבָן אֲשֶׁר עַל הַמַּקְלוֹת, דִּי לְכָל אִינוּן שִׁבְעָה שִׁבְעָה דַּרְגִּין אַסְחַר לוֹן <Nonei></i>בִּסְטָר דְחֶסֶ\"ד חַגָא דִּפְּטִירָא, לְקֳבֵל אַבְרָהָם דְאָתֵי מִחֶסֶ\"ד בְּגִין כָּךְ כּוּלְהוּ דַּרְגִּין תַמָּן. דְּהָא לְכוּלְהוּ דַּרְגִּין אֶסְחַר יַעֲקֹב שְׁלֵימָא לְסִטְרָא דְחֶסֶ\"ד. הַאי חַגָא לְקֳבֵל דַּרְגָא דְאֲהַרֹן דְאֲחִיד בְּחֶסֶד, כּוּלְהוּ עִמֵּיהּ.</p>\n<p>דָבָר אֲחֵר, בְּגִין דְּכוּלְהוּ דַּרְגִּין וְכוּלְהוּ זַכָּאִין, כַּד נַפְקוּ יִשְׂרָאֵל מִמִּצְרָיִם קוּדְשָׁא בְּרִיךְ הוּא אִתְגְּלֵי תַמָּן בְּכִתְרוֹי וְזַמִּין לְמֶעְבַּד כֵּן בְּיוֹמֵי דְּיֵיתֵי מְשִׁיחָא. בְּגִין כָּךְ כּוּלְהוּ כִּתְרִין רְמִיזִין הַכָא וְהָכָא וְנַטְלִין עַל חַד תְּרֵין שֶׁבַע בִּרְכָאָן הַכָא מֵהַתָּם.</p>\n<p>וְהָתָם עַל חַד שִׁבְעָה מִשְׁאָר מוּסָפִין, הֲדָא הוּא דִכְתִיב (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. כְּיוֹם צֵאתְךָ הֲוָה לֵיהּ לְמֵימָר. מַאי כִּימֵי. דְּכוּלְהוּ יוֹמִין עִלָּאִין אִזְדְּמָנוּ הֲתָם וְאִזְדָּמְנוּ הַכָא. בְּגִין כָּךְ נִפְלָאוֹת נ' פְּלָאוֹת, חַמְשִׁין פְּלָאוֹת. דְּהָא נ' תַרְעִין דְבִּינָ\"ה פָּתַח קוּדְשָׁא בְּרִיךְ הוּא לְאַפָּקָא לוֹן מִתַּמָּן. וּבְּגִינֵי כַּךְ בְּאוֹרַיְיתָא אִדְכַּר יְצִיאַת מִצְרָיִם נ' זִמְנִין לְקֳבֵל נ' תַרְעִין כְּדֵין יַעֲבִיד לְיוֹמֵי מְשִׁיחָא.</p>\n<p>וּמַאי אַרְאֶנּוּ. אֶלָּא אַרְאֶנּוּ לְהַהוּא סָבָא דְחָזָא בְּקַדְמִיתָא דִכְתִיב (שמות י״ד:ל״א) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה. כְּדֵין זַמִּין לְמֶחְזֵי פּוּרְעַנוּתָא דֶאֱדוֹם.</p>\n<p>דָבָר אַחֵר, דִּבְּגִינְהוֹן דְּשִׁבְעָה צַדִּיקַיָּיא, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא לְכָל אוּמִין דְּעָלְמָא וְלָא יִשְׁתָּאַר בְּעָלְמָא אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי וְיִשְׂרָאֵל גּוֹי אֶחָד בְּגִין כָּךְ הַכָא שִׁבְעָה יוֹמִין. תָּא חֲזֵי, דִּבְגִין כַּךְ מִתְמָעֲטִין וְהוֹלְכִין. וּבְיוֹמָא תְמִינָאָה שַׁלְטִין יִשְׂרָאֵל לְחוֹדָּיְיהוּ בְּעָלְמָא וּמָקְרִיבִין פָּר אֶחָד אַיִל אֶחָד, רָזָא דְּיִחוּדָא.</p>\n<p>שִׁבְעָה כְּבָשִׂים לְקֳבֵל שִׁבְעָה דַּרְגִּין. שְׂעִיר עִזִים, אַף עַל גַּב דְּבְהַהוּא זִמְנָא יַעֲבְרִינֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מֵעָלְמָא, עִם כָּל דָּא יִשְׁתָּאַר מִנֵּיהּ דְלָא יִתְבָּטְלוּן מִפִּרְיָה וְרִבְיָה. וּבְהַהוּא זִמְנָא יִפְקוּן מַיִם חַיִּים מֵחָכְמָה עִלָּאָה (זכריה י״ד:ח׳) חֶצְיָם אֶל הַיָּם הַקַּדְמוֹנִי דָא חֶסֶד עִלָּאָה וְחֶצְיָּם אֶל הַיָּם הָאַחֲרוֹן דָא גְּבוּרָ\"ה תַּתָּאָה וּגְבוּרָ\"ה עִלָּאָה. בַּקַיִץ וּבַחוֹרֵף בְּסִטְרָא דְאֶשָא וּבְּסִטְרָא דְמַיָּא. דְלָא יִשְׁתָּאַר דִינָא בְּעַלְמָא אֶלָּא כֹּלָּא רַחֲמֵי וְחַיִּים וְחֵירוּ בְּעַלְמָא:</p>\n<p>וְתָא חֲזֵי בְּהַאי חַגָא עַבְדִין נִסוּךְ הַמָּיִם. נְבִיעַ דְּחֶסֶד בְּאִינוּן שִׁתִּין מִשֵׁשֶׁת יְמֵי בְּרֵאשִׁית, וְכוּלְהוּ שִׁבְעָה יוֹמִין עִלָּאִין מְקַבְּלִין מֵאִינוּן מָיִם חַיִּים דְּנָפְקִין מִיְרוּשָׁלַיִם עִלָּאָה טְמִירָא. וּבֵאַן אֲתַר רָמִיז לְאִינוּן מָיִם חַיִּים, בְּאִינוּן שִׁיתִּין.</p>\n<p>וְחֲסִידֵי וְצַדִּיקֵי חַדָּאן בְּהַאי הִלּוּלָא, בְּגִין דִּרְמִיזָא לְהַהוּא טִיבוּ דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד כַּד יַעְבֵּר קוּדְשָׁא בְּרִיךְ הוּא סָאִיבוּ מֵאַרְעָא דְּיֶחְתוּן אִינוּן מָיִם חַיִּים טְהוֹרִים בְּאִינוּן שִׁיתִּין, בְּהַהוּא מִזְבֵּחַ עִלָּאָה הַהוּא יָם הָאַחֲרוֹן. וְאִינוּן תְלָתָא לוֹגִין מָיִם י\"ח בֵּצִים לְקֳבֵל צַדִּיק דְּאִקְרֵי ח\"י הָעוֹלָמִים, וְעַל יְדֵיהּ מָיִם נַחְתִּין בְּאִינוּן שִׁיתִּין.</p>\n<p>וְתָּא חֲזֵי הִלֵּל הַזָּקָן כַּד הֲוָה חַדֵּי בְּהַאי הִלּוּלָא אָמַר אִם אֲנִי כָּאן הַכֹּל כָּאן. וְאִם אֵין אֲנִי כָּאן מִי כָּאן. הוּא רָמִיז וְאָמַר אִי שְׁכִינְתָּא דְּאִקְרֵי אֲנִי שַׁרְיָיא כַּאן. הַכֹּל כָּאן הַהוּא אַתְרָא דְּאִקְרֵי כָּל דְאָתֵי לְאִזְדַּוְּוגָא בָּהּ. וְאִם אֵין אֲנִי כָּאן מִי כָּאן. דְּהָא לָא חַשִׁיבָא טִיבוּ שְׁלֵימָא בְּגִין דִשְׁכִינְתָּא לָא שַׁרְיָיא בְּאַרְעָא קַדִּישָׁא.</p>\n<p>אֲבָל כַּד יִשְׁתְּלָמוּ אִינוּן פָּרִים כְּדֵין כְּתִיב (ישעיהו י״ב:ג׳) וּשְׁאַבְתֶּם מָיִם בְּשָׂשׂוֹן מִמָעֲיְינֵי הַיְשׁוּעָה. מַאן אִינוּן. שִׁית מָעֲיַינֵי דְּאִינוּן מְרִיקִין בְּהַאי יְשׁוּעָה וּכְדֵין עַלְמָא כּוּלֵיהּ בְּחֶדְוָה בְּגִין דְּנָפְקַא שְׁכִינְתָּא מִבֵּין הַהוּא סָאִיבוּ דִּשְׁאָר עַמִּין, בְּגִין כָּךְ (במדבר כ״ט:ל״ה) בְּיוֹם הַשְׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם.</p>\n<p>תָּא חֲזֵי עֶשֶׂר נְטִיעוֹת עֲרָבָה וְנִסוּךְ הַמָּיִם הֲלָכָה לְמֹשֶׁה מִסִּינַי. שְׁאָר מִלֵּי דְּאוֹרַיְיתָא תּוֹרָה. וְהָכָא הֲלָכָה. מַאי טַעְמָא, אֶלָּא בְּגִין דְּהַאי אַתְרָא דְּאִקְרֵי הַר סִינַי, תּוֹרָה שֶׁבְּעַל פֶּה אוֹלִיפַת לֵיהּ לְמֹשֶׁה לְקַשְׁרָא קִשְׁרִין דִמְהֵימְנוּתָא.</p>\n<p>אִינוּן עֶשֶׂר נְטִיעִין דְּנָצָב קוּדְשָׁא בְּרִיךְ הוּא, דְּהָא אֲחִיד לוֹן בְּהַהוּא אַתְרָא דְּאִקְרֵי עֶרֶב שְׁבִיעִית וְיַעְבְּדוּן פְּרִי בְּהַהוּא בֵּית סְאָה, בְּגִין דְאַיְיתֵי מְזוֹנָא לְעָלְמָא בְּהַאי שְׁבִיעִית. דְּלֵית לוֹן מְזוֹנָא אֶלָּא מֵהַהוּא שַׁתָּא שְׁתִיתָאָה דְּזַרְעִין בָּהּ זַרְעִין, הֲדָא הוּא דִכְתִיב (הושע י׳:י״ב) זִרְעוּ לָכֶם לִצְדָקָה קִצְרוּ לְפִי חֶסֶד, מָה דְּזַרְעִין יְהֵא לְהַהוּא אַחֲרָא דְּאִקְרֵי צְדָקָה שְׁלֵימָה, וּכְדֵין וְקִצְרוּ לְפִי חֶסֶד כְּדֵין יְהֵא טִיבוּ עִלָּאָה. וּמַאן אִיהוּ לְפִי (פי) חֶסֶד דָא אַבְרָהָם.</p>\n<p>וְתָא חֲזֵי לְתַתָּא שִׁבְעָה עֲבִידָן אִית בֵּינֵיהוֹן. זְרִיעָ\"ה לְקֳבֵל אִימָא עִלָּאָה, הֲדָא הוּא דִכְתִיב (בראשיתמ\"ז) הֵא לָכֶם זֶרַע. קְצִירָ\"ה לְקֳבֵל דַּרְגָא דְאַבְרָהָם הֲדָא הוּא דִכְתִיב וְקִצְרוּ לְפִי חֶסֶד. דִישָׁ\"ה בַּחָרוּץ לְקֳבֵל דַּרְגֵּיהּ דְיִצְחָק דְּעָבִיד דִּינָא וְאַפְרִישׁ תֹּכֵן מֵהַהוּא בָּר. דִּינָא אַפְרִישׁ מִנֵּיהּ וְעֲבַד דִּינָא בִּרְשִׁיעֵי עַלְמָא וּכְדֵין אִינְהוּ כְּמוֹץ לִפְנִי רוּחַ.</p>\n<p>וְהַאי רוּחַ דָא דַּרְגָא דְיַעֲקֹב דִכְתִיב (בראשית מ״ה:כ״ז) וַתְּחִי רוּחַ יַעֲקֹב, וּלְקִבְלֵיהּ זוֹרֶ\"ה וְהוּא מוֹץ לְאֶשָּׁא אִתְיְיהִיב לְמֵיכָל. טוֹחֵ\"ן לְקֳבֵל דַּרְגָא דְמֹשֶׁה. לָּ\"שׁ לְקֳבֵל דַּרְגָא דְאֲהַרֹן. אוֹפֵ\"ה לְקֳבֵל דַּרְגָא דְצָדִי\"ק וְאִתְעֲבִיד לֶחֶ\"ם בְּיָדוֹ דְצָדִי\"ק בְּהַהוּא אוֹר דְּאִית בְּצִיּוֹן, הֲדָא הוּא דִכְתִיב (תהילים קל״ו:כ״ה) נוֹתֵן לֶחֶם לְכָל בָּשָׂר. בְּקַדְמִיתָא לְכָ\"ל וּלְבָתָר לְהַהוּא אֲתַר דְּאִקְרֵי <Nonei></i>בָּשָׂר וּמָאי לֶחֶם דָא קִיוּמָא.</p>\n<p>וּבְהַאי שַׁתָּא שְׁבִיעַתָּא לָא עָבְדִין עֲבִידְתָּא, אֶלָּא אַכְלִין הַהוּא לֶחֶם דְאִתְיְיהִיב לְהוּ מִשָׁתָּא שְׁתִיתָאָה. וְכוּלְהוּ עָלְמִין בְּחֶדְוָה נָיְיחִין וְכוּלְהוּ מִסְכְּנִי וְעֲתִּירֵי כּוּלְהוּ שָׁוִין בְּהַאי אֲתַר, דְּהָא כּוּלְהוּ תַתָּאֵי מֵהָאי שַׁתָּא שְׁבִיעַתָּא מִתְזָּנִין.</p>\n<p>וְאִי בַּר נָשׁ עֲבִיד בְּאִינוּן פֵּירִין סְחוֹרָתָא. הַאי דְאַתְרָא דְעַנִּיּוּתָא מָנַע מִנֵּיהּ בִּרְכָאָן, בְּגִין כָּךְ מָנַע מִנֵּיהּ בִּרְכָאָן. וּבָעֵי בַּר נָשׁ לְאַחֲזָאָה דְּהַאי אַרְעָא קַדִּישָׁא דְקוּדְשָׁא בְּרִיךְ הוּא אִית לָה נַיְיחָא בְּבַעְלָהּ וְקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לֶחֶם לְהַאי כָּ\"ל. וְכָ\"ל לְהַהוּא אַתְרָא דְּאִקְרֵי בָּשָׂ\"ר מִבְּשָׂרִי, וְלֵית לָהּ נְהוֹרָא מִדִילָה אֶלָּא הַנְהוּ סְפִיחֵי דִּשְׁתִּיתַאָה דְּאִזְדְּרָעוּ בָּהּ מִמֵילָא.</p>\n<p>וּבָעֵי בַּר נָשׁ בְּהַהוּא עֶרֶב שְׁבִיעִית לְמֶעְבָּד עֲבִידְתָּא דְּאַרְעָא בְּאִינוּן עֶשֶׂר נְטִיעָן אִשְׁתְּלִימוּ בָּהּ דְּתִתְיַחֵד הַאי אַרְעָא בְּהוּ, וְלָא תִתְפָּרָשׁ מִנַּיְיהוּ וְתִתִקְרֵי אַף הִיא נְטִיעָה, נְצִיבוּ דְּנָצָב קוּדְשָׁא בְּרִיךְ הוּא. בְּגִין דְלָא יִתִּמְנַע מִינָהּ הַהוּא טִיבוּ דְּאִית לָהּ עִם בַּעְלָהּ, נַיְיחָא בַּשְׁבִיעִית.</p>\n<p>בְּגִין כָּךְ אָדָם בְּיוֹמָא שְׁתִיתָאָה אִתְבְּרֵי וְאִזְדַּוְּוגַת עִמֵּיהּ בַּת זוּגֵיהּ לְאִתְעֲנְגָא בְּשַׁבְּתָא, וְהַשְׁתָּא אִזְדַּוְּוגַת צֶדֶ\"ק בִּשְׁתִיתָאָה לְמֵיהַב נְהִירוּ לְהַאי הַר סִינַי.</p>\n<p>וְתָּא חֲזֵי, הַר חוֹרֵב אִתְקְרֵי כַּד אִזְדְּוַוג עִמֵּיהּ וא\"ו. וְאִי בְּנִי נָשָׁא מַפְרִישִׁין וא\"ו מִינָהּ, אִקְרֵי חֶרֶב לַיְיָ, דְּהָא חֶרֶב כְּתִיב, וְעַבְדָּא נוּקְמִין. בְּגִין כָּךְ הֲלָכָה לְמֹשֶׁה מִסִּינַי תּוֹרָה שֶׁבְּעַל פֶּה דְּיִכְלְלוּן יָתָהּ בְּאִינוּן עֶשֶׂר נְטִיעָן עֶרֶב שְׁבִיעִית, וְיֵיתֵי מְזוֹנָא לְעָלְמָא בַּשְׁבִיעִית. דְהוּא אַתְרָא דְּלֵית לָהּ נְהוֹרָא אֶלָּא מָה דְאִתְיְיהִיב לָהּ מֵהַהוּא וא\"ו.</p>\n<p>וְתָּא חֲזֵי יִשְׂרָאֵל כַּד עֲבַדוּ עֶגְלָא וְאַפְרִישׁוּ בִּרְכָאָן מֵהַאי הַר חוֹרֵב דְּאַפְרִישׁוּ מִנֵּיהּ וא\"ו וְקַצִּיצוּ בִּנְטִיעוֹת בְּאִינוּן נְטִיעָן, מָה כְּתִיב (שמותל\"ג) וַיִתְנַצְּלוּ בְּנִי יִשְׂרָאֵל אֶת עֵדְיָם מֵהַר חוֹרֵב. הַהוּא עֲדִי עִלָּאָה, תְפִלִּין דְּרֵישָׁא וּדְרוֹעָא דְּשָׁוְויָין בְּיָד כֵּהָה אַעְדִּיאוּ מִנְּהוֹן. וּמֵאַן אֲתַר אִתְיְיהִיב לוֹן, מֵהַר חוֹרֵב כַּד אִזְדְּוַוג בָּהּ וא\"ו. וְהַשְׁתָּא (משלי ט״ז:כ״ח) וְנִרְגָּן מַפְרִיד אַלּוּף וְאִתְעָרוּ עֲלֵיהוֹן חֶרֶב.</p>\n<p>בְּגִין כָּךְ בְּנֵי לֵוִי דְּעָבְדוּ לְוָיָה לְהַאי אַתְרָא, אִתְפְּרָעוּ מִנְּהוֹן. הֲדָא הוּא דִכְתִיב (שמות ל״ב:כ״ו) וַיַעֲמֹד מֹשֶׁה בְּשַׁעַר הַמַּחֲנְה וַיֹּאמֶר מִי לַיְיָ אֵלָי וַיֵאָסְפוּ אֵלָיו כָּל בְּנִי לֵוִי, דְּהָא לָא עֲבָדוּ פִּרוּדָא אֶלָּא לְוָיָה.</p>\n<p>וְאָמַר לוֹן מֹשֶׁה (שמות ל״ב:כ״ז) כֹּה אָמַר יְיָ עִבְרוּ וָשׁוּבוּ מִשַׁעַר לְשַׁעַר בַּמַּחֲנֶה, בְּגִין דְּהַאי כֹּ\"ה יָהֲבַת לוֹן רְשׁוּתָא לְמֶעְבָּד דִּינִין וּמַאן אִיהוּ כֹּ\"ה, דָא הַר חוֹרֵב וּבְגִין כָּךְ קַטְלוּ מִנְּהוֹן כִּשְׁלֹשֶׁת אַלְפֵי אִישׁ, שְׁלֹשֶׁת לָא אִתְּמָר, אֶלָּא כִּשְׁלֹשֶׁת לְקֳבֵל הַנְהוּ תְלָתָא דַּרְגִּין דְהֲווּ מַלְיָין לְהַאי בְּאֵר. הֲדָא הוּא דִכְתִיב (בראשית כ״ט:ב׳) וְהִנֵּה שָׁם שְׁלֹשָׁה עֶדְרֵי צֹאן רוֹבְצִים עָלֵיהּ. בְּגִין דְּאִינוּן גָּרְמוּ דְּיִסְתַּלְקוּן מִינָהּ וְהָא אוּקְמוּהָ.</p>\n<p>בְּגִין כָּךְ פְּקִידָּת לֵיהּ הַאי תּוֹרָה שֶׁבְּעַל פֶּה לְמֹשֶׁה עַל אִינוּן עֶשֶׂר נְטִיעָן וַעֲרָבָה דְּיָקִיפוּן לְהַאי מִזְבֵּחַ בְּאִינוּן עַרְבֵי נַחַל לְקֳבֵל תְּרֵין דַּרְגִּין דְּמָקִיפִין לְעֵילָא דְּאִינוּן נְצַ\"ח הוֹ\"ד. וּכְדֵין יַעַבְדוּן נִסוּךְ הַמָּיִם מֵאִינוּן מָיִם חַיִּים דְאַתְיָין עַל יְדֵי דְּצַדִּיק וְלָא יִמְנֵעוּן מֵהָאי מִזְבֵּחַ טִיבוּ עִלָּאָה.</p>\n<p>וְתָא חֲזֵי כָּל שְׁאָר יוֹמֵי דְּשָׁתָא בְּהַאי מִזְבֵּחַ עַבְדִין נִסוּךְ הַיָּיִן, רָמִיז לְדִינָא דְעָיִיל בָּהּ לְמֵידָן עַלְמָא. אֲבָל בְּחָג עַבְדִין אוּף בְּמַיִם חַיִּים. דְּהָא חַיִּים וּנְהִירוּ אִתּוֹסַף בְּהַהוּא זִמְנָא (ישעיהו י״א:ט׳) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת יְיָ כַּמַּיִם לַיָּם מְכַסִּים.</p>\n<p>עֲשָׂרָה פַּעֲמָיִם נִמְנוּ יִשְׂרָאֵל, אַחַת בִּיְרִידַתָן לְמִצְרָיִם דִכְתִיב (בראשית מ״ו:כ״ז) כָּל הַנֶּפֶשׁ לְבֵית יַעֲקֹב הַבָּאָה מִצְרַיְמָה וכו' (וגו'). וְאַחַת בַּעֲלִיָיתָן דִכְתִיב (שמות י״ב:ל״ז) כְּשֵׁשׁ מֵאוֹת אֶלֶף. וּשְׁנַיִם בְּחוּמָשׁ הַפְּקוּדִים וּשְׁנַיִם בִּימֵי שָׁאוּל, א' בְּבֶּזֶק וְא' בַּטְלָאִים, וְא' בִּימֵי דָוִד (שמואל ב' כ\"ג) וַיִּתֵּן יוֹאָב אֶת מִסְפָּר הֲעָם אֶל הַמֶּלֶךְ. וְא' בִּימֵי עֶזְרָא (עזרא ב׳:ס״ד) כָּל הַקָּהָל כְּאֶחָד. וְא' לְעָתִיד לָבֹא (ירמיהו ל״ג:י״ג) עוֹד תַּעֲבוֹרְנָה הַצֹּאן עַל יְדֵי מוֹנֵה.</p>\n<p>אַשְׁרֵי אָדָם מָצָא חָכְמָה, דָא אָדָם עִלָּאָה דְּאַשְׁרֵי עֲלוֹי טִיבוּ דְּעַתִּיקָא. אֵימָתַי, כַּד מָטָא חָכְמָה כְּמָה דְאַתְּ אָמֵר (משלי י״ח:כ״ב) מָצָא אִשָּׁה מָצָא טוֹב וַיָּפֵק רָצוֹן מֵיְיָ. דָא רַעֲוָא דְּעַתִּיקָא וּמָאי אִיהוּ הַאי חָכְמָה, דָא חָכְמָה זְעִירָא דְהִיא רַבְרְבָא בְּאִתְחַבְּרוּתָא לְעֵילָא.</p>\n<p>מָצָא, מַאי מָצָא כְּגוֹן דְאִשְׁתַּכְּחַת בְּכֹלָּא. וְאָדָם יָפִיק תְבוּנָה דְּבָעֵי לְעַיְינָא וּלְאִסְתַּכְּלָא וּלְאַפָּקָא מֵעוֹמָקַא עִלָּאָה תְבוּנָה, לְאַנְהֲרָא לְהַאי חָכְמָה. וְעַל יְדֵי דְּמַאן אִתְנָהִירָת עַל יְדֵי עִלָּאָה דְּמָפִּיק רָצוֹן מִלְּעֵילָא לְאַנְהֲרָא לָהּ: רִבִּי בִנְיָמִן לֵוִי, מַצָאתִי כָּתוּב שֵׁם בֵּן י\"ב אוֹתִיּוֹת יְהַ יְהַ וְהַ וְהַ וָה יִה: תֹּה\"וּ בְּמִסְפָּר קָטָן עִם ג' אוֹתִיּוֹת גִימַטְרִיָּא ש' ש\"ד שד\"י. בֹּהוּ בְּמִסְפָּר קָטָן גִימַטְרִיָּא צְבָאוֹת כָּזֶה ב' ב\"ה בֹּהוּ. חֹשֶׁךְ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל גִימַטְרִיָּא אֱלֹהִים. רוּחַ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל בְּגִימַטְרִיָּא יהו\"ה בְּמִסְפָּר קָטָן. רַעַשׁ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל גִימַטְרִיָּא בֹּהוּ. קוֹל דְּמָמָה דַקָּה בְּמִסְפָּר קַטָן עִם הַכּוֹלֵל יהו\"ה וְי\"ב יוֹתֵר כְּנֶגֶד שֵׁם י\"ב הַנִמְסָר לְאֵלִיָּהוּ בַּמֵעַרָה. וְכֵן דַקָּה בְּמִסְפָּר קָטָן עִם הַשְׁלֹשָׁה אוֹתִיּוֹת גִימַטְרִיָּא יב\"ק נלעד\"ן:</p>"],[9520012806,"<p><Nonei></i>לָּמָה בֵּי\"ת דּוֹמֶה לְאָדָם שֶׁנוֹצָר בְּחָכְמָה שֶׁסָתוּם מִכָּל צָד וּפַּתוּחַ מִלְפָנָיו וְהָאָלֶף פְתוּחָה מֵאַחֲרָיו רוֹצֶה לוֹמַר כִּי הִיא פְתוּחָה לְקַבֵּל מִן הַכֶּתֶר וְיֵשׁ לָהּ פְּתַח לְהַשְׁפִּיעַ לְאֲחֵרִים.</p>"],[9520012807,"<p>וּמְנָא לָן דְּשָׁמַיִם הֲוֵי קוּדְשָׁא בְּרִיךְ הוּא, דִכְתִיב (מלכים א ח׳:ל״ב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. אֲטוּ שְׁלמֹה מִתְפָּלֵל אֶל הַשָּׁמַיִם שְׁיִשְׁמְעוּ תְּפִלָּתוֹ, אֶלָּא שְׁנִקְרָא שְׁמָן עַל שְׁמוֹ. וְלָמָּה נִקְרָא שָׁמַיִם אֶלָּא שֶׁהוּא עֲגוֹל כְּמוֹ רֹאשׁ וּמְלַמֵּד שֶׁמָּיִם מִימִינוֹ וְאֵשׁ מִשְׂמֹאלוֹ וְהוּא בְּאֶמְצַע שָׂא מָיִם, מֵאֶשׁ וּמִמָיִם וּמָכְנִיס בֵּינֵיהֶם שָׁלוֹם, בָּא הָאֵשׁ וּמָצָא מִצִדוֹ מִדַּת הָאֵשׁ. בָּא מָיִם וּמָצָא מִצִדוֹ מִדַּת הַמָּיִם וְהַיְינוּ (איוב כ״ה:ב׳) עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו, מַאי שָׁמַיִם מְלַמֵּד שֶׁגָבַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵשׁ וּמַיִם וּטְפָחַן זֶה בָּזֶה וְעָשָׂה מֶהֵן רֹאשׁ לִדְבַרָיו שֶׁנֶּאֱמַר (תהילים קי״ט:ק״ס) רֹאשׁ דְּבָרְךָ אֱמֶת. ע\"כ.</p>"],[9520012808,"<p>וְהָאָרֶץ הָיְתָה תֹהוּ. בְּזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה בְּאִלֵּין קְלִיפִּין הֲוָה בּוֹנֶה עָלְמִין וּמַחֲרִיבָן וְהָא אוּקְמוּהָ דְּלֵית הַשְפָּעַה בְּכָל עָלְמִין, וְנָהָר דְּאִיהוּ צַדִּיק יֶחרַב וְיָבֵשׁ בִּתְרֵין עָלְמִין, בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי.</p>\n<p>וְאִית מָאן דְּאָמַר דְסָלִיק בְּמַחְשַׁבְתֵּיהּ לְמִבְנִי עָלְמִין וּלְהַחָרִיבָן. וְאָמַר דֵין מְהַנְיָין לִי וְדֵין לָא מְהַנְיָין לִי. אִלֵּין דְּאִתְּמָר בְּהוֹן אֶת הַשָׁמַיִם וְאֶת הָאָרֶץ מְהַנְיָין לִי. וְאַחֲרָנִין דְּאִתְּמָר בְּהוֹן וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ דְּאַחְזֵי עַל עָלְמִין דְסָלִיק בִּרְעוּתֵיהּ לְמִבְנִי לוֹן וְלָא עֲבִיד לוֹן עֲלַיְהוּ אִתְּמָר תֹהוּ וָבֹהוּ.</p>\n<p>וּבְזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא בְּאִלֵּין קְלִיפִּין אִתְּמָר בֵּיהּ (איכה ג׳:מ״ד) סַכּוֹתָה בֶּעָנָן לָךְ מֵעֲבוֹר תְפִלָּה. תֹהוּ וְחֹשֶׁךְ עֲלַיְהוּ אִתְּמָר (שמות י״ד:כ׳) וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ וְאִלֵּין קְלִיפִּין דֶּאֱגוֹזָא, מוֹחָא מִלְגַאו דְּתַלְיָא (דתלת) לד' סִטְרִין דָא יהו\"ה דְּאִיהוּ לָא קַבִּיל מֵסָאֲבוּ, כְּמָה דְאַתְּ אָמֵר (ירמיהו כ״ג:כ״ט) הֲלֹא כֹּה דְּבָרַי כָּאֵשׁ נְאֻם יְיָ. מָה אֶשָׁא לָא מְקַבֵּל טוּמְאָה הֲכִי שְׁמֵיהּ לָא מְקַבֵּל טוּמְאָה.</p>\n<p>וּבִזְמְנָא דְּמִתְגַּבְּרִין אִלֵּין קְלִיפִּין וְאִתְבָּרוּן מֵאֱגוֹזָא, צְלוֹתָא דְּאִיהִי שְׁכִינְתָּא אדנ\"י, סַלְקָא לְגַבֵּי בַּעְלָהּ דְּאִיהוּ יהו\"ה וּסְלִיקַת כוּלַּהּ, דִּבְּזִמְנָא דְּאִיהוּ מִתְכָּסֵי מִינָהּ בְּאִלֵּין קְלִיפִּין, אִיהִי אִתְקְרִיאַת עֲנִיָּה יְבֵשָׁה וְלֵית לָהּ אֶלָּא מָה דְיַהֲבִין עֲבָדִין בַּחֲשָׁאי.</p>\n<p>וּבְהַהוּא זִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא אִתְפְּשָׁט מֵאִלֵּין קְלִיפִּין אִתְּמָר (ישעיהו ל׳:כ׳) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךָ וְהָיוּ עֵינְיךָ רוֹאוֹת אֶת מוֹרֶיךָ. וּמָה דַהֲוָה יְבֵשָׁה אִתְּמָר בָּהּ, מְלא כָּל הָאָרֶץ כְּבוֹדוֹ. וְאִתְקְרִיאַת בְּרָכָה דִילֵיהּ, קָרְבָּנָא דִילֵיהּ, עוֹלָה דִילֵיהּ, דְּאוֹקִיד כָּל אִלֵּין קְלִיפִּין.</p>\n<p>וּסְלִיקַת לְגַבֵּיהּ קְטֹרֶת. קִשׁוּרָא דִילֵיהּ, עוֹלָה דִילֵיהּ, דִכְתִיב (ויקרא ו׳:י״ח) זֹאת תּוֹרַת הָעוֹלָה, הִיא הָעוֹלָה בִּצְלוֹתָא דְשַׁחֲרִית, הִיא הָעוֹלָה לְגַבֵּיהּ בִּצְלוֹתָא דְמִנְחָה בְּכַמָּה רֵיחִין וּבוּסְמִין דְּגָן עֶדֶן דְאִיהִי גָן דְּאוֹרַיְיתָא. הֲדָא הוּא דִכְתִיב, (שיר השירים ד׳:י״ב) גָן נָעוּל אֲחוֹתִי כַלָּה, סְתִימָא דְלָא אִתְפַּתְּחַת אֶלָּא לְגַבֵּי בַּעְלָהּ.</p>\n<p>וְכַד יֵיתֵי בַּעְלָהּ (תהילים נ״א:י״ז) אֲדֹנָי שְׂפָתַי תִּפְתָּח דְאִיהִי בָּבַא עִלָּאָה אִתְפַּתְּחַת לְגַבֵּיהּ כִּתְרִין (בתרין) סַמְכֵין קְשׁוֹט וְקַבִּילַת לֵיהּ בִּתְרֵין דְּרוֹעִין, הֲדָא הוּא דִכְתִיב (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי.</p>\n<p>יהו\"ה נָחִית לְגַבָּהּ וְדָא הוּא רָזָא אָמֵ\"ן (דאמ\"ן) גִימַטְרִיָּא יאהדונה\"י דְּאִיהוּ חִבּוּרָא דִּתְּרֵין שְׁמָהָן בְּאַתְוָון. וּבְגִין דָּא גָּדוֹל הָעוֹנֶה אָמֵן יוֹתֵר מִן הַמְבָרֵךְ בְּזִמְנָא דְּאִינוּן תְרֵין בְּרֵישָׁא דְּצַדִּיקַיָּא.</p>\n<p>אֲבָל כַּד אִינוּן בְּרֵישָׁא דְּחֲיָּיבַיָּיא כְּנֶסֶת יִשְׂרָאֵל אֲמָרַת לְגַבַּיְיהוּ (שיר השירים א׳:ו׳) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחֹרֶת מֵאִלֵּין דְּשַׁרְיָין לְפַתָּאָה לִבְנִי נָשָׁא כְּמָה דַהֲווּ מְפָתִין לְיִשְׂרָאֵל בַעֲגָלָא בְּשִׁית שַׁעְתִּין, הֲדָא הוּא דִכְתִיב (שמות ל״ב:א׳) וַיַּרְא הָעָם כִּי בֹּשֵׁשׁ מֹשֶׁה לָרֶדֶת מִן הָהָר. וְאוּקְמוּהָ מַאי כִּי בֹּשֵׁשׁ, אֶלָּא בְּשִׁית שַׁעְתִּין עֲבָדוּ יָת עֶגְלָא בְּגִין לְאַפְרָשָׁא לוֹן מִשֶׁבַע. הֲדָא הוּא דִּכְתִיב (שמות י״ב:ט״ו) אַךְ בַּיוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְׁאֹר, אַךְ חִלֵק בֵּין שֵׁשׁ לְשֶׁבַע.</p>\n<p>וּבְגִין דָּא אָמְרָה כְּנֶסֶת לְיִשְׂרָאֵל שֶׁשְׁזָפַתְנִי הַשָׁמֶשׁ גָּרְמוּ דְאִסְתַּלַּק מִנִּי ו' דְּאִיהוּ הַשֵׁשׁ <Nonei></i>וְאוֹר הַשֵׁשׁ דַהֲוָה נָהִיר בְּסִתְרָא דְשִׁית תֵיבִין דְּאִינוּן (דברים ו׳:ד׳) שֵׁמַע יִשְׂרָאֵל יְיָ אֱלהֵינוּ יְיָ אֶחָד, בְּנֵי אִמִּי נִחֲרוּ בִּי, נִיחַר גְּרוֹנָם דְּבַטִּילוּ קְרִיַת שְׁמַע דְּאִתְּמָר בֵּיהּ (תהילים קמ״ט:ו׳) רוֹמְמוֹת אֵל בִּגְרוֹנָם, וּבְגִין דָּא שָׂמוּנִי נוֹטֵרָה אֶת הַכְּרָמִים, דְּאִינוּן שְׁאָר אוּמִין עֶרֶב רָב. וּבְגִין דָּא כַּרְמִי שֶׁלִי לֹא נָטָרְתִי וּבְגִין דָּא אִינוּן עֶרֶב רָב מַצְלִיחִין בְּכֹלָּא.</p>\n<p>כָּתְנוֹת עוֹר חֲשׁוֹכִין דְּעַיְינִין דְּאִתְּמָר בְּהוֹן (בראשית כ״ז:א׳) וַתִּכְהֶיןָ עֵינָיו מֵרְאוֹת, לְאִסְתַּכְּלָא לְאִלֵּין דְּאִתְּמָר בְּהוֹן (יחזקאל א׳:א׳-ב׳) נִפְתְּחוּ הַשָׁמַיִם וָאֶרְאֶה מַרְאוֹת אֱלֹהִים דְּאִינוּן חֲמֵשׁ אוֹר דְעוֹבָדָא דִבְּרֵאשִׁית כָּתְנוֹת אוֹר אִינוּן.</p>\n<p>וְהָאָרֶץ הָיְתָה תֹהוּ. וְהָאָרֶץ הוּא חַד. תֹהוּ תְּרֵין. בְּהוּ תְלָת. חֹשֶׁךְ אַרְבַּע. תְּהוֹם חֲמֵשׁ. וְאַרְבַּע אִינוּן דִכְלִילָן בְּגוּפָא וְאִינוּן אַרְבַּע יְסוֹדִין דְּאִינוּן קְלִיפִּין דֶּאֱגוֹזָא, וּבְגִין דָּא וְהָאָרֶץ הָיְתָה תֹהוּ. וְאוּקְמוּהָ הָיְתָה מִקַּדְמָת דְּנָא, דְהַכִי אָרְחָא דִקְלִיפִּין דְּמְקַדְמִין לְמוֹחָא. וְרוּחַ אֱלהִים דָא רוּחָא דִמְשִׁיחָא, דְּמִיָּד דִּיְהֵא מְרַחֶפֶת עַל אַנְפֵּי מַיָא דְּאוֹרַיְיתָא מִיָד יְהֵא פּוּרְקָנָא, הֲדָא הוּא דִכְתִיב (בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר.</p>"],[9520012809,"<p><Noneb>ספר הבהיר</b> אָמַר רִבִּי בְּרָכְיָה מַאי דִּכְתִיב וְהָאָרֶץ הָיְתָה תֹהוּ, מַאי מַשְׁמַע הָיְתָה, שֶׁכְּבָר הָיְתָה. וּמָאי תֹהוּ, דָבָר הַמָתְּהֵא אֶת בְּנֵי אָדָם. וּמָאי בֹּהוֹ, דָבָר שֶׁיְּשׁ בּוֹ מַמָּשׁ, דִכְתִיב בֹּהוֹ, בּוֹ הוּא. עַל שֵׁם מָאי דִּכְתִיב (קהלת ז׳:י״ד) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים. בָּרָא בֹּהוֹ וְשָׂם מְקוֹמוֹ בְּשָׁלוֹם. בָּרָא תֹהוּ וְשָׂם מְקוֹמוֹ בְּרָע. בֹּהוֹ בְּשָׁלוֹם דִכְתִיב (איוב כ״ה:ב׳) עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. מְלַמֵּד שְׁמִכָאֵל שַׂר יְמִינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מָיִם וּבָרָד. וְגָבְרִיאֵל שַׂר שְׂמֹאלוֹ, אֵשׁ. וְשָׂר שָׁלוֹם בֵּינֵיהֶם מַכְרִיעֲ וְהַיְינוּ דִכְתִיב עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו.</p>\n<p>וּמְנַלָן דְּבֹּהוֹ שָׁלוֹם, דִכְתִיב (ישעיהו מ״ה:ז׳) עוֹשֶׂה שָׁלוֹם וּבוֹרֵא רָע, הָא כֵּיצָד רָע מִתֹּהוּ וְשָׁלוֹם מִבֹּהוֹ, בָּרָא תֹּהוּ וְשָׂם מְקוֹמוֹ בַּרָע, שֶׁנֶּאֱמַר עוֹשֶׂה שָׁלוֹם וּבוֹרֵא רָע. בָּרָא בֹּהוֹ וְשָׂם מְקוֹמוֹ בְּשָׁלוֹם שֶׁנֶּאֱמַר עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. ע\"כ:</p>\n<p>וַיְשַׁלְּחֵהוּ יְיָ אֱלהִים, מִיָד (למשיחא) מְשִׁיחָא דְּהוּא בְּגִנְתָּא דְעֵדֶן בְּמָה דְּאִתְּמָר בֵּיהּ וַיְשַׁלְּחֵהוּ מִגַּן עֶדֶן מֵעִדּוּן דִילֵיהּ. וְאַמָּאי לַעֲבוֹד אֶת הָאֲדָמָה דְאִיהִי שְׁכִינְתָּא בְּגִין דָּא וַיְשַׁלְּחֵהוּ מִיָד, דְּיִפּוּק מִתַּמָּן. וַיַּשְׁכֵּן מִקֶּדֶם לְגַן עֶדֶן אֶת הַכְּרוּבִים דְּאִינוּן מָשִׁיחַ בֵּן דָוִד וּמָשִׁיחַ בֵּן יוֹסֵף דְּמָשְׁכָא רוּחָא דִמְשִׁיחָא דְּאִתְּמָר בֵּיהּ, וְרוּחַ אֱלֹהִים דָא שִׁילֹ\"ה הַהוּא דְּאִתְּמָר בֵּיהּ וְאַצָלְתִּי מִן הָרוּחַ, דְהַכִי סָלִיק שִׁילֹה מֹשֶׁה בְּחוּשְׁבָּנָא. וַיַּשְׁכֵּן מִקֶּדֶם, דְאַקְדִּים שִׁילה לִתְרָוָויְהוּ בְּגִין דִּיְהֵא מְרַחֶפֶת עַל אַנְפּוֹי דְּאוֹרַיְיתָא וּפוּרְקָנָא בֵּיהּ תַלְיָּיא וְהָא אוּקְמוּהָ.</p>\n<p>וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת מִיָד יְהֵא בִּידֵיהּ. וּמָאי נִיהוּ, מַטֵה מטט\"רון דְאִתְהַפַּךְ מִמַּטֶּה לְנָחָשׁ וּמִנָּחָשׁ לְמַטֶּה. וְעוֹד מַטֶּה דָא שְׁכִינְתָּא תַּתָּאָה וְאִם זָכוּ יִשְׂרָאֵל כְּלַפֵּי חֶסֶד לִימִינָא וְיִפְקוּן בְּרַחֲמֵי. וְאִם לָאו מַטֵה כְּלַפֵּי חוֹבָה לְסִטְרָא דִּגְבוּרָ\"ה דְּתַמָּן נָחָשׁ, אֵל אַחֵר. דְּתַבָע לִשְׁפּוֹךְ דָּמָא וְאִתְקְטִיל מָשִׁיחַ וְסַגִּיאִין מִיִּשְׂרָאֵל.</p>\n<p>וּבְגִין דָּא אִתְּמָר (רות ג׳:י״ג) שִׁכְבִי עַד הַבֹּקֶר דְּאִיהוּ בֹקֶר דְּאַבְרָהָם דִּיְהֵא מַטֵה כְּלַפֵּי חֶסֶד וּבְגִין דָּא וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת וְכֹלָא לִשְׁמוֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים דְאִיהִי אוֹרַיְיתָא דְּאִתְּמָר בָּהּ עֵץ חַיִּים הִיא</p>\n<p>וְאִיהִי אוֹרַיְיתָא דְּבְעַל פֶּה. אִם זָכָה בַּר נָשׁ, אִיהִי סַם חַיִּים דִילֵיהּ. וְאִם לָאו, הִיא מִתְהַפֶּכֶת לֵיהּ לְסַם הַמָּוֶת. וְהָא אוּקְמוּהָ מָארֵי מַתְנִיתִין הֲכִי, כְּגווָֹנָא דְמַטֶּה דְאִתְהַפַּךְ לְנָחָשׁ וּמִנָּחָשׁ לְמַטֶּה. וּבְזִמְנָא הַהוּא יִתְמַחוּן מִן עַלְמָא כָּל אִינוּן דְּאִתְּמָר בְּהוֹן (שמות ז׳:כ״ב) וַיַּעֲשׂוֹּ כֵּן חַרְטוּמֵי מִצְרָיִם בְּלַטֵיהֶם:</p>"],[9520012810,"<p>יָשָׁב רִבִּי בּוֹן וְדַּרָשׁ מָהוּ דִּכְתִיב (ישעיהו מ״ה:ז׳) יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ. אֶלָּא אוֹר שֶׁיֶּשׁ בּוֹ מַמָּשׁ כְּתִיב בּוֹ יְצִירָה. חֹשֶׁךְ שֶׁאֵין בּוֹ מַמָּשׁ כְּתִיב בּוֹ בְּרִיאָה כְּמָה דְּאַתְּ אָמֵר (עמוס ד׳:י״ג) יוֹצֵר הָרִים וּבוֹרֵא רוּחַ. אִי בָּעִית אִימָא אוֹר שֶׁיֶּשׁ בּוֹ מַמָּשׁ, כְּתִיב בּוֹ עֲשִׂיָּה. דִכְתִיב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. וְאֵין הֲוָיָה אֶלָּא עֲשִׂיָּה וְקָרֵי בֵּיהּ יְצִירָה. חֹשֶׁךְ דְלָא הֲוָה בֵּיהּ עֲשִׂיָּה אֶלָּא הַבְדָּלָה וְהַפְרָשָׁה קָרֵי בֵּיהּ בְּרִיאָה כְּמָה דְּאַתְּ אָמֵר הִבְרִיא פְּלוֹנִי וְכוּ'. אָמַר רִבִּי בְּרָכְיָה מָהוּ דִּכְתִיב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר וְלֹא אָמַר וְהָיָה. מָשָׁל לְמֶלֶךְ שֶׁהָיָה לוֹ חֵפֶץ נָאָה וְהִקְצָהוּ עַד שֶׁזִימֵן לוֹ מָקוֹם וְשָׂמַהוּ שָׁם הֲדָא הוּא דִכְתִיב יְהִי אוֹר וַיְהִי אוֹר שֶׁכְּבָר הָיָה. ע\"כ:</p>"],[9520012811,"<p><Nonei></i>שְׁבִיעִי הֲוֵי בְּמִזְרָחוֹ שֶׁל עוֹלָם וּמִשָׁם בָּא זָרְעַם שֶׁל יִשְׂרָאֵל כִּי חוּט הַשִׁדְרָה מָשׁוּךְ מִן הַמוֹחַ שֶׁל אָדָם וּבָא לַאָמָּה וּמִשָׁם הוּא הַזֶרַע דִכְתִיב (ישעיהו מ״ג:ה׳) מִמִּזְרָח אַבִיא זַרְעֲךָ, כְּשֶׁיִשְׂרָאֵל טוֹבִים מִזֶּה הַמָּקוֹם אַבִיא זַרְעֲךָ יִתְחַדֵּשׁ לְךָ זְרַע חָדָשׁ,</p>\n<p>וּכְּשֶׁיִשְׂרָאֵל רָעִים מִן הַזֶּרַע שֶׁכְּבָר בָּא לְעוֹלָם דִכְתִיב (קהלת א׳:ד׳) הוֹלֵךְ וְדוֹר בָּא. דוֹר שֶׁכְּבָר בָּא. וּמָאי מִמָעֲרָב אֲקַבְּצֵךְ, מֵאוֹתָה מִדָּה שׁנוֹטֶה תָּמִיד לְמַעֲרָב. וְלָמָּה אִיקְרֵי מַעֲרָב, מִפְּנֵי שֶׁשָּׁם מִתְעָרֵב כָּל הַזֶּרַע.</p>\n<p>מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְבֵן מֶלֶךְ שֶׁהָיָה לוֹ כַלָּה נָאָה וּצְנוּעָה בְּחַדְרוֹ, וְהָיָה לוֹקֵחַ מִבֵּית אָבִיו עוֹשֶׁר וּמֵבִיא לָהּ תָּמִיד וְלוֹקַחַת הַכֹּל וּמָצְנָעַת אוֹתוֹ תָּמִיד וּמְעַרֶבֶת הַכֹּל. לְסוֹף יַמִּים בִּיקֵשׁ לִרְאוֹת מָה אֲסָף וּמָה קִיבֵּץ הַיְינוּ דִכְתִיב וּמִמָעֲרָב אֲקַבְּצֵךְ. וּמַאי נִיהוּ בֵּית אָבִיו דִכְתִיב מִמִּזְרָח אַבִיא זַרְעֲךָ מְלַמֵּד שְׁמִמִזְרָח מֵבִיא וְזוֹרֵעַ בַּמָעֲרָב וְאַחַר כָּךְ הוּא מְקַבֵּץ מָה שְׁזָרָע. ע\"כ:</p>"],[9520012812,"<p>זי\"ן מַאי עֲבִידְתֵּיהּ, כְּמִנְיָן יְמֵי הַשָׁבוּעַ. לְלַמֶּדְךָ שֶׁכָּל יוֹם יֶשׁ לוֹ כֹּחַ. וּמָאי עֲבִידְתֵּיהּ הַכָא לְלַמֶּדְךָ שְׁכְּשֵׁם שֶׁיֶּשׁ חָכְמָה גְּדוֹלָה בַּאוֹזֶן לְאֵין תַּכְלִית, כָּךְ יֶשׁ הַכֹּחַ הַהוּא בְּכָל הַאֵבָרִים, וּמָאי אֵבָרִים, שֶׁבַע שֶׁיֶּשׁ בָּאָדָם. דִכְתִיב כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. ע\"כ:</p>"],[9520012813,"<p>נִשְׁמַת הַזָכָר, מִן הַזָכָר. וְנִשְׁמַת הַנְקֵבָה, מִן הַנְקֵבָה. וְהַיְינוּ דְּקָא אֲזִיל נָחָשׁ בַּתְרָה דְחַוָּה. אָמַר, הוֹאִיל וְנִשְׁמָתָה מִן הַצָּפוֹן אֲסִיתֵנָה מְהֵרָה. וּמָאי הַסָתָה הֲוָה, מִשׁוּם דְּבָּא עָלֵיהּ. שָׁאֲלוּ תַּלְמִידוֹי, עוֹבָדָא הֵיכִי הֲוָה. אָמַר לָהֶם, סמ\"אל הָרָשָׁע קַשָׁר עִם כָּל צְבָאוֹת מַעְלָה עַל רַבּוֹ. מִשׁוּם דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא, וּרְדוּ בִּדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם. אָמַר, הֵיאָךְ אוּכַל לְהַחְטִיאוֹ וּלְגָרְשׁוֹ מִלְפָנָיו. יָרַד עִם כָּל חַיָּילוֹתָיו וּבִיקֵשׁ לוֹ בָּאָרֶץ חָבֵר כְּמוֹתוֹ וּמַנוּ נָחָשׁ, וְהָיָה לוֹ דְּמוּת גָמָל. רָכָב עָלָיו וּבָא לוֹ אֵצֶל הַאִשָׁה.</p>\n<p>אָמַר לָהּ, אַף כִּי אָמַר אֱלֹהִים לא תֹאכְלוּ מִכָּל עֵץ הַגָּן. אָמַר אֲבָקֵשׁ יוֹתֵר וְאוֹסִיף, כְּדֵי שֶׁתִגְרָע הִיא. אָמְרָה, לֹא מֵנַעֲנוּ אֶלָּא מֵעֵץ הַדַּעַת אֲשֶׁר בְּתוֹךְ הַגָּן אָמַר אֱלֹהִים לֹא תֹאכְלוּ מִמֶּנּוּ וְלֹא תִּגְעוּ בּוֹ פֶּן תְּמוּתוּן. וְהוֹסִיפָה ב' דְּבָרִים, אָמְרָה מִפְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן אָמַר אֱלהִים לא תֹאכְלוּ, וְלֹא נֶאֱמַר לָהּ אֶלָּא מֵעֵץ הַדַּעַת. וְאָמְרָה, לא תִּגְעוּ פֶּן תְּמוּתוּן.</p>\n<p>מָה עָשָׂה סמ\"אל הָרָשָׁע הָלַךְ וְנָגַע בְּאִילָן וַהֲוָה הַאִילָן צוִֹוִחַ וְאֹמֵר (תהילים ל״ו:י״ב) אַל תְּבוֹאֵנִי רֶגֶל גָאַוָה וְיָד רְשָׁעִים אַל תְּנִידֵנִי, אַל תִּגַּע בִּי. שֶׁנֶּאֱמַר וְיָד רְשָׁעִים אַל תְּנִידֵנִי. הָלַךְ וְאָמַר לְאִשָׁה, הֲרֵי נָגַעְתִּי בְּאִילָן וְלָא מָתִּי, אַף אַתְּ תִּגְעִי בְּאִילָן וְלֹא תָּמוּתִי. הֲלְכָה הַאִשָׁה וְנָגְעָה בְּאִילָן וְרָאֲתָה מַלְאַךְ הַמָּוֶת בָּא כְּנֶגְדָה, אָמְרָה אוּלַי עַכְשָׁיו אֲנִי מֵתָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לוֹ אִשָּׁה אַחֶרֶת וְנוֹתְנָה לְאָדָם הַרֵינִי גוֹרֶמֶת לוֹ שֶׁיֹאכַל עִמִי אִם נָמוּת, נָמוּת שְׁנֵינוּ. וְאִם נִחְיֶּה, נִחְיֶּה שְׁנִינוּ. וְלַקְחָה מִפִּרְיוֹ וְנָתְּנָה גַּם לְבַעְלָה,</p>\n<p>נִתְפָּקְחוּ עֵינֵי שְׁנֵיהֶם וְקָהוּ שִׁנָּיו. אָמַר לָהּ מַהוּ זֶה שְׁהֶאֵכַלְתָּנִי שֶׁקָהוּ שִׁינָי, כָּךְ קָהוּ שִׁינֵי כָּל הַבְּרִיוֹת. יָשָׁב לוֹ בְּדִין אֱמֶת שֶׁנֶּאֱמַר (תהילים ט׳:ה׳) יָשַׁבְתָּ לְכִּסֵא שׁוֹפֵט צֶדֶק. קָרָא לְאָדָם וְאָמַר לוֹ, לָמָה בָּרַחְתָּ מִפָּנָי. אָמַר לוֹ, אֶת קוֹלֶךָ שָׁמָעְתִּי בַּגָּן וְרָעַדוּ עַצְמוֹתָי וָאִירָא כִּי עֵירוֹם אָנֹכִי וָאֵחָבֵא. כִּי עֵירוֹם אָנֹכִי, מִפֹּעֲלִי. כִּי עֵירוֹם אָנֹכִי, מִצִווּיִּי. כִּי עֵירוֹם אָנֹכִי, מִמַעֲשָׂי וָאֵחָבֵא.</p>\n<p>מָה הָיָה לְבוּשׁוֹ שֶׁל אָדָם עוֹר שֶׁל צִפּוֹרֶן, וְהִפְשִׁיטוֹ מֵעָלָיו. רָאָה עַצְמוֹ עֵרוֹם, שֶׁנְּאֱמַר מִי הִגִּיד לְךָ כִּי עֵירוֹם אַתָּה. אָמַר אָדָם לִפְנִי הַקָּדוֹשׁ בָּרוּךְ הוּא, רִבּוֹנוֹ שֶׁל עוֹלָם, כְּשֶׁהָיִיתִי לְבַדִּי שֶׁמָּא חֲטָאתִי לְךָ, אֶלָּא הַאִשָׁה שֶׁהֵבֶאתָּ לִּי הִיא הֵדִיחָה אוֹתִי מִדְּבָרֶיךָ. שֶׁנֶּאֱמַר הַאִשָׁה אֲשֶׁר נָתַתָּ עִמָּדִי הִיא נָתְּנָה לִּי מִן הָעֵץ.</p>\n<p>אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, לא דָּיֵּיךְ שֶׁחַטָּאת אֶלָּא שֶׁהֶחֶטֵאת לְאָדָם. אָמְרָה לְפָנָיו רִבּוֹנוֹ שֶׁל עוֹלָם, הַנָּחָשׁ הִשִׁיאַנִי לַחֲטוֹא לְפָנֶיךָ. הֵבִיא שְׁלָשְׁתָּן וְגָזַר עֲלֵיהֶן גְּזֵרוֹת דִּין ט' קְלַלוֹת וּמָוֶת וְהִפִּיל סמ\"אל וְאֶת הַכַּת שֶׁלּוֹ מִמָקוֹם קְדוּשָׁתָן מִן הַשָׁמַיִם, וְקִצֵץ רַגְלָיו שֶׁל נָּחָשׁ וְאִירְרוֹ מִכֹּל חַיָּה וּמִכָּל בְּהֵמָה וּפָקַּד עָלָיו שֶׁיִּהְיֶה מָפְשִׁיט אֶת עוֹרוֹ אַחַר שְׁבַע שָׁנִים. ע\"כ:</p>"],[9520012814,"<p><Nonei></i>(ישעיהו נ״ה:א׳) וּבְלָא מְחִיר יַיִן וְחָלָב, מָה עִנְיָן זֶה אֵצֶל זֶה. אֶלָּא מְלַמֵּד שֶׁהַיָּיִן הוּא פַּחַד וְחָלָב הוּא חֶסֶד. וּמִפְּנִי מָה הִזְכִּיר יַיִן תְּחִילָה, מִפְּנֵי שֶׁהוּא קָרוֹב אֵלֵינוּ יוֹתֵר, יַיִן וְחָלָב סַלְקָא דַּעְתָּךְ, אֶלָּא אֵימָא דְמוּת יַיִן וְחָלָב. ע\"כ.</p>"],[9520012815,"<p>רַבִּי חִיָּיא אָמַר מֵעוֹלָם דָא הֲווּ, וְגוּבְרִין גִבָּרִין דְּסִטְרָא בִישָׁא הֲווּ, דִּכְתִיב אַנְשֵׁי הַשֵׁם. אַנְשֵׁי שֵׁם לָא כְּתִיב, אֶלָּא אַנְשֵׁי הַשֵׁם כְּגווָֹנָא דָא כְּתִיב, זְכוֹר רָחֲמֶיךָ יְיָ וַחֲסָדֶּיךָ כִּי מֵעוֹלָם הֵמָּה, מֵעוֹלָם וַדָּאי נָטַל לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְאִינוּן אֲבָהָן קַדְמָאֵי לְמֶהֱוֵי רְתִיכָא קַדִּישָׁא לְעֵילָא. אָמַר רַבִּי יִצְחָק מֵעוֹלָם דָא אִיהוּ מִטָּתוֹ שְׁלִשְׁלֹמָה דִּכְתִיב וְכוּ':</p>"],[9520012816,"<p>וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, וְאָמַר רַבִּי יוֹחָנָן שְׁנֵי אוֹרִים הַגְּדוֹלִים הָיוּ, דִּכְתִיב וַיְהִי אוֹר. וְעָלָיו נֶּאֱמַר כִּי טוֹב. וְלָקַח הַקָּדוֹשׁ בָּרוּךְ הוּא הָאֶחָד וּגְנָזוֹ לַצַּדִּיקִים לֶעָתִיד לָבֹא דִּכְתִיב מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם.</p>\n<p>מְלַמֵּד שֶׁאוֹר הָרִאשׁוֹן אֵין כָּל בִּרְיָה יְכוֹלָה לְהִסְתַּכֵּל בּוֹ דִּכְתִיב וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב וַיַּרְא אֱלהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד. רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל אֲשֶׁר עָשָׂה, רָאָה טוֹב מְאֹד, מָזְהִיר וּבָּהִיר. וְלָקַח מֵאוֹרוֹ הַטּוֹב וְכָלַל שְׁלשִׁים וּשְׁתַּיִם נְתִיבוֹת הַחָכְמָה וּנְתָנוֹ לְעוֹלָם הַזֶּה.</p>\n<p>וְהַיְינוּ דִּכְתִיב (משלי ד׳:ב׳) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם תּוֹרָתִּי אַל תַּעֲזוֹבוּ. הֱוֵי אוֹמֵר אוֹצָרָה שֶׁל תּוֹרָה שֶׁבְּעַל פֶּה. וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אִם יִשְׁמֶרוּ זֹאת הַמִּדָּה בָּעוֹלָם הַזֶּה שֶׁזֹאת הַמִּדָּה נֶחְשֶׁבֶת בִּכְלַל הָעוֹלָם הַזֶּה, וְהִיא תּוֹרָה שֶׁבְּעַל פֶּה. יִזְכּוּ לְחַיֵּי הַעוֹלָם הַבָּא שֶׁהוּא הַטּוֹב הַגָּנוּז. וּמָאי נִיהוּ עוּזוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא,</p>\n<p>דִּכְתִיב (חבקוק ג׳:ד׳) וְנֹגַהּ כָּאוֹר תִּהְיֶה. עָתִיד הַנֹּגַהּ שְׁנִלְקַח מֵהָאוֹר הָרִאשׁוֹן לִהְיוֹת כָּאוֹר, אִם יֵקַיְימוּ בָּנַי הַתּוֹרָה וְהַמִּצְוָה אֲשֶׁר כַּתָּבְתִּי לְהוֹרוֹתָּם. וּכְתִיב (משלי א׳:ח׳) שְׁמַע בְּנִי מוּסַר אָבִיךָ וְאַל תִיטוֹשׁ תּוֹרַת אִמֶּךָ.</p>\n<p>וּכְתִיב (חבקוק ג׳:ד׳) קַרְנַיִם מִיָּדוֹ לוֹ וְשָׁם חֶבְיוֹן עֻזֹּהּ, וּמָאי חֶבְיוֹן עֻזּוֹ. אֶלָּא אוֹתוֹ הָאוֹר שֶׁגָנַז וְהֵחְבִּיא שֶׁנֶּאֱמַר (תהלים ל\"ד) צָפַנְתָּ לִירֵאֶיךָ, וְזֶה שֶׁנִשְׁאַר לָנוּ. (תהלים ל\"ד) פָּעַלְתָּ לַחוֹסִים בָּךְ, אוֹתָם שֶׁחוֹסִים בְּצִלְּךָ בָּעוֹלָם הַזֶּה וְשׁוֹמְרִים תּוֹרָתֶּךָ וּמְקַיְימִים מִצְוֹתֶּיךָ וּמְקַדְּשִׁים שִׁמְךָ הַגָּדוֹל וּמְיָּיחַדִּים בַּסֵּתֶר וּבַגָּלוּי, שְׁנֶּאֱמַר, נֶגֶד בְּנֵי אָדָם.</p>\n<p>אָמַר רַבִּי רְחוּמָאי, מְלַמֵּד שֶׁהִיא אוֹרָה לְיִשְׂרָאֵל וְתוֹרָה אוֹרָה. שְׁנֶּאֱמַר, (משלי ו׳:כ״ג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר, וְאָמַר נֵר זוֹ מִצְוָה. וּמִצְוָה זוֹ תּוֹרָה שֶׁבְּעַל פֶּה. אוֹר, זוֹ תּוֹרָה שֶׁבִּכְתָב. אֶלָּא מִתּוֹךְ שֶׁכְּבָר נִתְקַיָים הָאוֹר קָרֵי לָהּ אוֹר. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה לְאָדָם צָנוּעַ בְּסִיפֵי הַבַּיִת אַף עַל פִּי שְׁיוֹם הוּא וְאוֹר גָּדוֹל בָּעוֹלָם, אֵין אָדָם רוֹאֶה בְּתוֹךְ בֵּיתוֹ אֶלָּא אִם כֵּן הִכְנִיס בּוֹ נֵר. נֵר תּוֹרָה שֶׁבְּעַל פֶּה, אַף עַל פִּי שֶׁהִיא נֵר, צְרִיכָה לָהּ תּוֹרָה לְפָרֵק קוּשִׁיוֹתֶיהָ וּלְבָאֵר סוֹדוֹתֵּיהָ.</p>\n<p>וּמָאי נִיהוּ יִרְאַת יְיָ, זֶה הָאוֹר הָרִאשׁוֹן. דְּאָמַר ר' מֵאִיר מָהוּ דִּכְתִיב וַיֹּאמֶר אֱלהִים יְהִי אוֹר וַיְהִי אוֹר וְלָא אָמַר לֵיהּ וַיְהִי כֵן. מְלַמֵּד שֶׁהָאוֹר הַהוּא גָּדוֹל וְאֵין כָּל בִּרְיָה יְכוֹלָה לְהִסְתַּכֵּל בּוֹ. גְנָזוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים לֶעָתִיד לָבֹא</p>\n<p>וְהִיא מִדַּת כָּל סְחוֹרָה שֶׁבָּעוֹלָם וְהוּא כֹּחַ אֶבֶן יְקָרָה שְׁקוֹרִין סוֹחָרֶת. וְדָר וְעַל מָה הִיא מִדַּת דָר, אֶלָּא מְלַמֵּד שְׁלָקַח הַקָּדוֹשׁ בָּרוּךְ הוּא מִזִיוָה אַחַת מֵאֲלְפָּיִם, וּבָנָה מִמֶּנָּה אֶבֶן יְקָרָה נָאָה וּמְקוּשֶׁטֶת וְכָלַל בָּהּ כָּל הַמִּצְוֹת. בָּא אַבְרָהָם וּבִיקֵשׁ כֹּחוֹ לָתֵת לוֹ, נָתְנוּ לוֹ אֶבֶן יְקָרָה זוֹ וְלא רָצָה אוֹתָהּ, זָכָה וְנָטַל מִדַתּוֹ שְׁנֶּאֱמַר (מיכה ז׳:כ׳) תִתֵּן אֱמֶת ליַעֲקֹב חֶסֶד לְאַבְרָהָם.</p>\n<p>בָּא יִצְחָק וּבִיקֵשׁ כֹּחוֹ וְנָתְנוּ לוֹ, וְלא רָצָה בָּהּ. זָכָה וְנָטַל מִדַתּוֹ שֶׁהִיא מִדַּת הַגְּבוּרָה דְּהַיְינוּ הַפָּחַ\"ד. דִּכְתִיב (בראשית ל״א:נ״ג-נ״ד) וַיִּשָׁבַע יַעֲקֹב בְּפָחַד אָבִיו יִצְחָק. בָּא יַעֲקֹב וְרָצָה בָּהּ וְלֹא נְתַּנוּהוּ לוֹ, אָמַר לֵיהּ הוֹאִיל ואַבְרָהָם מִלְמַעְלָה וְיִצְחָק לְמַטָּה, אַתָּה תִּהְיֶה בְּאֶמְצַע וְתִכְלוֹל שְׁלָשְׁתַּם דִּכְתִיב תִתֵּן אֱמֶת ליַעֲקֹב.</p>\n<p>וּמָאי אֱמְצָע, הַיְינוּ שָׁלוֹם. וְהָא כְּתִיב תִתֵּן אֱמֶת לְיַעֲקֹב, אֱמֶת וְשָׁלוֹם חַד הֲוִי. כְּמָה דְאַתְּ אָמֵר (אסתר ט׳:ל׳) דִּבְרֵי שָׁלוֹם וְאֱמֶת (ישעיהט'ל) כִּי שָׁלוֹם וֶאֱמֶת יִהְיֶה בִּימֵי וְהַיְינוּ דִּכְתִיב (ישעיהו נ״ח:י״ד) וְהַאָכַלְתִּיךָ נָחֲלַת יַעֲקֹב אָבִיךָ. דְּהַיְינוּ נָחַלָה גְמוּרָה דְּאִית לֵיהּ הַחֶסֶ\"ד וְהַפָּחַד וְהַאֶמֶת וְהַשָׁלוֹם.</p>\n<p>וּלְפִיכָּךְ אָמַר (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּינָה. אֶבֶן מָאֲסוּ אַבְרָהָם ויִצְחָק שְׁבָּנוּ אֶת הָעוֹלָם, הָיְתָה עַתָּה לְרֹאשׁ פִּינָה. וְלָמָּה מָאֲסוּ בָּהּ וַהֲלא <Nonei></i>נֶּאֱמַר (בראשית כ״ו:ה׳) עֵקֶב אֲשֶׁר שָׁמַע אַבְרָהָם בְּקוֹלִי וַיִשְׁמוֹר מִשְׁמָרְתִּי מִצְוֹתָי חֻקוֹתָי וְתוֹרוֹתָי. מָאי מִשְׁמָרְתִּי, אָמַר מִדַּת חֶסֶ\"ד. כָּל יְמֵי היוֹת אַבְרָהָם בָּעוֹלָם לא הוּצְרָכְתִּי אֲנִי לַעֲשׂוֹת מֵלַאכְתִּי, שֶׁהֲרֵי אַבְרָהָם עָמָד שָׁם בִּמְקוֹמִי. וַיִשְׁמוֹר מִשְׁמָרְתִּי, בְּמִדָּה זוֹ הָיְתָה מֵלַאכְתִּי שֶׁאֲנִי מֵזָכֵּה אֶת הָעוֹלָם כֻּלּוֹ וְאֲפִילוּ נִתְחַיְיבוּ, אֲנִי מֵזָכֵּה אוֹתָם.</p>\n<p>וְעוֹד מֵשִׁיבָם וּמֵבִיא בִּלְבַבָם לַעֲשׂוֹת רָצוֹן אֲבִיהֶם. כָּל זֶה עָשָׂה אַבְרָהָם וּכְתִיב (בראשית כ״א:ל״ג) וַיִּטַּע אֶשֶׁל בִּבְאֵר שָׁבַע. סִידֵר לַחְמוֹ וּמֵימָיו לְכָל בָּאֵי עוֹלָם וְהָיָה מֵזָכֵּה וּמְדַבֶּר עַל לִבָּם, לְמִי אַתֶּם עוֹבְדִּים, עִבְדוּ אֶת יְיָ אֱלֹהֵי הַשָׁמַיִם וְהָאָרֶץ. וְהָיָה דוֹרֵשׁ לָהֶם, עַד שֶׁהָיוּ בָּאִים וְשָׁבִים.</p>\n<p>וּמְנַלָן שְׁאַף הַחַיָבִים הָיָה מֵזָכֵּה, שְׁנֶּאֱמַר הַמְכַסֶּה אֲנִי מְאַבְרָהָם וְאַבְרָהָם הָיֹה יִהְיֶה וְגוֹ'. אֶלָּא אֲזָכֶּהוּ שְׁיְבַקֵּשּׂ עֲלֵיהֶם רַחֲמִים וְיִזְכֶּה. וְכִי אֶפְשָׁר לוֹמַר שֶׁלּא יָדַע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלּא יָכְלוּ לְהִנָצֵל. אֶלָּא זְכוּתוֹ קָאָמַר. מִכָּאן אֲמְרוּ בָּא לִיטָהֵר מֵסָיְיעִין אוֹתוֹ. בָּא לִיטָמֵא פּוֹתְחִין לוֹ מָאי פּוֹתְחִין לוֹ, אוֹתָן הַפְּתוּחִים תָּמִיד.</p>\n<p>מִצְוֹתָי חֻקוֹתָי וְתוֹרוֹתָי, אָמַר, הוֹאִיל וְלֹא חֲפָצְתִי בָּהּ אֱשְׁמוֹר מִצְוֹתֶיהָ. מָאי תוֹרוֹתָי, אֶלָּא אֲפִילוּ הוֹרָאוֹת וּפִּלְפּוּלִים שְׁמּוּרִים לְמָעְלָה, הוּא יְדָעֲם וּפִלְפֵּל וְקִיְימָם.</p>\n<p>וּמָאי מִשָׁם רוֹעֶה אֶבֶן יִשְׂרָאֵל, הֱוֵי אוֹמֶר צֶדֶק הַעֶלְיוֹן. וּמָאי הָאוֹר הַגָּדוֹל הַצָּפוּן, הַיְינוּ סוֹחָרֶת. וְהָאֶבֶן שְׁדָרָה לְמַטָּה הֵימֵּנָה נִקְרֵאת דָר, וּמָאי הוּא מִיָדוֹ לוֹ, הַיְינוּ חֲמֵשׁ אֶצְבָּעוֹת שֶׁל יָד יָמִין:</p>"],[9520012817,"<p>שֶׁבַע צוּרוֹת קְדוֹשׁוֹת יֶשׁ לוֹ לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְכוּלָן כְּנֶגֶדָן בַּאָדָם, שְׁנֶּאֱמַר בְּצֶלֶם אֱלהִים בָּרָא אוֹתוֹ זָכָר וּנְקֵבָה בָּרָא אוֹתָם. וְאֵלּוּ הֵן שׁוֹק יָמִין וּשְׁמֹאל. יָד יְמִין וּשְׁמֹאל גּוּף וּבְרִית הֲרֵי שֵׁשׁ. וְהָא אֲמַרְתָּ שִׁבְעָה. שֶׁבַע הֲוֵי בְּאִשְׁתּוֹ וְהָיוּ לְבָשָׂר אֶחָד.</p>\n<p>מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְמֶלֶךְ שְׁעָלָה בְּלִבּוֹ לִיטָע בְּגָנוֹ תִשְׁעָה אִילָנִין זְכָרִים וְהָיוּ כֻּלָּם דְקַלִים, אָמַר כְּשְׁיִהְיוּ כֻּלָּם מִין אֶחָד, אִי אֶפְשָׁר לְהִתְקַיֵּים. מָה עָשָׂה, נָטַע אֶתְרוֹג בְּינֵיהֶם וְהוּא אֶחָד מֵאוֹתָן הַתִשְׁעָה שְׁעָלָה בְּלִבּוֹ לִהְיוֹת זְכָרִים וְאֶתְרוֹג מָאי הֲוֵי, נְקֵבָה וְהַיְינוּ דִּכְתִיב (ויקרא כ״ג:מ׳) פֶּרִי עֵץ הֲדַר כָּפֹּת תְּמָרִים (ע\"כ).</p>\n<p>זָכָר וּנְקֵבָה בְּרָאָם. אֶפְשָׁר לוֹמַר כֵּן וְהָא כְּתִיב וַיִּבְרָא אֱלהִים אֶת הַאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלהִים בָּרָא אוֹתוֹ וְגוֹ' וְאַחַר כָּךְ אֱעֶשֶׂה לוֹ עֵזֶר כְּנֶגְדוֹ. וַיִּקַּח אַחַת מִצַּלְעוֹתָיו וַיִסְגֹר בָּשָׂר תַּחְתֵּנָה. אֶלָּא אֵימָא, דִּכְתִיב יְצִירָה וּכְתִיב בָּהֵן עֲשִׂיָּה וּכְתִיב בָּהֵן בְּרִיאָה. עֲשִׂיָּה דִּכְתִיב זָכָר וּנְקֵבָה בָּרָא אוֹתָם, בְּעֵת הִרְכִּיב הַנְּשָׁמָה עַל הַגּוּף וְאַסָף הַכֹּל. וּמְנַלָן דְּהָאי יְצִירָה לִישְׁנָא דְּאַסוֹפֵי הוּא דִּכְתִיב, וַיּיִצֶר יְיָ אֱלֹהִים כָּל חַיַּת הַשָּׂדֶה וְכָל עוֹף הַשָׁמַיִם וַיָּבֵא אֶל הַאָדָם, וְהַיְינוּ דִּכְתִיב עַל הַאָדָם זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אוֹתָם (ע\"כ).</p>\n<p>בְּצֶלֶם אֱלהִים בָּרָא אוֹתוֹ בְּכָל אֵבָרָיו וְכָל חֲלָקַיו, וְהָא אֲמְרִינָן וא\"ו וּלְמָה הוּא דּוֹמֶה לְעוֹטֶה אוֹר כַּשַּׂלְמָה וְהַאי וא\"ו אֵינָה אֶלָּא שֵׁשׁ קְצָווֹת. אָמַר לֵיהּ, בְּרִית מִילָה וְזִווּגוֹ שֶׁל הַאָדָם חַשְׁבֵינַן אֶחָד. שְׁתֵּי יָדָיו ג'. רֹאשׁוֹ וְגוּפוֹ ה'. שְׁתֵּי שׁוֹקָיו ו'. וּכְּנְגְדָם כְּמוֹתָם בַּשָׁמַיִם דִכְתִיב (קהלת ז׳:י״ד) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים. וְהַיְינוּ יַמִּים (שמות ל״א:י״ז) כִּי שֵׁשֶׁת יַמִּים עָשָׂה יְיָ אֶת הַשָׁמַיִם וְאֶת הָאָרֶץ וְלֹא אָמַר בְּשֵׁשֶׁת יַמִּים מְלַמֵּד שֶׁכָּל יוֹם וָיוֹם יֵשׁ לוֹ כֹּחוֹ (ע\"כ):</p>\n<p>וַיֹּאמֶר אֱלֹהִים פְּרוּ וּרְבוּ וְגוֹ'. פִקּוּדָא דָא לְאִתְעַסְקָא בְּהַאי עָלְמָא בְּפִרְיָה וְרִבְיָה וּלְמֶעֱבָּד תּוֹלָדִין לְאִתְפַּשְּׁטָא שֶׁמָּא קַדִּישָׁא לְכָל סִטְרִין וּלְמִלְקַּט רוּחִין וְנִשְׁמָתִין לְמֶהֱוֵי יְקָרָא דְקוּדְשָׁא בְּרִיךְ הוּא עֵילָא וְתַתָּא. דְּכָל מָאן דְּלָא אִתְעַסַּק בְּפִרְיָה וְרִבְיָה אֲזְעִיר דִּיּוּקְנָא דְּמָרֵיהּ דְּלָא אִשְׁתְּכַח בְּהַאי עָלְמָא. וְגָרִים דְּלָא שַׁרְיָיא שְׁכִינְתָּא בְּהַאי עָלְמָא דְּכְּמָה דְאִתוֹסְפָן רוּחִין וְנִשְׁמָתִין, הֲכִי אִתּוֹסַף לְנַחֲתָא (נ\"א דוגמתא) בְּהַאי עָלְמָא זִיו יְקָרָא דְמַלְכָּא דִּכְתִיב (משלי י״ד:כ״ח) בְּרֹב עַם הֲדְרָת מֶלֶךְ וּבְּאֶפֶס לְאֹם מַחְתָּת רָזוֹן.</p>\n<p>הֲדְרָת מֶלֶךְ דָא זִּיו יְקָרָא דְמַלְכָּא דְּאִתּוֹסַף לְנַחֲתָא בְּהַאי עָלְמָא, מַחְתָּת רָזוֹן דָא זְעִירוּ דְּדִיּוּקְנָא דְמַלְכָּא דְּאַזְעִיר מֵהָאי עָלְמָא, הֲכִי אֲזְעִיר מֵעֵילָא. דְּהָא הַהוּא זִיוָא לָא נָחִית, וְאִתְחַשָׁב עַל הַהוּא בָּר נָשׁ כְּאִילוּ אוֹשִׁיד דָּמִין דְּגָרַע דִּיּוּקְנָא דִלְתַתָּא כְּגווָֹנָא דִּלְעֵילָא דִּכְתִיב כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הַאָדָם, וְאִיהוּ אֲזְעִיר צֶלֶם אֱלֹהִים לְתַתָּא, וּדְמוּת וּדְיוּקְנָא לְעֵילָא. וְעַל דָא אִצְטְרִיךְ בַּר נָשׁ לְאִתְעַסְקָא בְּפִרְיָה וְרִבְיָה וּלְמֶעֱבַד צֶלֶם אֱלהִים לְאַסְגָּאָה יְקָרָא דְּיְיָ בְּכָל סִטְרִין:</p>\n<p><Noneb>רעיא מְהֵימְנָא</b> פִקּוּדָא דָּא לְקַיִּים פִּרְיָה וְרִבְיָה לְקַיֵּים בֵּן וּבַת. בְּגִין דְּאָב תַמָּן י', וְאֵם תַמָּן ה', בֵּן תַמָּן ו', בַּת תַמָּן ה'. ואָב ואֵם דְּלֵית לוֹן בֵּן וּבַת, גַּם יְיָ' לָא שַׁרְיָא עָלַיְיהוּ, וּכְגַוונָא דָּא בְּעוֹבָדָא דְּבְּרֵאשִׁית אָמַר פְּרוּ וּרְבוּ. פְּרוּ מִסִּטְרָא דִיְמִינָא וּרְבוּ מִסִּטְרָא דִשְׂמָאלָא דְבֵּיהּ בָּרָא אֱלקִים כֹּלָּא, וּבְרָא דָּא עַמּוּדָא דְאֶמְצָּעִיתָא. אֶת הָאָרֶץ דָּא שְׁכִינְתָּא. ואַמָּאי צָּרִיךְ ד', בְּאָב וְאֵם בֵּן וּבַת. בְּגִין דְּהָא אִתְקַדָשׁוּ וְאִתְבָּרְכוּ בְּשָׁלֹשׁ קְדוּשׁוֹת וְשֶׁבַע בִּרְכָאָן דְּאִינּוּן י', צְּרִיכִין לְמֶהֱוִי ד' אַתְוון דְּשַׁרְיָין עָלַיְיהוּ עֲשָׂרָה, לְמֶהֱוִי בָּר נָשׁ רְשׁוּת הַיָּחִיד לְמָארֵיהּ, דְּרָחְבּוֹ ד' וגָבְהוֹ י'.</p>\n<p>וּמָאן דְּמִתְעַסֵּק <Nonei></i>בְּאוֹרַיְיתָא וּבְמִצְּוָה בִּדְחִילוּ וּבִרְחִימוּ דְּמָארֵיהּ בְּאֲתַר דְּיִרְאָה שַׁרְיָא תַמָּן י', בְּאֲתַר דְּאַהֲבָה שַׁרְיָא תַמָּן ה'. בְּאֲתַר דְתוֹרָה שַׁרְיָא ו', וּבְאֲתַר דְמִצְּוָה שַׁרְיָא ה'. בְּאֲתַר דְמַחֲשָׁבָה דְאִתְמָר בָּהּ (שמואל ב ז׳:י״ט) וְזֹאת תּוֹרַת הַאָדָם, כַּלִיל מִכֹּלָא. שַׁרְיָא בֵּיה יוֹ\"ד הֵ\"א וא\"ו הֵ\"א. (תהילים קכ״ז:א׳) אִם יְיָ לֹא יִבְנֶה בַּיִת שָׁוְא עָמְלוּ בּוֹנָיו בּוֹ, מָאי שָׁוְא עָמְלוּ בּוֹנָיו בּוֹ, אִינוּן סַמָּאֵ\"ל וְנָחָשׁ ע\"כ:</p>"],[9520012818,"<p>יָשָׁב רַבִּי בְּרָכְיָה וְדָּרַשׁ מָאי הַאי דְּקָא אֲמְרִינָן כָּל יוֹמָא הַעוֹלָם הַבָּא, וְלֹא יָדְעִינָן מָאי קָאָמַר, הַעוֹלָם הַבָּא מְתַּרְגֵּם עָלְמָא דְּאָתֵי מְלַמֵּד שְׁקוֹדֶם שֶׁנִּבְרָא הָעוֹלָם עָלָה בְּמַחְשָׁבָה לִבְרוֹא אוֹר גָּדוֹל לְהָאִיר וְנִבְרָא אוֹר גָּדוֹל שֶׁאֵין כָּל בִּרְיָה יְכוֹלָה לִשְׁלוֹט בּוֹ, צָפָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאֵינָן יְכוֹלִין לְסוֹבְלוֹ לָקַח שְׁבִיעִי וְשָׂם לָהֶם בִּמְקוֹמוֹ וְהַשְׁאָר גְנָזוֹ לַצַּדִּיקִים לֶעָתִיד לָבֹא. אָמַר אִם יִזְכּוּ בָּזֶה הַשְׁבִיעִי וְיִשְׁמְרוּהוּ, אֶתֶּן לָהֶם זֶה לְעוֹלָם אַחֲרוֹן. וְהַיְינוּ דִּכְתִיב, הַעוֹלָם הַבָּא. שֶׁכְּבָר בָּא מִקוֹדֶם שֵׁשֶׁת יְמֵי בְּרִאשִׁית. הֲדָא הוּא דִכְתִיב, (שם ל\"א) מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם:</p>"],[9520012819,"<p>שְׁמִינִי מָאי הֲוֵי, יֶשׁ לוֹ להַקָּדוֹשׁ בָּרוּךְ הוּא צַדִּיק אֶחָד בָּעוֹלָם וְחֲבִיב לוֹ מִפְּנֵי שְׁמְקַיֵּים כָּל הָעוֹלָם כֻּלּוֹ וְהוּא יְסוֹדוֹ וְהוּא מְכַלְכְּלוֹ וּמַצְמִיחוֹ וּמְגַּדְּלוֹ וּמְשָׂמְחוֹ. אֲהוּב וְחֲבִיב לְמַעְלָה, נוֹרָא וְאַדִּיר לְמַטָּה. מְתוּקַן וּמְקוּבָּל לְמַעְלָה, מְתוּקַן וּמְקוּבָּל לְמַטָּה. וְהוּא יְסוֹד הַנְפָשׁוֹת כֻּלָּם.</p>\n<p>אֲמַרְתָּ שְׁמִינִי וְאָמַרְתָּ יְסוֹד הַנְפָשׁוֹת כֻּלָּם, וְהָא כְּתִיב וּבְיוֹם הַשְׁבִיעִי שַׁבָּת וַיִּנָּפַשׁ. אִין שְׁבִיעִי הֲוִי, אֶלָּא מִשׁוּם דְּמַכְרִיעַ בֵּינַיְיהוּ, וְיֵשׁ אִינוּן תְלָת לְרָע וּתְלָת לְעֵיל, וְהוּא דְּאַכְרָע בֵּינַיְיהוּ.</p>\n<p>וּמָאי טַעְמָא אִקְרֵי שְׁבִיעִי, וְכִי הוּא בַּשְׁבִיעִי, לֹא. אֶלָּא מִפְּנֵי שהַקָּדוֹשׁ בָּרוּךְ הוּא שַׁבָת בְּשַׁבָּת בְּאוֹתָה הַמִּדָּה. דִּכְתִיב (שמות ל״א:י״ז) כִּי שֵׁשֶׁת יָמִים עָשָׂה יְיָ אֶת הַשָׁמַיִם וְאֶת הָאָרֶץ וּבַיוֹם הַשְׁבִיעִי שַׁבָּת וַיִּנָּפַשׁ. מְלַמֵּד שֶׁכָּל יוֹם וָיוֹם יֶשׁ לוֹ מַאֲמָר אֶחָד שֶׁהוּא אֲדוֹן לוֹ, לא מִפְּנֵי שֶׁהוּא נִבְרָא בּוֹ, אֶלָּא מִפְּנִי שֶׁהוּא פּוֹעֵל בָּעוֹלָם פְּעוּלָה הַמְסוּרָה לוֹ בְּיָדוֹ. פָּעַלוּ כֻּלָּם פְּעוּלָתָם וְקִיֵּימוּ מַעֲשֵׂיהֶם לְבָד, בָּא יוֹם הַשְׁבִיעִי וּפָעָל פְּעוּלָתוֹ. שָׂמְחוּ כֻּלָּם וְאַף הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלֹא עוֹד אֶלָּא שְׁגַּדְלָה נִשְׁמָתוֹ, דִּכְתִיב וּבְיוֹם הַשְׁבִיעִי שַׁבָּת וַיִּנָּפַשׁ.</p>\n<p>וּמָאי הֲוֵי שְׁבִיתָה זוֹ דְּלָא הֲוֵי בָּהּ מְלָאכָה, וַהֲוֵי הַנָחַה. דִּכְתִיב שַׁבָּת. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְמֶלֶךְ שֶׁהָיוּ לוֹ שִׁבְעָה גָּנוֹת, וּבַגָּן הָאֶמְצָעִי מַעְיָן נָאֶה נוֹבֵעַ מִמָקוֹר מַיִם חַיִּים, ג' מִימִינוֹ וג' מִשְׂמֹאלוֹ. וּמִיָּד שׁפּוֹעֶל בָּעוֹלָם, אָז מִתְמָלֵא וְשְׂמֵחִים כֻּלָּם. וְאוֹמְרִים לְצֹרְכֵנוּ הוּא מִתְמָלֵא וְהוּא מָשְׁקֵה אוֹתָם וּמֵגַּדְלָם וְהֵם מָמְתִינִין וְשׁוֹבְתִין וְהוּא מָשְׁקֵה אֶת הַשִׁבְעָה.</p>\n<p>וְהָא כְּתִיב (ישעיהו מ״ג:ה׳) מִמִּזְרָח אֲבִיא זַרְעֲךָ וַהֲוֵי חַד מִנְהוֹן וּמָשְׁקֵה לֵיהּ. אֶלָּא אֵימָא הוּא מָשְׁקֵה אֶת הַלֵּב וְהַלֵּב מָשְׁקֵה אַחַר כֵּן כֻּלָּם. וּמָאי נִיהוּ מִדָּה שְׁבִיעִית הוֵי אוֹמֶר זוֹ מִדַּת טוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>מָאי טַעְמָא אָמַר אֶת שַׁבְּתוֹתַי, וְלֹא אָמַר אֶת שַבָּתַי. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְמֶלֶךְ שֶׁהָיָה לוֹ כַלָּה נָאָה וְכָל שָׁבוּעַ וְשָׁבוּעַ מָזְמִינָה יוֹם אֶחָד לִהְיוֹת עִמּוֹ. וְהַמֶּלֶךְ יֶשׁ לוֹ בָּנִים נָאִים וְאַהוּבִים אָמַר לָהֶם הוֹאִיל וְכֵן שִׂמְחוּ אַתֶּם גַם כֵּן בְּיוֹם שִׂמְחַתִי כִּי אֲנִי בְּשְׁלָכֶם אֲנִי מִשְׁתַּדֵּל וְאַתֶּם גַּם כֵּן הֲדְרוּ אוֹתוֹ.</p>\n<p>וּמָאי זָכוֹר וְשָׁמוֹר זָכוֹר לַזָּכָר וְשָׁמוֹר לַנְּקֵבָה. מָאי טַעְמָא (ויקרא י״ט:ל׳) וּמִקְדָשִׁי תִּירָאוּ. שִׁמְרוּ עַצְמְכֶם מֵהִרְהוּר, כִּי מִקְדָשִׁי קָדוֹשׁ הוּא לָמָה (ויקרא כ׳:ח׳) כִּי אֲנִי יְיָ מֵקַדִשְׁכֶם, אֲנִי בְּכָל צָד. ע\"כ:</p>"],[9520012820,"<p>תָּאנָא עַמּוּד אֶחָד מִן הָאָרֶץ עַד לָרָקִיעַ וְצַדִּיק שְׁמוֹ עַל שֵׁם הַצַּדִּיקִים וּכְּשְׁיִשְׂרָאֵל צַדִּיקִים מִתְגַבֵּר וְאִם לָאו מִתְחַלֵשׁ וְהוּא סוֹבֵל כָּל הָעוֹלָם דִּכְתִיב (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם. וְאִם חָלַשׁ לֹא יוּכַל לְהִתְקַיֵּים הָעוֹלָם. עד כאן:</p>"],[9520012821,"<p>רַבִּי חֲנִינָא פָּרִישׁ כָּל חַד עַל קִיוּמָא. שָׂשׂוֹן חַד. שִׂמְחָה תְרֵין. חָתָן תְלָת. כַלָּה אַרְבַּע. גִּילָה דִּיצָה אַהֲבָה אַחְוָה שָׁלוֹם וְרֵיעוּת י' כְּנֶגֶד עֲשָׂרָה מַאֲמָרוֹת שְׁבָּהֵן נִבְרָא הָעוֹלָם. ע\"כ:</p>"],[9520012822,"<p><Nonei></i>ס\"א יֵצֶר טוֹב וְיֵצֶר רָע דְּאִיהוּ חֶדְוָה וְאַיְיתֵי לָהּ לְגַבֵּיהּ, וּלְעֵילָא סִטְרָא דְּצָפוֹן מַמָּשׁ דְּאִיהוּ חֶדְוָה בְּלֹא זוֹהֲמָא דְיֶצֶר הַרָע אֲחִיד בֵּיה (נ\"א בה). בְּקַדְמִיתָא דִּכְתִיב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וּלְבָתָר וִימִינוֹ תְּחַבְּקֵנִי וְאִתְיְּיהִיבַת בֵּין יְמִינָא לִשְׂמָאלָא (נ\"א ושמאלא) (לאתזנא) וְעַל דָא וַיּיִצֶר (יי אלהים שם מלא לגבי תרין סטרין אלין. את האדם וכו')</p>"],[9520012823,"<p>אָמַר לֵיהּ (שיר השירים ז׳:י״ב) לְכָה דּוֹדִי נֵצֶא הַשָּׂדֶה לְכוּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא לְטָיֵּיל וְאַל אֶשֵׁב תָּמִיד בְּמָקוֹם אֶחָד וּמָאי ל\"ב אָמַר לֵיהּ, אִם כֵּן בֵּן זוֹמָא מִבַּחוּץ וְאַתָּה עִמּוֹ ל\"ב הוּא (והוא) שְׁלשִׁים וּשְׁתַּיִם וְהָיוּ סְתוּמִים וּבָהֵם נִבְרָא הָעוֹלָם. וּמָאי שְׁלשִׁים וּשְׁתַּיִם אָמַר לֵיהּ לֵ\"ב נְתִיבוֹת</p>\n<p>מָשָׁל לְמֶלֶךְ שֶׁהָיָה יוֹשֵׁב בְּחַדְרֵי חֲדָרִים וּמִנְיָן הַחֲדָרִים לֵ\"ב. וּלְכָל אֶחָד מִן הַחֲדָרִים יֶשׁ נָתִיב נָאֶה לְמֶלֶךְ זֶה לְהִכָּנֵס (הכל) בְּחֲדְּרוֹ עַל דֶּרֶךְ נְתִיבוֹת. אָמַר, לֹא נָאֶה לוֹ שֶׁלּא לְגַלּוֹת פְּנִינָיו וּמִשְׁכְּנוֹתָיו וּגְנָזָיו וְחֲמוּדוֹתָיו. אֲמַרְתָּ לא. מָה עָשָׂה, נָגַע בְּבַת וְכָּלַל בָּהּ כָּל הַנְתִיבוֹת וּמַלְבּוּשֵׁיהָ וְהַרוֹצֶה לְהִכָּנֵס (ס\"א להסתכל בעיניה) בִּפְנִים, יִסְתַּכֵּל הֵנָּה. וּנְשָׂאָה לַמֶּלֶךְ. גַּם נִתָּנָה לוֹ בְּמַתָּנָה. וְלִפְעֲמִים קוֹרֵא אוֹתָהּ בְּאַהֲבָתוֹ, (בת) אֲחוֹתִי כִּי מִמָקוֹם אֶחָד הָיוּ וְלִפְעֲמִים קוֹרֵא אוֹתָהּ בִּתִּי, כִּי בִּתּוֹ הִיא. וְלִפְעֲמִים קוֹרֵא אוֹתָהּ אִמִּי.</p>\n<p>וְעוֹד כִּי אֵין דִּין אִם אֵין חָכְמָה, שֶׁהֲרֵי נֶּאֱמַר (מלכים א ה׳:כ״ו) ויְיָ נָתַן חָכְמָה לִשׁלֹמֹה. וְאַחַר כָּךְ דָן אֶת הַדִּין עַל מַתְכּוּנְתּוֹ דִּכְתִיב (מלכים ג') וַיִּשְׁמְעוּ כָּל יִשְׂרָאֵל אֶת הַמִּשְׁפָּט וְגוֹ' כִּי רָאוּ כִּי חָכְמָה אֱלהִים בְקִרְבּוֹ וְגוֹ'.</p>\n<p>וּמָה חָכְמָה נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁלֹמֹה. שְׁלֹמֹה נָשָׂא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדְּאַמְרִינָן, כָּל שְׁלֹמֹה שְׁבְּשִׁיר הַשִׁירִים קֹדֶשׁ, לְבָד מֵאֶחָד. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹאִיל וְשִׁמְךָ כִּשְׁמִי, אֲשִׂיא לְךָ בִּתִּי. וְהָא נְשׁוֹּאָה הִיא, אָמַר לֵיהּ, בְּמַתָּנָה נְתָּנָה לוֹ הַשֵׁם. וַיְיָ נָתַן חָכְמָה לִשְׁלֹמֹה וְלָא פֵּירַשׁ. וְהֵיכָן פֵּירַשׁ, לְהַלָן. כִּי רָאוּ כִּי חָכְמַת אֱלהִים בְקִרְבּוֹ לַעֲשׂוֹת מִשְׁפָּט (נ\"א ומאי משפט אלא כל זמן שאדם עושה משפט חכמת אלחים בקרבו) וּמָאי לַעֲשׂוֹת מִשְׁפָּט, הֱוִי אוֹמֶר שְׁאוֹתָה חָכְמָה שְׁנְתָנָה אֱלהִים וְשְׁהִיא עִמּוֹ בְּחֲדְּרוֹ, הִיא בְקִרְבּוֹ. זֹאת עוֹזְרָתוֹ וּמְקַרְבָתוֹ וְאִם לָאו מַרְחֲקַתוֹ וְלֹא עוֹד אֶלָּא מֵיָסְרָתוֹ דִּכְתִיב (ויקרא כ״ו:כ״ח) וְיִסַּרְתִּי אֶתְכֶם אַף אֲנִי:</p>"],[9520012824,"<p>בְּשַׂעְרָא, בְּגּווָֹנִין דְּשַׂעְרָא. בַּאֲרִיכוּ דְּשַׂעְרָא. בְּקְמִיטוּ דְּשַׂעְרָא. בְּמִצְּחָא, בִּקְמִיטוּ דְּמִצְּחָא, בַּאֲרִיכוּ, בְּשִּׂרְטוּטִין. בְּפוּתְיָא. בְּאוּדְנִין, בְּשַׂעְרָא דְּנָחִית עָלַיְיהוּ, אוֹ תְּחוֹתַיְיהוּ, אוֹ אַבַּתְרַיְיהוּ דְּאוּדְנִין. בְּאַנְפִּין. בְּעַיְינִין. בְּגּווָֹנִין דְּעַיְינִין. בִּקְרִיצִּין דְּעַל עַיְינִין.</p>\n<p>וכֹל נְבִיאַיָּא לָא הֲווּ מָשִׂיגִין לִנְבוּאָה דְּאִיהִי בְּרַתָּא דְמַלְכָּא, וְלָא מָשִׂיגִין לָהּ בְּכָל אֲתַר, כְּמוֹ מֹשֶׁה. אֶלָּא, מִנְהוֹן הֲווּ מָשִׂיגִין לָהּ בְּרֵישָׁ\"א. מִנְהוֹן בְּאֻדְנִי\"ן בִּשְׁמִיעָה. מִנְהוֹן בְּעַיְינִין בִּרְאִיָה. מִנְהוֹן בְּחוֹטָמָא בְּרֵיחָא. מִנְהוֹן בְּאַנְפִּין בְּדִבּוּ\"ר מִנְהוֹן בְּיָדִי\"ן לְקַבְּלָא דוֹרוֹן. מִנְהוֹן בְּרָגְלִין הֲדָא הוּא דִכְתִיב (יחזקאל ב׳:א׳) בֵּן אָדָם עֲמוֹד עַל רַגְלֶךָ. בִּצְּלוֹתָא</p>\n<p>אִלֵּין דְּקָיְמִין בַּעֲמִידָה וּמַטְרוֹנִיתָא קָמַת בְּגִינַיְיהוּ בְּגִין דְאִלֵּין דְּאִתְקְרִיאוּ רַגְלִין אִינוּן עַבֲדִין בְג' רִאשׁוֹנוֹת וּבְג' וּבְאֶמְצָּעִיוֹת אַחֲרוֹנוֹת דִּצְּלוֹתָא וּבְגִין דָא צָּרִיךְ עַבְדָא לְמֶהֱוִי בַּעֲמִידָה קֳדָם מַטְרוֹנִיתָא אוֹ קֳדָם מַלְכָּא וּמַטְרוֹנִיתָא דְּתְהֵא יַתְבָא</p>\n<p>וּבְזִמְנָא דְּנַפְקוּ יִשְׂרָאֵל מִמִּצְּרַיִם כֻּלְּהוּ נַפְקֵי רַגְלִין וּכְּמָה דְאַתְּ אָמֵר (שמות ו' י\"ב) כְּשֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי וְכֻלְּהוּ הֲווּ עַבְדִין כְּמָה דְאַתְּ אָמֵר (ויקרא כ\"ה) כִּי לִי בְּנֵי יִשְׂרָאֵל עֲבָדִים, מִיָּד דְּאָתָא מֹשֶׁה קָרָא לוֹן בְּנִין. הֲדָא הוּא דִכְתִיב (שמות ד') בְּנִי בְּכֹרִי יִשְׂרָאֵל:</p>\n<p>קָם חַד סָבָא מֵאִלֵּין דְּנַחְתּוּ וְאָמַר מִמְתִיבְתָא בּוֹצִּינָא קַדִּישָׁא וְהָא בָתָר דְּנַפְקֵי יִשְׂרָאֵל מִמִּצְּרָיִם, קָרָא לוֹן עֲבָדִין. אָמַר, וַדָּאי הֲכִי הוּא. אֲבָל הֲווּ בְּהוֹן דְאִתְקְרִיאוּ בְּנִין וּבְהוֹן הֲווּ עֲבָדִין, וּבְהוֹן עַם. כְּמָה דְאַתְּ אָמֵר, שָׁלַח אֶת עַמִי אֲבָל עֲבָדִין הֲווּ שֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי.</p>\n<p>אָמַר זַכָּאָה חוּלָקָא דְבּוּצִּינָא קַדִּישָׁא דְהַכִי נַהֲרָא בֵּיה אוֹרַיְיתָא. לְבָתָר דַהֲווּ נַפְקִין פַלִּיג לוֹן קוּדְשָׁא בְּרִיךְ הוּא לִתְלַת סִטְרִין. בְּנִין לְסִטְרָא חַד. עֲבָדִין לְסִטְרָא חַד. עַמָּא לְסִטְרָא חַד. וְהָא אוּקְמוּהָ. וּבְגִין דָא רַגְלִי\"ן. עָלַייהוּ אִתְמָר (יחזקאל ב׳:א׳) בֵּן אָדָם עֲמוֹד עַל רַגְלֶיךָ וְאִי עָאלִין בִּצְּלוֹתָא בִּדְחִילוּ וּרְחִימוּ דְי\"ה הָא הֵיכָלָא אִתְפַּתְּחַת לְגַבַּיְיהוּ כְּמָה דְאַתְּ אָמֵר (תהילים נ״א:י״ז) אֲדֹנָי שְׂפָתַי תִּפְתָּח:</p>"],[9520012825,"<p><Nonei></i>אָמַר רַבִּי רְחוּמָאי כָּבוֹד וְלֵב הֲרֵי הֵן אֶחָד אֶלָּא שְׁכָּבוֹד נִקְרָא עַל שֵׁם מַעְלָה וְלֵב אִתְקְרֵי עַל שֵׁם פְּעוּלַת מַטָּה. וְהַיְינוּ כְּבוֹד הַשֵׁם וְהַיְינוּ לֵב הַשָׁמַיִם. מָאי נִיהוּ (ישעיהו ו׳:ג׳) מְלֹא כָּל הָאָרֶץ כְּבוֹדוֹ אֶלָּא כָּל אוֹתָהּ אֶרֶץ שְׁנִבְרֵאת בְּיוֹם רִאשׁוֹן שֶׁהוּא לְמָעְלָה כְּנֶגֶד אֶרֶץ יִשְׂרָאֵל מְלֵאָה מִכְּבוֹד הַשֵׁם וּמָאי נִינְהוּ חֲכָמִים דִּכְתִיב (משלי ג׳:ל״ה) כָּבוֹד חֲכָמִים יִנְחָלוּ וּכְתִיב (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד יְיָ מִמְּקוֹמוֹ.</p>\n<p>וּמָאי הֲוֵי כָּבוֹד זֶה. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה לְמֶלֶךְ שֶׁהָיָה לוֹ מַטְרוֹנִיתָא בְּחַדְרוֹ שֶׁכָּל חַיָּילָיו מִשְׁתַעֲשְׁעִין בָּהּ וְהָיוּ לָהּ בָּנִים וּבָאִים כָּל הַיּוֹם לִרְאוֹת פְּנֵי הַמֶּלֶךְ וּמְבָרְכִין אוֹתוֹ אֲמְרוּ לוֹ אָנָה אִמֵנוּ אָמַר לָהֶם לא תּוּכְלוּ לִרְאוֹתָהּ עַתָּה. אֲמְרוּ בְּרוּכָה תְּהֵא בְּכָל מָקוֹם שֶׁהִיא.</p>\n<p>וּמָאי דִּכְתִיב מִמְּקוֹמוֹ מִכְּלַל דְּלִיכָּא דְּיָדַע אֶת מְקוֹמוֹ מָשָׁל לְמַטְרוֹנִיתָא שְׁבָּאָה מִמָקוֹם רָחוֹק וְלֹא יָדְעוּ מֵאַיִן בָּאָה עַד שְׁרָאוּ שֶׁהִיא אֵשֶׁת חַיִל נָאָה וְהַגּוּנָה בְּכָל מַעֲשֶׂיהָ, אֲמְרוּ זֹאת וַדָּאי מִן הָאוֹר נִלְקְחָה כַּךְ בְּמַעֲשֶׂיהָ הֵאִירָה אֶת הָעוֹלָם. שָׁאֲלוּ אוֹתָהּ מֵאַיִן אַתְּ אָמְרָה לָהֶם מִמְקוֹמִי אֲמְרוּ אִם כֵּן גְּדוֹלִים אַנְשֵׁי מְקוֹמֶךְ בְּרוּכָה תִּהְיִּי וּמְבוֹרָךְ מְקוֹמֶךְ.</p>\n<p>וְכִי אֵין כְּבוֹד יְיָ אֶחָד מִצִבְאוֹתָיו לא גָּרַע אַמָּאי מְבָרְכִין לֵיהּ. אֶלָּא מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְאִישׁ שֶׁהָיָה לוֹ גָן נָאָה וְחוּץ לְגַן בְּקַרוֹב מִמֶּנּוּ חַתִּיכַת שָׂדֶה. וְאִם הִשְׁקָה הַגָּן בִּתְּחִלַּת שָׁקְיוּתוֹ הָלְכוּ לָהֶם הַמָּיִם עַל כָּל הַגָּן. אַךְ אוֹתָהּ חַתִּיכָה שֶׁל שָׂדֶה שֶׁהִיא אֵינָה דְבוּקָה, אַף עַל פִּי שְׁהַכֹּל אֶחָד הוּא לְפִיכָךְ פָּתַח לָהּ מָקוֹם וְהִשְׁקָה לָהּ לְבַדָּהּ.</p>"],[9520012826,"<p>עַל יַמִּים יָסְדָה, אִלֵּין חַכִּימִין דְּיִשְׂרָאֵל רַבְרְבַיָּא דְּיָסְדָן אוֹרַיְיתָא וְחָכְמָתָא דְּאִתְקְרִיאַת הַיָּם הַגָּדוֹל וְכֵן הוּא אוֹמֵר (קהלת א') וְעַל נְהַרוֹת אִלֵּין תַּלְמִידָיָּיא דְּאִינוּן רַבְרְבִין מִן נַהֲרָא. וְכֵן הַרָב גָּדוֹל מִן הַתָלְמִידִים. וְאִינוּן מְחַדְדִין אֶת הַרָב בְּקוּשִׁיוֹתֵיהֶן. וְהוּא מְתָרֵץ לוֹן כָּל הַקוּשִׁיוֹת וְאֵינוֹ מִתְרָשֵׁל. כְּמוֹ הַנְהַרוֹת שְׁנִמְשָׁכִין לַיָּם וְאֵינוֹ מָלֵא שְׁנֶּאֱמַר כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם. וְהַרְאָיָּה אֲמְרוּ אָחֲרֵי כֵן מִי יַעֲלֶה בְּהַר יְיָ. כִּי אֵין מַעֲשֶׂה בְּלָא חָכְמָה. כִּי הַתַלְמוּד מֵבִיא לִידֵי מַעֲשֶׂה:</p>"],[9520012827,"<p>שְׁכִינְתָּא אִתְקְרִיאַת אוֹת בְּרִית מִסִּטְרָא דְצַדִיק יְסוֹד עוֹלָם זֹאת אוֹת הַבְּרִית בְּסִינַי (ס\"א ביני). עַמּוּדָא דְאֶמְצָעִיתָא. וּבֵין בְּנֵי יִשְׂרָאֵל נֶצַ\"ח הוֹ\"ד. אוֹת דָא צַדִּיק, הִיא דָא שְׁכִינְתָּא (שמות ל״א:י״ז) כִּי שֵׁשֶׁת יָמִים עָשָׂה יְיָ אֶת הַשָׁמַיִם מִכֶּתֶ\"ר עַד עַמּוּדָא דְאֶמְצָעִיתָא. דְּלֵית שִׁית בְּכָל אֲתַר אֶלָּא מִסִּטְרָא דְּאָתְּ ו' וְלֵית שְׁבִיעִי אֶלָּא מִטְרָא דְּאָתְּ י' עֲטָרָה עַל רֵישֵׁיהּ חָכְמָ\"ה עִלָּאָה אוֹת הִיא חָכְמָה תַתָּאָה אוֹת הִיא. וְתַּקִינוּ לְמִגְזָר לִתְמָנְיָּיא דְּאִיהוּ תַמָּן חָכְמָ\"ה עַד יְסוֹד לְקָבְּלָא בְּהוֹן י' זְעִירָא לְסַלְקָא לָהּ עַד כֶּתֶר לְמֶהוֵי עֲטָרָה עַל רָאשֵׁיהוֹן וְתַּקִינוּ לְשָׁוְיָּיא עָרְלָה בְּמָנָא וְעַפְרָא לְקַיֵּים (ישעיהו ס״ה:כ״ה) וְנָחָשׁ עָפָר לַחְמוֹ:</p>"],[9520012828,"<p>אהניאל \"ברקיאל \"גדיאל \"דומיאל \"הדריאל \"ודרגזיה \"זהריאל \"חניאל \"טהריאל \"יעזריאל \"כרעיאל \"למדיאל \"מלכיאל \"נהריאל \"סניה \"ענאל \"פּתּחיאל \"צּוריאל \"קנאל \"רמיאל \"שעריאל \"תּבכיאל: <Nonei></i>סדר תּשר\"ק \"תּפּוריא \"שכניאל \"רנאל \"קמריה \"צּוריה \"פּסיסיה \"עיריאל \"סמכיאל \"נריאל \"מדוניה \"לסניה \"כמסריה \"יריאל \"טסמסיה \"חניאל \"זכראל \"ודריאל \"הניאל \"דנבאל \"גדיאל \"בדאל \"אדירירון אדני על כולהו וכו':</p>"],[9520012829,"<p><Noneb>רַעֲיָא מְהֵימְנָא</b> וַיַּחֲלוֹם וְהִנֵּה סוּלָם מֻצָּב אַרְצָּה. וְהִנֵּה סוּלָם דָא צְּלוֹתָא, מֻצָּב אַרְצָּה, דְּמָצְּלָאן בְּנֵי נָשָׁא לֵיהּ בְּאַרְעָא דְּאִיהִי שְׁכִינְתָּא וּמַטָא לִשְׁמַיָּא דְּאִיהוּ קוּדְשָׁא בְּרִיךְ הוּא דְאִתְמָר בֵּיה (מלכים א ח׳:ל״ב) וְאַתָּה תִּשְׁמַע הַשָׁמַיִם וְרָזָא דְּמִלָה (תהילים ח׳:ב׳) יְהוָֹ\"ה אֲדֹנֵינוּ מָה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ וגוֹ'.</p>\n<p>וּבְזִמְנָא דְּמוֹדָע לוֹן קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ דְּסָלְקָא בְּהַהוּא צְּלוֹתָא, מִיָד וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עוֹלִים וְיוֹרְדִים בּוֹ. בּוֹ בְּהַהוּא בַּר נָשׁ. כֻּלְּהוּ פַּתְחִין גַדְפַיְיהוּ לְקָבְּלָא שְׁכִינְתָּא בְּהַהִיא צְּלוֹתָא, הֲדָא הוּא דִכְתִיב (יחזקאל א׳:י״א) וְכַנְפֵיהֶם פְּרוּדוֹת מִלְמַעְלָה וְהַאי אִיהוּ עוֹלִים שְׁכִינְתָּא עַל גַדְפַיְיהוּ וְיוֹרְדִים בּוֹ. מָאי בּוֹ, בְּקוּדְשָׁא בְּרִיךְ הוּא. דְקוּדְשָׁא בְּרִיךְ הוּא נָחִית עָלַיְיהוּ לְקָבְּלָא שְׁכִינְתֵּיהּ וּמְיַיחֵד קוּדְשָׁא בְּרִיךְ הוּא בֵּיה בְּהַהוּא בַּר נָשׁ בִּצְּלוֹתֵיהּ.</p>\n<p>דִשְׁכִינְתָּא אִיהִי מִצְּוָה כְּלִילָא בְּשֵׁם יְהוָֹ\"ה אִיהִי חַיָּה דִילֵיהּ. וּמִצְּוָה בְּלא מַחֲשָׁבָה לֵית לָהּ סְלִיקוּ. וּמַחֲשָׁבָה אִיהוּ אָדָ\"ם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א תִפְאֶרְ\"ת. מִצְּוָה מַלְכוּתָא כְּלִילָא מֵאַרְבַּע חֵיוָון דְמֶרְכַּבְתָּא, כְּלִילָא מֵאַרְבַּע אַתְוון. אִיהִי נוּקְבָא דִילֵיהּ, אַנְפִּין דִילֵיהּ, אַנְפּוֹי דְּרַחֲמֵי. בְּגִינָהּ אֲמֵינָא (שמות ל״ג:ט״ו) אִם אֵין פָּנֶיךָ הוֹלְכִים וְגוֹ'.</p>\n<p>וּמִסִּטְרָא דְצַּדִיק אִתְקַרְיָא אֲחוֹרוֹי חַיָּה כְּלִילָא חָ\"י חוּלְיָין דְּאֲחוֹרוֹי דְּבָּר נָשׁ, דְּדָמֵי לְשִׁדְרָה דְּבֵיהּ חָ\"י חוּלְיָין. אִיהִי אָחוֹר לְעוֹבַדָא דְּבְּרֵאשִׁית וְקֵדֶם לְמַחֲשָׁבָה דְאִתְמָר בָּהּ, עֲלָהּ בְּמַחֲשָׁבָה. מָה דְּלָאו הֲכִי בַּאָדָם, דְּאֲחוֹר דְּעֵץ הַדַּעַת טוֹב וָרָע דְּאִיהוּ אָחוֹר לְמַעֲשֶׂה בְּרִאשִׁית, וקֵדֶם לְפּוּרְעֲנוּת.</p>\n<p>קָמוּ תַּנָּאִין וְאֱמוֹרָאִין וְאָמְרוּ רַעְיָא מְהֵימְנָא בְּרִיךְ אֲנְתְ לֵאֱלָהָא עִלָּאָה, הוּא יְקָם לָךְ בַּעוּתָךְ בְּכֹלָּא. קָם סָבָא עִלָּאָה בְּינֵיהוֹן וְאָמַר רַעְיָא מְהֵימְנָא בָּךְ אִתְקָיָּים הַאי קְרָא דְאִתְמָר (ישעיהו ס״ב:ז׳) וְאַל תִּתְנוּ דֹּמִי לוֹ דְּהָא עִלָּאִין וְתַתָּאִין מֵקַנְנֵי בְּצּוּלְמָא דִּידָךְ מַשִׁירְיָין דְקוּדְשָׁא בְּרִיךְ הוּא דְּאִינוּן מְתִיבְתָּא עִלָּאָה וּמַשִּׁירְיָין דְּמַטְרוֹנִיתָא דְּאִינוּן מִמְתִּיבְתָא תַתָּאָה עֲלָךְ אִתְמָר וְהִנֵּה מַלְאֲכֵי אֱלהִים עוֹלִים וְיוֹרְדִים בּוֹ</p>\n<p>בָּךְ סָלְקִין מַשִׁירְיָין דִשְׁכִינְתָּא בִּצְּלוֹתָא וְנָחֲתִין מַשִׁירְיָין דְקוּדְשָׁא בְּרִיךְ הוּא לְגַבֵּי שְׁכִינְתֵּיהּ בְּכַמָּה שִׁירִין וְנִגּוּנִין דִּצְּלוֹתָא. אֲנְתְ הוּא קְרִיבָא דְקוּדְשָׁא בְּרִיךְ הוּא בִּצְּלוֹתָא דִּילָךְ, דְּאִיהוּ קָרְבָּנָא דְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ בְּאֵיזְהוּ מְקוֹמָן בְּצַּו אֶת בְּנֵי יִשְׂרָאֵל וְכוּ' דְּתַקִּינוּ מָארֵי מַתְנִיתִין קָרְבָּנִין דִּצְּלוֹתָא מִסִּטְרָא דִיְמִינָא דְּתַמָּן כֹּהֵן אִישׁ חֶסֶ\"ד</p>\n<p>וְתַּקִינוּ זְּמִירוֹת דְּאִינוּן שִׁיר דִלְוִיִּם אַבַּתְרַיְיהוּ מִסִּטְרָא דִּגְבוּרָ\"ה. וְהוֹ\"ד דַרְגָּא דְּדָוִד אִתְקַשַׁר בִּשְׂמָאלָא דִּגְבוּרָ\"ה. וְאַהֲרֹן דְדַרְגָא דִילֵיהּ בְּהוֹ\"ד אִתְקַשַׁר בְּחֶסֶ\"ד. הֲדָא הוּא דִכְתִיב (תהלים י\"ז) נְעִימוֹת בִּימִינְךָ נֶצַּח.</p>\n<p>שְׁמַע יִשְׂרָאֵל דְּיִחוּדָא כָּלִיל בָּרְכוּ וּקְדוּשָׁה. דְּאִיהוּ קָדוֹשׁ. קָדוֹשׁ. קָדוֹשׁ. וּבְרָכָה מִסִּטְרָא דִיְמִינָא הֲדָא הוּא דִכְתִיב (במדבר ו׳:כ״ג) דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרְכוּ אֶת בְּנֵי יִשְׂרָאֵל. וּקְדוּשָׁה מִסִּטְרָא דִלְוִיִּם עַמּוּדָא דְאֶמְצָּעִיתָא קִשׁוּרָא דִיְמִינָא וּשְׂמָאלָא וְאִיהוּ קִשׁוּרָא דִתְפִלִּין דְּרֵישָׁא דְּאִיהוּ אִימָא עִלָּאָה. תְּפִילִין עַל רֵישֵׁיהּ, כְּמָה דְּאוּקְמוּהַ מָארֵי מַתְנִיתִין. תְפִלִּין דְמָארֵי עָלְמָא, מָה כְּתִיב בְּהוּ. וְאִיהוּ קִשׁוּרָא דִתְפִלִּין דְיַד, דְּאִיהִי שְׁכִינְתָּא תַתָּאָה. וְהַאי אִיהוּ דְּאוּקְמוּהַ מָארֵי מַתְנִיתִין הֵרְאָהוּ לְמֹשֶׁה קֶשֶׁר שֶׁל תְפִלִּין</p>\n<p>ש דִּילָךְ מֹשֶׁה כָלִיל תְלָת אַנְפֵּי אֲבָהָן לְעֵילָא דְּתַקִּינוּ ג' צְּלוֹתִין דְּאִיהוּ סִימָנָם שַׁחֲרִית מִנְחָה עַרְבִית. מִשׁוּם הֲכִי דִּידָךְ צְּלוֹתָא דְּשַׁבָּת דְאִתְמָר בֵּיהּ (בה) (בראשית א׳:כ״ו) וּרְדוּ בִּדְגַת הַיָּם וּבְעוֹף הַשָׁמַיִם וּבַבְּהֵמָה וּבְכָל הָאָרֶץ</p>\n<p>וְאִתְכְּלִיל מֵרְכָּבְתָא תַתָּאָה דְאֲהַרֹן דָוד וּשְׁלֹמֹה ואָדָם קַדְמָאָה לְעֵילָא וּבַת זוּגִיהּ לְתַתָּא אֵם כָּל חָי דְּאִיהוּ צַּדִּיק חָ\"י עָלְמִין. וּבְגִין דָא אַהֲרֹן אַף עַל גַּב דְּאִיהוּ יְמִינָא אוּקְמוּהָ רָבַּנָן בֵּיהּ, אַהֲרֹן שׁוּשְׁבִינָא דְּמַטְרוֹנִיתָא הֲוָה. רַעְיָא מְהֵימְנָא, יַעֲקֹב אִיהוּ כָּלִיל תְלָת אֲבָהָן דְבֵּיהּ רָכִיב אָדָם קַדְמָאָה וְלָאו לְמַגָּנָא אוּקְמוּהָ מָארֵי מַתְנִיתִין שׁוּפְרֵיהּ דְּיַעֲקֹב כְּשׁוּפְרָא דְּאָדָם קַדְמָאָה.</p>\n<p>אָמַר בּוֹצִּינָא קַדִּישָׁא רַעְיָא מְהֵימְנָא חָזֵינָא דְּכַּפָל קוּדְשָׁא בְּרִיךְ הוּא שְׁמָךְ וְאָמַר מֹשֶׁה מֹשֶׁה לְאַכְלָלָא לָךְ בְּמֶרְכַּבְתָּא עִלָּאָה תַתָּאָה. וּבְּמֶרְכַּבְתָּא לְאַכְלָלָא בָּךְ אָדָם קַדְמָאָה מִסִּטְרָא דְּאַבְרָהָם וּלְאַכְלָלָא בָּךְ חַוָּה מִסִּטְרָא דְאֲהַרֹן דָוִד וּשְׁלֹמֹה.</p>\n<p>לָמָה לֹא כָּפָל שְׁמֵיהּ דְּיַעֲקֹב הֲכִי אָמַר לֵיהּ בּוֹצִּינָא קַדִּישָׁא בְּגִין דְקָרָא לֵיהּ יַעֲקֹב וְקָרָא לֵיהּ יִשְׂרָאֵל. יַעֲקֹב לִישָׁנָא דְּעוּקְבָא דְּהַיְינוּ נוּקְבָא, דְאִתְמָר עֲקֵבוֹ שֶׁל אָדָם הָרִאשׁוֹן מַכְהֵה גַלְגַּל חַמָּה. וְאִקְרֵי יִשְׂרָאֵל, דְּתַמָּן רֹאשׁ דְכוּרָא, רֵישָׁא לְנוּקְבָא, דְּהַיְינוּ עָקֵב. וְהַאי אִיהוּ דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא לְחִוְיָּיא (בראשית ג׳:ט״ו) הוּא יְשׁוּפְךָ <Nonei></i>רֹאשׁ וְאַתָּה תְּשׁוּפֶנוּ עָקֵב. וְדָא גָרַם שְׁכִינְתָּא בְּגָלוּתָא דְאִתְמָר בֵּיה (משלי כ״ב:ד׳) עֵקֶב עֲנָוָה יִרְאַת יְיָ.</p>\n<p>חָדָא רַבִּי שִׁמְעוֹן וְחַדּוּ מָארֵי מְתִיבְתָּא ואָמְרוּ קַמֵּיהּ. פּוּמָא דִשְׁכִינְתָּא סִינַי, מָאן יָכִיל לְמֵיקָם (קמיה) דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ מְמַלְּלָן בֵּיה וְשִׁתִּין רִבְבָן דִּמְתִיבְתָּא תַתָּאָה מְמַלְלִין בֵּיה וְאוּף שִׁתִּין רִבּוֹא דִּמְתִיבְתָּא עִלָּאָה הֲכִי מְמַלְלִין בֵּיה. עַל פּוּמָךְ אִתְמַר והִנֵּה מַלְאֲכֵי אֱלהִים עוֹלִים וגוֹ'.</p>\n<p>דָּבָר אַחֵר וַיַּחֲלוֹם וְהִנֵּה סֻלָּם. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר סִינָ\"י דָא סֻלָּ\"ם וְאִיהוּ קַ\"ל וְרָזָא דְמִלָה (ישעיהו י״ט:א׳) הִנֵּה יְיָ רוֹכֵב עַל ע\"ב קַ\"ל. ע\"ב דָא יוֹ\"ד הֵ\"י וָי\"ו הֵ\"י וְעוֹד יוֹ\"ד. יוֹ\"ד הֵ\"א. יוֹ\"ד הֵ\"א וא\"ו. יוֹ\"ד הֵ\"א וא\"ו הֵ\"א, דָא קַ\"ל. אַתְוון קַדְמָאַן סָלְקִין לְע\"ב אַתְוון דְּאִינוּן תּוֹלָדִין דִּילְהוֹן סָלְקִין קַ\"ל. ע\"ב קַ\"ל מָאתַן וּתְרֵין כְּחֻשְׁבָּן ב\"ר. אֲנְתְ הוּא בָּר, רַעְיָא מְהֵימְנָא עֲלַךְ אִתְמַר (תהלים ב') נַשְׁקוּ בָּר, אֲנְתְ הוּא רַבָּן דְּיִשְׂרָאֵל רָב לְתַתָּא רַבָּן דְּמַלְאֲכֵי הַשָׁרֵת ב\"ר לְעֵילָא בְּרָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ</p>\n<p>(חס\"ר ג\"ם לאשלמא רמ\"ה) עָלַיְיהוּ אִתְמַר לְגַבֵּי מָשִׁיחַ בֶּן יוֹסֵף (שמואל ב י״ב:י״ג) גַּם יְהוָֹ\"ה הֶעְבִיר חֲטָאתְךָ לֹא תָּמוּת. בְּהַאי גָּ\"ם אִתְכַּפָּר דָוִד והָאי אִיהוּ שִׁיעוּרָא דְּחַלָּה מ\"ג בֵּיצִּים וְתוֹסֶפֶת חוֹמֵשׁ בֵּיצָּה רָמִיז (ויקרא ה׳:ט״ז) וחֲמִישִׁיתוֹ יוֹסֵף עַלָּיו.</p>\n<p>זַכָּאָה צְּלוֹתָא דְנָפִיק מִפּוּמָךְ כְּגווָֹנָא דְּקוּדְשָׁא בְּרִיךְ הוּא דְּנָחִית עַל טוּרָא דְסִינָי וְאִתְּמַר בֵּיה (דברים כ״ט:י״ד) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה עִמָּנוּ עוֹמֵד הַיּוֹם וְאֶת אֲשֶׁר אֵינֶנּוּ פֹּה עִמָּנוּ הַיּוֹם, הֲכִי כַּד אַתְּ מִשְׁתַּדֵּל בְּאוֹרַיְיתָא וּבִצְּלוֹתָא, קוּדְשָׁא בְּרִיךְ הוּא כָּנִישׁ עִלָּאִין וְתַתָּאִין. וְכָל אִלֵּין נִשְׁמָתִין דַהֲווּ וּדְּעֲתִדִין לְמֶהֱוִי, וְכָל מַשִׁירְיָין דְּמַלְאָכִין. וְנָחִית בְּצּוּלְמָא דִּילָךְ, לְקָבְּלָא צְּלוֹתָא דִּילָךְ, אוֹרַיְיתָא דִּילָךְ. בְּגִין דְּמַחֲשָׁבְתָא דִּילָךְ לְיַחֲדָא לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ בְּכָל מַשִׁירְיָין דִּילֵיהּ לְעֵילָא וְתַתָּא</p>\n<p>בְּאוֹרָיְיתָךְ וּבִצְּלוֹתָךְ קוּדְשָׁא בְּרִיךְ הוּא מְצָּרֵף מַחֲשָׁבָה טוֹבָה לְמַעֲשֶׂה. וּכְגַוְונָא דְּאִיהוּ אָמַר אָנֹכִי, וְאִינְהוּ אַמְרִי (שמות כ״ד:ז׳) נַעֲשֶׂה וְנִשְׁמָע. הֲכִי קוּדְשָׁא בְּרִיךְ הוּא עֲבִיד לְכֻלְּהוּ מַשִׁירְיָין וְאִינְהוּ שָׁתְקִין ושָׁמְעִין לְמִלוּלָךְ בְּגִין דִּרְעוּתָךְ בְּהוֹן לְיַחֲדָא קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ בְּכָל מַשִׁירְיָין דִּילֵיהּ</p>\n<p>וְכָל מָה דְּקוּדְשָׁא בְּרִיךְ הוּא אַבְטַח וְאוֹדֵי לְמֶעְבָּד לָךְ חָכְמָה מִכַּמָּה טָבִין דְּלֵית לוֹן סוֹף כֻּלְּהוּ אָמְרִין נַעֲשֶׂה וְנִשְׁמָע. וּבְגִין דָא אֲמְרוּ (תהילים ק״ג:כ׳) בָּרְכוּ יְיָ מַלְאָכָיו גִּבּוֹרֵי כֹּחַ וְגוֹ' וְאִתְתַּקַּף בָךְ דְּהָא קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ וְכָל מַשִׁירְיָין דִּילֵיהּ וּדְּשְׁכִנְתֵּיהּ אִסְתַּכְּמוּ לְמֶעְבָּד כָּל רְעוּתָךְ, וְיַתִּיר מִדָּאי הוּא כְּתִיב עַל יְדָךְ ולא נָפַל מִלָּה זְעִירָא מִכְּתִיבָת יְדָךְ דְלָא אִתְקָיָּים. זַכָּאָה בַּר נָשׁ דְּמָרֵיהּ חָשִׁיב לֵיהּ כְּגוּפֵיהּ וְעָבִיד לֵיהּ יְקָרָא כְּדִיּוּקְנֵיהּ לְמֶהֱוִי שָׁקִיל מִלּוּלִין דְּפּוּמוֹי בְּאוֹרַיְיתָא בִּצְּלוֹתָא בְּלִימוּד בְּטוּרָא דְסִינָי. וְלֵית חַד דְּפָּתָח פּוּמֵיהּ לְקַטְרְגָא, אֶלָּא עִלָּאִין ותַתָּאִין בְּאַסְכָּמוּתָא חֲדָא בִּרְעוּתָא חֲדָא. ע\"כ: (עד כאן רעיא מהימנא מההשמטות)</p>"],[9520012830,"<p>וַיִּזְכּוֹר אֱלהִים אֶת רָחֵל, בְּשָׂרָה כְּתִיב פְּקִידָה, וּבְּרָחֵל כְּתִיב זְכִירָה. אַמָּאי, בְּגִין דְּזָכוֹר אִתְרְשִׁים בְּיַעֲקֹב דְּאִיהוּ בְּרִית שָׁלוֹם כָּד אִתְעֲבִיד יוֹסֵף, וּבְמָה כַּד נָטַל שׁוֹר בַּהֲדֵיהּ דְלָא יַתְקִיף לְסִטְרָא אַחֲרָא. וּבְגִין כָּךְ אִתְקְרֵי יוֹסֵף בְּכוֹר, דְּהַהוּא שׁוֹר דְנָטַל, בְּכוֹר שׁוֹרוֹ וַדָּאי, וְהַהוּא שׁוֹר, שׁוֹר תַּם וְיַעֲקֹב אִישׁ תַּם. רִבּוֹן וְשָׁלִיט מָארִיהּ דְּבֵיתָא, דְּהַהוּא שׁוֹר תַּם שָׁארֵי בְּגַוִּיהּ:</p>"],[9520012831,"<p>לִי הַכֶּסֶף וְלִי הַזָּהָב. מָאי לִי הַכֶּסֶף וְלִי הַזָּהָב, מָשָׁל לְמָה הַדָּבָר דּוֹמֶה לְמֶלֶךְ שֶׁהָיוּ לוֹ שְׁתֵּי אוֹצָרוֹת, אַחַת שֶׁל כֶּסֶף וְאַחַת שֶׁל זָהָב. שָׂם שֶׁל כֶּסֶף בִּימִינוֹ וְשֶׁל זָהָב בִּשְׂמֹאלוֹ אָמַר זֶה יִהְיֶה מְזוּמָן וְקַל לְהוֹצָאָה וְעוֹשֶׂה דְבָרָיו בְּנָחָת וְהוּא יִהְיֶה דַבֵק עִם הַעֲנִיִּים וּמָנְהִיגָּם בְּנָחָת. כְּהַהִיא דְאַמְרֵינָן, (שמות ט״ו:ו׳) יְמִינְךָ יְיָ נֶאְדָּרִי בַּכֹּחַ. וְאִם שָׂמֵחַ אָדָם בְּחֶלְקוֹ טוֹב,</p>\n<p>וְאִם לָאו, (שמות ט״ו:ו׳) יְמִינְךָ יְיָ תִּרְעַץ אוֹיֵב. מָאי יְמִינְךָ יְיָ תִּרְעַץ אוֹיֵב, אָמַר לוֹ, זֶה הַזָּהָב דִּכְתִיב לִי הַכֶּסֶף וְלִי הַזָּהָב. לָמָה נִקְרָא שְׁמוֹ זָהָב שְׁבּוֹ כְּלוּלוֹת שְׁלשׁ מִדּוֹת. הַז', ז' מִדּוֹת. הַה', ה' אַחֲדוֹת אַחֲרוֹנוֹת (ס\"א אחרונה) הַב' חָכְמָ\"ה וּבִינָ\"ה וְנִקְרֵאת נְשָׁמָה זוֹ עַל שֵׁם אַצִילוּת ה' סְפִירוֹת אַחֲרוֹנוֹת וְה' שֶׁמוֹת לְנְשָׁמָה (ס\"א נר\"ן ח\"י סימנא נפש רוח נשמה חיה יחידה). רוּחַ, חַיָּה, יְחִידָה, נְשָׁמָה, נֶפֶשׁ.</p>\n<p>מָאי עֲבִידְתֵּיהּ כִּסֵּא הִיא ה' לְז'. דִּכְתִיב כִּי גָּבוֹהּ מֵעַל גָּבוֹהּ שׁוֹמֵר וּגְבוֹהִים עֲלֵיהֶם וּב' הִיא קִיוּמָם כְּמָה דְאַתְּ אָמֵר בְּבְּרֵאשִׁית. וּמָאי עֲבִידְתֵּיהּ הַכָא, מָשָׁל לְמָה הַדָּבָר דּוֹמֶה לְאֶחָד שֶׁהָיָה לוֹ בַּת טוֹבָה וּנְעִימָה וּשְלֵמָה וְנָאָה וְהִשִׂיאָה לְבֵן מֶלֶךְ וְהִלְבִּישָׁה וְעִיטְרָה וְקִישְׁטָה וּנְתָּנָה לוֹ עִם מָמוֹן רַב. אָמַר אֶפְשָׁר לְמֶלֶךְ זֶה לָשֶׁבֶת חוּץ מִבֵּיתוֹ, אֲמַרְתָּ לֹא. אֶפְשָׁר לוֹ לָשֶׁבֶת כָּל הַיּוֹם תָּמִיד עִמָּהּ, אֲמַרְתָּ לֹא. הָא כֵּיצָד שָׂם חַלּוֹן בֵּינוֹ לְבֵינָהּ וְכָל שָׁעָה שֶׁצְרִיכָה הַבַּת לְאָבִיהָ אוֹ הָאָב לְבִּתּוֹ מִתְחַבְּרִין יַחַד בַּחַלוֹן. הֲדָא הוּא דִכְתִיב, (תהילים מ״ה:י״ד) כָּל כְּבוּדָה בַּת מֶלֶךְ פְּנִימָה מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ ע\"כ.</p>\n<p>(וכתיב) (וויהם כסף) <Nonei></i>(שמות כ״ז:י״ז) וְאֲדְנֵיהֶם נְחשֶׁת דְּאִינוּן מָאנֵי שִׁמוּשָא לְאִשְׁתַּמְשָׁא מַשְׁכְּנָא בְּהוּ. אֲבָל הַכָא בְּאִלֵּין לְבוּשִׁין דִּיְקָר לָא בָּעֵי לְאִשְׁתַּמְשָׁא בְּהוּ בַּר נָשׁ אַחֲרָא בָּר כַּהֲנָא (נ\"א מכהנא) רַבָּא, דְּרְבוּ מְשַׁח קוּדְשָׁא עַל רֵישָׁא. דִּכְתִיב (שמות כ״ח:ב׳) (ועשית) בִּגְדֵי קֹדֶשׁ לְאַהֲרֹן אָחִיךָ לְכָבוֹד וּלְתִפְאָרֶ\"ת, דְּבְּאִינוּן לְבוּשִׁין דָמֵי לְגּווָֹנָא דִּלְעֵילָא:</p>"],[9520012832,"<p>מַאי פֶּרִי עֵץ הֲדַר אִילָנָא דְּאֶתְרוֹגָּא וּמָאי הֲדַר הַיְינוּ הֲדַר עַל הַכֹּל וְהַיְינוּ הֲדַר דְּשִׁיר הַשִׁירִים דִּכְתִיב בֵּיה (שיר השירים ו׳:י׳) מִי זֹאת הַנִשְׁקַפָה כְּמוֹ שָׁחַר. וְהַיְינוּ עַל שֵׁם נְקֵבָה וְעַל שְׁמָהּ נִלְקְחָה נְקֵבָה מֵאָדָם שְׁאִי אֶפְשָׁר לְהִתְקַיֵּים עוֹלָם הֲתַחְתוֹן בְּלָא נְקֵבָה. וּמָאי טַעְמָא אִקְרֵי נְקֵבָה עַל שֵׁם שֶׁנְקַבֵיהָ רְחֲבִים וְיֵשׁ לָהּ נִקַבִים יֵתְרִים עַל הָאִישׁ. וּמָאי נִינְהוּ נְקַבִים שָׁדַיִם וֻרְחֶם וּבֵית קִיבּוּל הַוְלָד.</p>\n<p>וּמָאי נִיהוּ שֶׁאָמְרוּ שִׁיר הַשִׁירִים שֶׁהוּא הֲדַר לְכָל סִפְרֵי הַקֹּדֶשׁ אִין דְּאָמַר רַבִּי יוֹחָנָן כָּל הַסְפָרִים קֹדֶשׁ וְשִׁיר הַשִׁירִים קֹדֶשׁ קֳדָשִׁים, וּמָאי נִיהוּ קֹדֶשׁ קֳדָשִׁים. אֶלָּא קֹדֶשׁ, שֶׁהוּא קֹדֶשׁ לְקֳדָשִׁים. וּמָאי הֵם קֳדָשִׁים אֵלּוּ שֶׁכְּנֶגֶד שֵׁשׁ קְצָווֹת שֶׁבַּאָדָם וְקֹדֶשׁ הֲוֵי לְהוּ קֹדֶשׁ לְכֻלְּהוּ.</p>\n<p>וּמָאי נִיהוּ קֹדֶשׁ זֶה, אֶתְרוֹג שֶׁהוּא הֲדַר הַכֹּל. וְלָמָּה נִקְרָא שְׁמוֹ הֲדַר אַל תִקְרֵי הֲדַר אֶלָּא ה' דָר זֶה אֶתְרוֹג שֶׁהוּא נִפְרָד מֵאֶגֶד הַלוּלָב וְאֵין מִצְוַת לוּלָב קַיְימֶת אֶלָּא בּוֹ, וְהוּא גַּם כֵּן אֲגּוּד עִם הַכֹּל. שְׁעִם כָּל אֶחָד הוּא וְעִם כּוּלָן יַחַד הוּא.</p>\n<p>וּמָאי לוּלָב כְּנֶגֶד חוּט הַשִּׂדְרָה. וְעַנָף עֵץ עֲבוֹת שְׁעֲנָפָיו חוֹפִין אֶת רוּבּוֹ וְאִם אֵין עֲנָפָיו חוֹפִין אֶת רוּבּוֹ אֵינוֹ כְּלוּם. מִפְּנֵי מָה, מָשָׁל לְאָדָם שְׁבִּזְרוֹעוֹתָיו יָגֵן עַל רֹאשׁוֹ הֲרֵי זְרוֹעוֹתָיו שְׁנַיִם וְרֹאשׁוֹ שְׁלשָׁה וְהַיְינוּ עֲנָף לִשְׂמֹאל עֲבוֹת לְיָמִין וְנִמְצָא עֵץ בְּאֶמְצַע. וְלָמָּה נֶּאֱמַר בּוֹ עֵץ שֶׁהוּא שֹׁרֶשׁ הֲאִילָן.</p>\n<p>וּמָאי עַרְבֵי נַחַל שׁוֹקֵי הַאָדָם שֶׁהֵם שְׁתַּיִם. וּמָאי נִינְהוּ לִישָׁנָא דְּעֲרְבֵי נַחַל, מִשׁוּם דְּגָדוֹל שֶׁבָּהֶם הֲוֵי לְמַעֲרָב וּמִשָׁם יוֹנֵק כֹּחוֹ. וְשֶׁל צָפוֹן הוּא קָטָן מִמֶּנּוּ מַהֲלַךְ חֲמֵשׁ מֵאוֹת שָׁנָה וְהוּא בְּרוּחַ צְפוֹנִית מָעֲרָבִית וּבוֹ פּוֹעֵל וְנִקְרָא עַל שְׁמוֹ וְהֵם שְׁנֵיהֶם עֵצִים.</p>\n<p>דָבָר אַחֵר עַרְבֵי שְׁפְּעֲמִים מֵעַרְבִין פְּעוּלָתָן זֶה עִם זֶה מָאי עַרְבֵי נַחַל, נַחַל הֲוִי עַל שֵׁם הַמָּקוֹם שֶׁהֵם קְבוּעִים בּוֹ שֶׁשְׁמוֹ נַחַל כְּדִכְתִיב (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם. מָאי נִיהוּ יָם, הֱוֵי אוֹמֶר זֶה אֶתְרוֹג. וּמְנָא לָן דְּכָל מִדָּה וּמִדָּה מֵאֶלוּ הַשִׁבְעָה אִיקְרֵי נַחַל שְׁנְּאֱמַר (במדבר כ״א:י״ט) וּמְמָתַנָה נָחֲלִיאֵל אַל תִקְרֵי נָחֲלִיאֵל אֶלָּא נַחֲלֵי אֵל.</p>\n<p>וְעוֹד שָׁם, מָה לֵב, הֲדַר פֶּרִי הַגּוּף, אַף יִשְׂרָאֵל פֶּרִי עֵץ הֲדַר. מָה אִילָן תָּמָר, עֲנָפָיו סְבִיבָיו וְלוּלָבוֹ בְּאֶמְצַע, אַף יִשְׂרָאֵל נָטְלוּ גּוּף הֲאִילָן הַזֶּה שֶׁהוּא לִבּו וּכְּנְגֶד הַגּוּף חוּט הַשִּׂדְרָה בָּאָדָם שֶׁהוּא עִיקָר הַגּוּף. וּמָה לוּלָב זֶה כְּתִיב לוֹ לֵב אַף לֵב מָסוּר לוֹ. וּמָה לֵב זֶה שְׁלשִׁים וּשְׁתַּיִם נְתִיבוֹת חָכְמָה בּוֹ, אַף בְּכָל נְתִיב מֶהֵן צוּרָה שׁוֹמֶרֶת שְׁנֶּאֱמַר (בראשית ג׳:כ״ד) לִשְׁמוֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים:</p>"],[9520012833,"<p><Nonei></i>(שמות כ׳:ט״ו) וְכָל הָעָם רוֹאִים אֶת הַקּוֹלוֹת וְאֵת הַלַּפִּידִים. וְכִי רוֹאִים אֶת הַקּוֹלוֹת אֶלָּא וְכָל הָעָם רוֹאִים אֵת הַקּוֹלוֹת, אוֹתָן קוֹלוֹת שֶׁנֶּאָמַר (תהילים כ״ט:ג׳) קוֹל יְיָ עַל הַמָּיִם אֵל הַכָּבוֹד הִרְעִים. קוֹל יְיָ בַּכֹּחַ. וְאוֹמֵר (ישעיהו י׳:י״ג) בְּכֹחַ יָדִי עָשִׂיתִי. וְאוֹמֵר (ישעיהו מ״ח:י״ג) אַף יָדִי יָסְדָה אֶרֶץ. (תהילים כ״ט:ד׳) קוֹל ה' בֶּהָדָר. וְאוֹמֵר (תהילים קי״א:ג׳) הוֹד וְהָדָר פָּעֳלוֹ וְצִדְקָתוֹ. (תהילים כ״ט:ה׳) קוֹל יְיָ שׁוֹבֵר אֲרָזִים, זֶה קֶשֶׁת שֶׁמְשַּׁבֶּרֶת עֲצֵי אֲרָזִים וַעֲצֵי בְּרוֹשִׁים. (תהילים כ״ט:ז׳) קוֹל יְיָ חוֹצֵב לַהֲבוֹת אֵשׁ, זֶה שֶּׁעוֹשֶׂה שָׁלוֹם בֵּין הָאֵשׁ וּבֵין הַמַּיִם שֶׁחוֹצֵב כֹּחַ הָאֵשׁ וּמוֹנִעַ אוֹתוֹ מִלִלְחוֹךְ הַמַּיִם גַּם מוֹנִעַ מִלְכָבּוֹתוֹ. (תהילים כ״ט:ח׳) קוֹל יְיָ יָחִיל מִדְבָּר, שֶׁנְּאמַר (תהילים י״ח:נ״א) וְעוֹשֶׂה חֶסֶד לִמְשִׁיחוֹ לְדָוִד וּלְזָרְעוֹ עַד עוֹלָם. יוֹתֵר מִן הַמִּדְבָּר. (תהילים כ״ט:ט׳) קוֹל יְיָ יְחוֹלֵל אַיָּלוֹת וַיֶחֱשׂוֹף יְעָרוֹת וּבְהֵיכָלוֹ כֻּלּוֹ אוֹמֵר כָּבוֹד. דִּכְתִיב (שיר השירים ב׳:ז׳) הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַיִם בִּצְבָאוֹת אוֹ בְּאַיְלוֹת הַשָּׂדֶה. הָא לַמָדְתָּ שֶׁבְּשֶׁבַע קוֹלוֹת נִיתָּנָה הַתּוֹרָה וּבְכוּלָּם נִגְלָה עֲלֵיהֶם אֲדוֹן הַעוֹלָם, וְרָאוּם. וְהַיְינוּ, דִּכְתִיב (שמות ב') וְכָל הָעָם רוֹאִים אֶת הַקּוֹלוֹת.</p>\n<p>כָּתוּב אֶחָד אוֹמֵר (תהילים י״ח:י׳) וַיֵּט שָּׁמַיִם וַיֵּרַד וַעֲרָפֶל תַּחַת רַגְלָיו. וְכָתוּב אֶחָד אוֹמֵר (שמות כ׳:י״ט) כִּי מִן הַשָּׁמַיִם דִּבַּרְתִי עִמָּכֶם. הַא כֵּיצָד אִשׁוֹ הַגְּדוֹלָה הָיְתָה בָּאָרֶץ שֶׁהוּא קוֹל אֶחָד, וּשְׁאָר קוֹלוֹת הָיוּ בַּשָׁמַיִם דִּכְתִיב (דברים ד׳:ל״ו) מִן הַשָּׁמַיִם הִשְׁמִיעֲךָ אֵת קוֹלוֹ לְיַסְּרֶךָּ וְעַל הָאָרֶץ הֶרְאֲךָ אֵת אִשׁוֹ הַגְּדוֹלָה וּדְבָרָיו שָׁמַעְתָּ מִתּוֹך הָאֵשׁ. וּמַאי הִיא גְּדוֹלָה, (שמאלו) וּמֵאֵלוּ הָיָה יוֹצֵא דִבּוּר מִתּוֹך הָאֵשׁ שֶׁנֶּאֱמַר, וּדְבָרָיו שָׁמַעְתָּ מִתּוֹך הָאֵשׁ.</p>\n<p>וּמַאי (דברים ד׳:י״ב) וּתְּמוּנָה אֵינְכֶם רוֹאִים זוּלָתִי קוֹל, הַהוּא כִּדְאָמַר לָהֶם מֹשֶׁה לְיִשְׂרָאֵל (דברים ד׳:י״ב) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה. תְּמוּנָה וְלא כָּל תְּמוּנָה. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְמֶלֶךְ שֶׁהָיָה עוֹמֵד עַל עֲבָדָיו מְעוּטָף בִּכְסוּת לְבָנָה לֹא דָּי לְאֵימַת הַמֶּלֶךְ שֶׁיִסְתָּכְּלוּ בִּלְבוּשָׁיו וְעוֹד רָחוֹק הָיָה הַמֶּלֶךְ וְשָׁמְעוּ קוֹלוֹ, יְכוֹלִין לִרְאוֹת גְרוֹנוֹ אֲמַרְתָּ לֹא, הַא לָמַדְּתָ שֶׁרָאוּ תְמוּנָה וְלא כָּל תְמוּנָה. וְהַיְינוּ דִּכְתִיב, וּתְמוּנָה אֵינְכֶם רוֹאִים זוּלָתִי קוֹל. וּכְתִיב (דברים ד׳:י״ב) קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים.</p>\n<p>כָּתוּב אֶחָד אוֹמֶר וְכָל הַעֲם רוֹאִים אֵת הַקּוֹלוֹת וְכָתוּב אֶחָד אוֹמֶר קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים. הָא כֵּיצָד, בַּתְחִילָה רוֹאִים אֵת הַקּוֹלוֹת. וּמָה רָאוּ שֶׁבַע קוֹלוֹת שֶׁאָמַר דָּוִד וְלָסוֹף שָׁמְעוּ הַדָּבָר יוֹצֵא מִבֵּין כֻּלָּם.</p>\n<p>וְהָא אִינוּן עֶשֶׂר. דְּרַבָּנָן אַמְרֵי דְּכֻלְּהוּ אֲמְרִינָן (אמרן) כַּחֲדָא מִלְּתָא, כֵּן כֻּלְּהוּ כַּחֲדָא מִלְּתָא אֲמְרִינָן (אמרן). וַהֲווּ שִׁבְעָה מַאֲמָרוֹת בְּשִׁבְעָה קוֹלוֹת. וְעַל דָּא נֶאֱמַר קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים וּתְּמוּנָה אֵינְכֶם רוֹאִים זוּלָתִי קוֹל. הָא לָמַדְתָּ דְּכֻלְּהוּ כַּחֲדָא, מֵחֲדָא מִלְּתָא אֲמְרִינָן (אמרן). וּבַעֲבוּר שֶׁלּא יִטְעוּ יִשְׂרָאֵל לוֹמַר אֲחֵרִים יַעֲזְרוּהוּ מִן הַמַּלְאָכִים, אַף קוֹלוֹ לְבַדּוֹ לֹא יוּכַל לִהְיוֹת חָזָק כָּל כָּךְ, בַּעֲבוּר כָּךְ חָזַר וּכְלַלָם.</p>\n<p>דָּבָר אַחֵר שֶׁלֹּא יֹאמְרוּ הַעוֹלָם הוֹאִיל וְהֵם עֲשָׂרָה מַאֲמָרוֹת לְעֶשֶׂר מַלְאָכִים שֶׁמָּא לא יוּכְלוּ לְדַבֵּר עַל פֶּה אֶחָד, כְּתִיב בֵּיהּ אָנֹכִי וְכָּלַל כָּל הַעֲשָׂרָה. וּמַאי עֲשָׂרָה מְלָכִים, שֶׁבַע קוֹלוֹת וּשְׁלשָׁה מָאֲמָרִים. וּמַאי אוֹמְרִים דִּכְתִיב (דברים כ״ו:י״ח) וַיְיָ הֶאֱמִירְךָ הַיּוֹם. וּמַאי נִינְהוּ שְׁלשָׁה, דִּכְתִיב (משלי ד׳:ז׳) רֵאשִׁית חָכְמָה קְנֵה חָכְמָה וּבְכָל קִנְיָנְךָ קְנֵה בִּינָה. כְּמָה דְאַתְּ אָמֵר (איוב ל״ב:ח׳) וְנִשְׁמַת שַׁדָּי תְבִינֵם. נִשְׁמָתוֹ שֶׁל שַׁדָּי, הִיא תְבִינֵם, שְׁלִישִׁית מַאי הֲוֵי כְּדְאָמַר לֵיהּ הַהוּא גַּבְרָא סָבָא לְהַהוּא יְנוּקָא. בַּמּוּפְלֶא מִמְּךָ אַל תִּדְרוֹשׁ וּבַמְּכוּסֶה מִמְּךָ אַל תַּחְקוֹר בְּמָּה שֶׁהִרְשְׁיתִּיךָ הִתְבּוֹנֵן אֵין לְךָ עֵסֶק בַּנִּסְתָּרוֹת.</p>\n<p>תָּנָא (משלי כ\"ה) כְּבוֹד אֱלהִים הַסְתֶר דָבָר. מַאי דָבָר, כְּמָה דְאַתְּ אָמֵר (תהלים קי\"ט) רֹאשׁ דְּבָרְךָ אֱמֶת. (משלי כ\"ה) וּכְבוֹד מְלָכִים חַקוֹר דָבָר. מַאי דָבָר, דִּכְתִיב (משלי כ\"ה) דָבָר דָּבוּר עַל אֹפָנָיו. אַל תִּקְרֵי אָפְנָיו, אֶלָּא אוֹפָנָיו:</p>"],[9520012834,"<p>וְאֵלּוּ הֵם י\"ב פִּקּוּדִין. א' יִחוּד יְיָ. ב' לְיִרְאָה אֵת יְיָ. ג' לְמִנְדַּע דְּאִית דָּיַּין וְאִית אֲגַר טָב וְכוּ'. ד' לְקַדֶשׁ אֵת יְיָ. ת לְהִתְפָּלֵל בְּכָל יוֹם שַׁחֲרִית מִנְחָה עַרְבִית. ו' לַעֲסוֹק בְּתוֹרָה. ז' לְמוּל אֵת הַבֶּן. ח' קַדֶּשׁ לִּי כָּל בְּכוֹר. ט' תְפִילִין. י' צִיצִית. י\"א מֵזוּזָה. י\"ב לִמְסוֹר נַפְשׁוֹ בִּדְבֵקוּת (ה').</p>\n<p><Nonei></i>אֵלּוּ הֵם י\"ב פִּקּוּדֵי שָׁמוֹר. א' דְּלָא לְמִיהָב רֵבוּ לְעֲבוֹדָה זָרָה. ב' דְּלָא לְמִבְנֵי מִגְדַּל לְעֲבוֹדָה זָרָה. ג' אַל תִפְנוּ וְגוֹ' (שלא) לְהַרְהֵר אַחֲרֵיהֶם. ד' לֹא תִשְׁתַּחֲוֶה לָהֶם. ה' דְּלָא לְאִתְכָּפְיָּיא, דְּהַיְינוּ לא תָעָבְדֵם. ו' דְּלָא לְהַחֲלִיף יִחוּדָא דְּמָארֵיהּ דְּהַיְינוּ הַהֶמִיר. ז' דְּלָא לְהַרְהֵרָא, דְּהַיְינוּ לא תָתוּרוּ וְגוֹ'. ח' שֶׁלֹּא לִשְׁאוֹל בְּאוֹב. ט' שֶׁלּא לִשְׁאוֹל בְּיִדְעוֹנִי. י' שֶׁלֹּא לִדְרוֹשׁ אֶל הַמֵּתִים. י\"א דְּלָא לְמֶעְבַּד חַרְשִׁין דְּהַיְינוּ וְחוֹבֵר חָבֶר. י\"ב וְשֵׁם אֱלֹהִים אֲחֵרִים שֶׁלֹּא תַזְכִּירוּ: (שמות כ׳:ג׳)</p>"],[9520012835,"<p><Noneb>מספר הבהיר</b> יָשָׁב רַבִּי בְּרֶכְיָה וְדַּרָשׁ מַאי דִּכְתִיב (שמות כ״ה:ב׳) וְיִקְחוּ לִּי תְּרוּמָה. כָּךְ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אוֹתָהּ תְּרוּמָה תָּרִימוּ אוֹתָהּ בִּתְפִלוֹתֵיכֶם, וּמִי הוּא אוֹתוֹ שֶׁנְדָבוֹ לִבּוֹ לְהִמָשֶׁךְ מִן הַעוֹלָם הַזֶּה כַּבְּדוּהוּ, כִּי בּוֹ אֲנִי שָׂמֵחַ שֶׁיוֹדִיעַ שְׁמִי, וּמִמֶּנוּ רָאוּי לָקַחַת אֵת תְּרוּמָתִי. שְׁנְּאֱמַר (שמות כ״ה:ב׳) מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְבֵנוּ לִבּוֹ תִקְחוּ אֵת תְּרוּמָתִי, מֵאוֹתוֹ הַמִתְנָדֵב.</p>\n<p>דְּאָמַר רִבִּי רְחִימָאי צַדִּיקִים וַחֲסִידִים שבְּיִשְׂרָאֵל שֶׁמְרִימִין אוֹתִי (אותו) עַל כָּל הַעוֹלָם בִּזְכוּיוֹתֵיהֶן וּמֵהֶם מִתְפָּרְנֵס הַלֵּ\"ב, וְהַלֵּב מְפָרְנֶסָן. וְכָל הַצוּרוֹת הַקְדּוֹשׁוֹת הַמֵמוּנוֹת עַל הָאוּמוֹת. וְיִשְׂרָאֵל קְדוֹשִׁים נָטְלוּ מִגוּף הֲאִילָן וּמִלִבּוֹ. מָה לֵב הֲדַר, פְּרִי הַגּוּף. אַף יִשְׂרָאֵל נָטְלוּ עֵץ הֲדַר.</p>\n<p>מָה אִילָן תָּמָר, עֲנָפָיו סְבִיבָיו וְלוּלָבוֹ בְּאֶמְצַע. אַף יִשְׂרָאֵל נָטְלוּ גוּף הֲאִילָן הַזֶּה שֶׁהוּא לִבּוֹ. וּכְּנֶגֶד הַגּוּף הוּא חוּט הַשִׁדְרָה בָּאָדָם שֶׁהוּא עִיקָר הַגּוּף לָמָה (ומה) לוּלָב זֶה, כְּתִיב לוֹ לֵּב אַף הַלֵּב מְסוֹר ל\"וֹ. וּמָה לֵ\"ב זֶה שְׁלשִׁים וּשְׁתַּיִם נְתִיבוֹת חָכְמָה בּוֹ, אַף בְּכָל נָתִיב מֵהֶם צוּרָה שׁוֹמֶרֶת. שְׁנְּאֱמַר (בראשית ג׳:כ״ד) לִשְׁמוֹר אֵת דֶּרֶךְ עֵץ הַחַיִּים.</p>\n<p>וּמַאי (בראשית ג׳:כ״ד) וַיַּשְׁכְּן מִקֶּדֶם לְגַּן עֵדֶן, וַיִּשְׁכֹּן בְּאוֹתָן נְתִיבוֹת שֶׁקַדְמוּ לְאוֹתוֹ מָקוֹם שֶׁנִקְרָא גַּן וְשֶׁקַדָם לַכְּרוּבִים. דִּכְתִיב (בראשית ג') וְאֶת הַכְּרוּבִין, וְשֶׁקַדָם לְלָהַט דִּכְתִיב (בראשית ג׳:כ״ד) אֵת לַהַט הַחֶרֶב.</p>\n<p>וְהָא כְּתִיב דְּמַיִם וְאֵשׁ קַדְמוּ דִּכְתִיב (בראשית א׳:ח׳) יְהִי רָקִיעַ בְּתוֹךְ הַמַּיִם. וּכְתִיב וַיִּקְרָא אֱלֹהִים לָרָקִיעַ שָּׁמַיִם, וּמְנַלָן דְּשָׁמַיִם הֲווּ אֵשׁ דִּכְתִיב (דברים ד׳:כ״ד) כִּי יְיָ אֱלהֶיךָ אֵשׁ אוֹכְלָה הוּא. וּמְנָא לָן דְּשָׁמַיִם הַקָּדוֹשׁ בָּרוּךְ הוּא דִּכְתִיב (מלכים א ח׳:ל״ב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. אֲטוּ שְׁלֹמֹה מִתְפָּלֵל אֶל הַשָּׁמַיִם שֶׁיִשְׁמֵעוּ תְּפִלָּתוֹ, אֶלָּא שֶׁנִקְרָא שְׁמָם עַל שְׁמוֹ. דִּכְתִיב (מלכים א ח׳:כ״ז) הַשָּׁמַיִם וּשְׁמֵי הַשָּׁמַיִם לֹא יֵכַלְכְּלוּךָ. הוֵי שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וַהֲוֵי אֵשׁ. וְאָמַרְתָּ קֶדֶם.</p>\n<p>אֶלָּא, אֵימָא כֹּחָם קֶדֶם שֶׁל אוֹתָם הַצוּרוֹת שֶׁל הַמָּקוֹם הַהוּא. וּמַאי נִינְהוּ כֹּחָם כְּמָה דְאַתְּ אָמֵר (שמואל א ב׳:ב׳) אֵין קָדוֹשׁ כַּיְיָ כִּי אֵין בִּלְתֶּךָ, וְאֵין צוּר כֵּאלֹהֵינוּ.</p>\n<p>יָשָׁב רַבִּי בְּרָכְיָה וְדַּרָשׁ, מַאי לוּלָב דְּאֲמְרִינָן, אֶלָּא לוֹ מָסָר הַלֵב וְהֵיאַךְ, אָמַר לֵיהּ שׁלֹשָׁה שָׂרִים הֵם, תל\"י וְגַּלְגַּל וְל\"ב, וּלְכָל אֶחָד וְאֶחָד שְׁנֵים עֲשָׂר. חָזְרוּ הַשְׁלֹשָׁה מִנְיָן ל\"וֹ וּבָהֵם נִתְקַיָים הַעוֹלָם דִּכְתִיב (משלי כ\"ה) וְצַדִּיק יְסוֹד עוֹלָם,</p>\n<p>תָּנָא עַמוּד א' מִן הַאָרֶץ עַד לַרָקִיעַ וְצַדִּיק שְׁמוֹ עַל שֵׁם הַצַּדִּיקִים, וְנִתְגַבֵּר. וְאִם לָאו מִתְחַלֵשׁ, וְהוּא סוֹבֵל כָּל הַעוֹלָם דִּכְתִיב וְצַדִּיק יְסוֹד עוֹלָם. וְאִם חָלַשׁ לא יוּכַל לְהִתְקַיֵּים הַעוֹלָם. הִילְכָּךְ אֲפִילוּ אֵין בָּעוֹלָם אֶלָּא צַדִּיק אֶחָד, מָעֲמִיד אֵת הַעוֹלָם. לְפִיכָךְ קְחוּ תְּרוּמָתִי מִמֶּנּוּ תְּחִלָּה, וְאַחֲרָיו זֹאת הַתְּרוּמָה אֲשֶׁר תִקְחוּ מֵאִתָּם, מֵאֵת הַנִּשְׁאָר. וּמָהוּ זָהָב וָכֶסֶף וּנְחֹשֶׁת.</p>\n<p>דָּבָר אַחֵר וְיִקְחוּ לִּי תְּרוּמָה וְיִקְחוּ לִּי לְקַדֵשׁ תְּרוּמָה שֶׁהִיא יוֹ\"ד וְהִיא עֲשִׂירִי. וּמְנַלָן דְּעֲשִׂירִי קֹדֶשׁ, דִּכְתִיב (ויקרא כ״ז:ל״ב) הָעֲשִׂירִי יִהְיֶה קֹדֶשׁ לְקַדֵשׁ. וּמַאי נִינְהוּ קֹדֶשׁ דִּכְתִיב (יחזקאל מ״ד:ל׳) וְרֵאשִׁית כָּל בִּכּוּרֵי כָּל וְכָל תְּרוּמָת כָּל מִכָּל תְּרוּמוֹתֵיכֶם דִּכְתִיב (תהילים קי״א:י׳) רִאשִׁית חָכְמָה יִרְאַת יְיָ, אֵין חָכְמָה אֶלָּא יִרְאַת הַשֵׁם:</p>"],[9520012836,"<p>אִיכָּא בְּצָוַואָת רַבִּי אֱלִיעֶזֶר הַגָּדוֹל, קַרְקַע הַגַּן הוּא כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא גַּן עֵדֶן, נָטַל שֶׁלֶג מִתַּחַת כִּסֵּא הַכָּבוֹד וּמִמֶּנָּה נַעֲשָׂה קַרְקַע הַגַּן וְזֶהוּ קַרְקַעִיתּוֹ שֶׁל גַּן עֵדֶן. וְאֵינוֹ נוֹגֵעַ עִם הָאָרֶץ הֲזֹאת שֶׁהִיא לְמָעְלָה מִכָּל הָאֲרָצוֹת.</p>\n<p>רָקִיעַ שֶׁעַל גַּבֵּי הַגַּן, הוּא כְּעֵין כָּל הַגּווָֹנִין, כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר. וּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, חָקוּק בְּאֶמְצַע הָרָקִיעַ. וְאַרְבַּע טַבָּעוֹת בְּד' קְצוֹת הָרָקִיעַ וְד' אוֹפַנִּים בְּכָל טַבַּעַת. וּבְאֶמְצַע הָרָקִיעַ עַמּוּד א', וְעַמוּד הַזֶּה נָעוּץ מִקַרְקַע הַגַּן עַד שֶׁאוֹחֵז פְּנִי כִּסֵּא הַכָּבוֹד וְהוּא מְכוּסֶּה מֵעָנָן הַכָּבוֹד. וְהַמָלְאַךְ גָבְרִיאֵל לָבוּשׁ הַבָּדִים עוֹמֵד עַלָּיו, פַּעַם כּוּלָם אוֹחַזִים בְּטַבָּעוֹת הָרָקִיעַ וְהַעֲמוּד חוֹזֵר וְהַרָקִיעַ סוֹבֵב, וְאוֹתִיּוֹת שֵׁם הַמֵפוֹרָשׁ בּוֹלְטוֹת וְנוֹצְצוֹת וְעוֹלוֹת וְיוֹרְדוֹת.</p>\n<p>קוֹל קוֹרֵא הִתְנוֹדְדוּ מַחֲנוֹת צַדִּיקִים קְדוֹשִׁים, אַשְׁרֵיכֶם שֶׁזָכִיתֶם לְכָךְ. מִי שָׁמַע כַּזֹאת, מִי רָאָה כַּאֵלֶה, בִּהְיוֹת כָּל נִגוּן הָרָקִיעַ <Nonei></i>בְּנוֹסְעוֹ עַל יְדֵי הָאִישׁ לָבוּשׁ הַבָּדִים, וְהוּא מִסְתָלֵק וְהָרָקִיעַ עוֹמֵד. וְהַעֲמוּד מְנַגֵּן, עוֹלֵה וְיוֹרֵד, עַד שֶׁנִמְשָׁךְ אוֹר זוֹהַר, אוֹר נוֹעַם מִלְמַעְלָה בְּאוֹתוֹ הַעֲמוּד. וְהַצַדִיקִים עוֹמְדִים לְנְגֶד הָאוֹר הַהוּא וְנֵהֶנִים מִמֶּנּוּ עַד חֲצוֹת הַלַּיְלָה.</p>\n<p>בַּחֲצִי הַלַּיְלָה כְּשֶׁבָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לִיכָּנֵס עִם הַצַּדִּיקִים, שׁוֹמְעִים קוֹל סִיבּוּב הָרָקִיעַ וְהַעֲמוּד מְנַגֵּן, וְקַרְקַע הַגַּן מִתְנָשֶׂא, וְהַצַדִיקִים עוֹלִים מֵחוּפּוֹתֵיהֶם לִקְרַאת בּוֹרְאָם, וְכָל הַגַּן מִתְמָלֵא מִכְּבוֹדוֹ. בְּאוֹתָה שָׁעָה מִזְדָוְּוגּוֹת הַרוּחוֹת זְכָרִים וּנְקֵבוֹת כְּפִי שֶׁהָיוּ קוֹדֶם שֶׁנִבְרֵאוּ, וּמֵאוֹתוֹ נוֹעַם תַּאֲוָתָם לַחֲזוֹת בְּנוֹעַם ה' כּוּלָם עוֹשִׂים פֶּרִי, דְּהַיְינוּ רוּחוֹת לַגֵּרִים:</p>"],[9520012837,"<p><Noneb>תּוֹסַפְתָּא</b> פִּקּוּדָא לְאַקְרָבָא קָרְבְּנָא דְּאִיהוּ חַדְּתוּתָא דְּסִיהֲרָא בְּכָל יַרְחָא וְיַרְחָא, וּבְחַדְתּוּתֵי דִּילָה לְמִקְרַב חַבִיבוּתָא עֵילָא וְתַתָּא, וּלְאַעֲבָרָא זוֹהֲמָא מִבֵּי מַקְדְּשָׁא וקָרְבְּנָא דְרֹאשׁ חֹדֶשׁ סָלִיק לְעֵילָּא. בְּגִין לְאַמְשָׁכָא נְהִירוּ דְּאַנְפִּין מִמְקוֹרָא דִלְעֵילָּא, לְתַתָּא. דְדָּא אִיצְטְרִיךְ בְּגִין מִיעוּטָא וְזְעִירוּ דְּסִיהֲרָא,</p>\n<p>וְהַהוּא שָׂעִיר דְרֹאשׁ חֹדֶשׁ אִעְבָּר זוֹהֲמָא וְסָלִיק לֵיהּ דְּלָא חָפֵי לְסִיהֲרָא. וּכְדֵין אֲנְגִיד נְגִידָן לְגַבָּהּ מֵעֵילָּא לְתַתָּא וְאִתְנָהַרָת סִיהֲרָא כְּדְקָא יֵאוֹת. בְּגִין דְּשֵׂעִיר מֵפָנֵי זוֹהֲמָא תָּדִיר מִמַקְדְּשָׁא, וְגָרַם לְאַמְשָׁכָא נְהִירוּ מֵעֵילָּא לְתַתָּא. וְקָרְבְּנָא דָא סָלִיק לְעֵילָּא.</p>\n<p>וּבְגִין כָּךְ כְּתִיב בּוֹ (ביה) (במדבר כ\"ט) חַטָּאת לַה'. בְּגִין הַהוּא זוֹהֲמָא דְּחָפֵי לְסִיהֲרָא, וְאִיהוּ רָזָא דִּכְתִיב (בראשית ד׳:ז׳) לַפֶּתַח חַטָּאת רוֹבֵץ. וְאִי תֵּימָא אֲמַאי כְּתִיב חַטָּאת לַיְיָ, אֶלָּא וַדַּאי הַהוּא שָׂעִיר מָעְבְּרָא הַהוּא חַטָּאת, וְגָרַם לְאַמְשָׁכָא נְהִירוּ מֵעֵילָּא. וְדָא אִיהוּ וְשָׂעִיר עִזִים אֶחָד לְחַטָּאת, לְאַעֲבְּרָא לֵיהּ מִן מַקְדְּשָׁא. לַיְיָ, לְאַמְשָׁכָא נְהִירוּ מֵעֵילָּא. דְּכָד חַטָּאת אִתְעֲבַר, הַהוּא נְהִירוּ וְחֶדְוָה נָחִית מֵעֵילָּא לְתַתָּא. וְעַל דָּא סָלִיק קָרְבְּנָא דָא לְעֵילָּא וְקָרְבְּנָא דָא אִקְרֵי כַּפָּרָה, לְפַנָּאָה מַקְדְּשָׁא וּלְאַעֲבָרָא זוֹהֲמָא:</p>"],[9520012838,"<p>תַּנְיָא אָמַר רַבִּי יוֹסִי גָּלִיף הֲוָה חוּטְרָא מִתְּרֵין סִטְרִין מִשְׁמָּא קַדִּישָׁא, חַד סִטְרָא דְּרַחֲמֵי וְדִינָא בְּאַתְוָון גְּלִיפָן, וְחַד סְטָר דִינָא בְּדִינָא נָחָשׁ עֲלֵי צוּר.</p>\n<p>תָּא חֲזֵי כְּתִיב (שמות י״ד:ט״ז) וְאַתָּה הַרֵם אֵת מָטֶךָ וּנְטֵה אֵת יָדְךָ עַל הַיָּם. מַאי וּנְטֵה, כְּלוֹמַר נְטֵה בְּחָד גִּיסָא דִּגְלִיפָא בְּרַחֲמֵי וְדִינָא, וּכְתִיב וַיֵּט מֹשֶׁה אֵת יָדוֹ וְלָא כְּתִיב וַיִשְׁלַּח מֹשֶׁה אֵת יָדוֹ. כְּלוֹמַר, אַסְטֵי מֵחָד גִּיסָא.</p>\n<p>וְאִי תֵּימָא דְּגָּלִיף הֲוָה מִקַּדְמָת דְּנָא נָחָשׁ עֲלֵי צוּר, אֶלָּא בְּאַסָנָא אִתְגְּלִיף דִּכְתִיב (שמותד) וַיָשְׁלִיכֵהוּ אַרְצָה וַיְהִי לְנָחָשׁ, בְּהַהִיא שַׁעְתֵּי אִתְגְּלִיף נָחָשׁ עֲלֵי צוּר.</p>\n<p>וְתָּא חֲזֵי אָמַר רַבִּי יְהוּדָה בָּעָא קוּדְשָׁא בְּרִיךְ הוּא דִּשְׁמוֹי הֲווּ (דהוו) גְּלִיפָן בְּחוּטְרָא יַעֲבִידוּ אָתָאן, וְתַנְיָא תְרֵין אָתִין אִתְעֲבִידוּ בְּיַמָּא בְּהַהוּא סְטָר דְּסָטָא מֹשֶׁה בְּרַחֲמֵי וְדִינָא, בַּזָע יַמָּא לְיִשְׂרָאֵל בְּי\"ב שְׁבִילִין וְאָתִיב בְּדִינָא עַל מִצְרָאֵי וְאַטְבָּע לְהוֹן בִּתְהוֹמָא. הֲדָא הוּא דִכְתִיב, (שמות י\"ד) וַיָּשֶׁב ה' עֲלֵיהֶם אֵת מֵי הַיָּם</p>\n<p>מְהַהִיא שַׁעֲתָא בָּעָא לְאַפָּקָא מַיָּא. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא אַסְטֵי חוּטְרָא מִגִּיסָא אוֹחֲרָא וּתְרֵין אָתָאן אִתְעֲבִיד בֵּיהּ, כְּמָה דְּאִתְעֲבִיד מִסִטְרָא אוֹחֲרָא, חַד אַת הָכָא וְחַד אַת בִּמְרִיבָה. אֲבָל הַשְׁתָּא, (שמות י״ז:ו׳) וְהִכִּיתָ בַּצוּר, בְּאַן צוּר, בְּהַאי צוּר, וְסָלִיק נָחָשׁ דִּלְזִמְנָא אַחֲרָא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר מַאי דִּכְתִיב (במדבר כ׳:ח׳) קַח אֵת הַמָּטֶּה וְהַקְהֵל אֵת הָעֵדָה אַתָּה וְאַהֲרֹן אָחִיךָ וְדִבַּרְתֶּם. מָהוּ וְדִבַּרְתֶּם. אָמַר רַבִּי אֶלְעָזָר מָנִי לֵיהּ עַל נָחָשׁ דְּהָא אִתְעֲבִיד בַּצוּר. הַשְׁתָּא בָּעֵי דְּאִתְעֲבִיד בְּנָחָשׁ לְאַשְׁלָמָא שֶׁמוֹי דְקוּדְשָׁא בְּרִיךְ הוּא בְּאִלֵּין אָתִין,</p>\n<p>מַשְׁמַע דִּכְתִיב וְדִבַּרְתֶּם וּכְתִיב (במדבר כ״א:ו׳) וַיְדַבֵּר הַעֲם בְּאֱלֹהִים וּבְּמֹשֶׁה. מָה כְּתִיב בַּתְרֵיהּ, וַיְשַׁלַּח ה' בַּעָם אֵת הַנְחָשִׁים הַשְׂרָפִים וְגוֹ'. מָה נָחָשׁ חֵילֵיהּ בְּפוּמֵיהּ, אוּף הָכָא בְּפוּמָא</p>\n<p>וּמֹשֶׁה לָא עֲבָד הָכִי, אֶלָּא הִכָּה, מָחָא וְלָא אַשְׁלִים שְׁמָּא, אֶלָּא חָזַר בְּקַדְמִיתָא (כקדמיתא) בִּשְׁמָא דְּצוּר וְשָׁבַק שְׁמָּא דְנָחָשׁ. הֲדָא הוּא דִּכְתִיב וַיַּךְ, וְלָא כְּתִיב וַיְדַבֵּר, כְּמָה דְּאִתְפְּקַד, וְדִבַּרְתֶּם. <Nonei></i>דְּתָנֵינָן צוּר לְמֶעְבַּד, וְנָחָשׁ לְמַלְּלָא. (במדבר כ׳:י״א) וַיַּךְ אֵת הַסֶּלַע בְּמַטֵּהוּ פַּעֲמָיִם, חַד דְּעָבַר וְחַד הַשְׁתָּא.</p>\n<p>תַּנְיָא אָמַר רַבִּי אֶלְעָזָר בֵּיהּ שַׁעֲתָא אִשְׁתָּאַר שְׁמָּא, כְּלּוֹמָר דְּלָא אִשְׁתְּלִים בְּהַהוּא אוֹת דְּשָׁבִיק מֹשֶׁה נָחָשׁ וְלָא אִשְׁתְּלִים כָּל שְׁמָּא, דְּהָא בְּחָד גִּיסָא אִשְׁתְּלִים. בְּיַמָּא מִגִּיסָא אוֹחֲרָא, שָׁרֵי בַּצוּר וְלָא אִשְׁתְּלִים בְּנָחָשׁ. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, עֲבַדְתְּ דְּשָׁרֵי שְׁמִי וְלָא אִשְׁתְּלִים לְמֶעְבַּד אַתְוָון, אוּף אַתְ שָׁרִית, וְלָא תִּשְׁתְלִים. (במדבר כ׳:י״ב) לַכֵן לא תַבִיאוּ, שָׁרִית לְאַפָּקָא לוֹן, וְלָא תִּשְׁתְלִים לְאָעָלָא לוֹן לְאַרְעָא. לַכֵן לֹא תַּבִיאוּ, אָמַר רַבִּי אֶלְעָזָר יָדַע לִבָּא דְּמֹשֶׁה בְּקַדְמִיתָא, דְּדָחִיל כַּד חָמָא נָחָשׁ. דִּכְתִיב (שמות ד׳:ג׳) וַיָּנָס מֹשֶׁה מִפְּנֵי לִבָּא, חָמָא וְלָא יָדַע.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר כְּתִיב (במדבר כ״א:ט׳) וַיַעֲשׂ מֹשֶׁה נָחָשׁ נְחשֶׁת וַיְשִׂימֵהוּ עַל הַנֵס, עַל נֵס לָא כְּתִיב אֶלָּא עַל הַנִס. בָּעָא לְאַתְקָנָא מָה דְּחַסֵר. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא כְּתִיב (במדבר כ״ז:י״ד) לְהַקְדִּישֵׁנִי בְּמַיִם, בְּמַיִם וְלֹא בְּדָבַר אַחֵר. כְּשֵׁם שְׁהִתְחָלַתָּ בְּמַיִם, בָּעֵינָא דְּיִשְׁתְּלִים בִּשְׁמִי הַנֵס בְּמַיִם. אָמַר רִבִּי אֶלְעָזָר אַתְרָא דְּחַסֵר לָא שְׁלִים אֲבָל אַתְּ מַגִּיד נִסָא חֲדָא (נ\"א הכא).</p>\n<p>אָמַר רַבִּי יְהוֹשֻׁעַ כְּתִיב (במדבר כ״א:ח׳) עֲשֵׂה לְךָ שָׂרָף, עֲשֵׂה לְךָ, לְתוֹעֲלְתְּךָ. עֲשֵׂה לְךָ, תַקִּין מָה דְּחַסָרְתְּ וְעִם כָּל זֶה, לָא תִּקֵּן אֶלָּא רְאִיָּיה, שֶׁהָיוּ רוֹאִים בַּנָחָשׁ וְחָיִין, אֲבָל לא נִקְדָשׁ שְׁמָּא בְּמַיִם וְאִשְׁתָּאַר חָסֵר מֵהַשְׁאָר.</p>\n<p>וְתִקַנְתָּ בִּרְאִיָה, (דברים ל״ב:מ״ט) עֲלֶה אֶל הַר הַעֲבָרִים וּרְאֵה, הִנְּךְ רוֹאֶה בְּעֵינֶיךָ וְשָׁמָה לא תַעֲבוֹר (במדבר כ״ז:י״ג) וְרָאִיתָ אוֹתָהּ וְנֵאֶסָפְתָּ אֶל עַמְּךָ. תָּא חֲזֵי דְּאֲפִילּוּ רְאִיָּיה כֵּיוָן דְּעֲבָד רְאִיָּה, בְּהַאי אַשְׁלִים לֵיהּ רְאִיָּה, אֲבָל לָא אַשְׁלִים שְׁמָא בְּמַיָּא כְּמוֹ שְׁאָר כָּל שְׁמָּא.</p>\n<p>אָמַר רַבִּי יִצְחָק בְּשָׁעָה דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא, (במדבר כ) לְכֵן לא תַּבִיאוּ. אָמַר מֹשֶׁה, הַאי חִוְיָא לְתַקָלָא עַלְמָא הוּא. אָמַר לֵיהּ מֹשֶׁה, לָאו הָכִי, דִּינָא לְחַיָּיבַיָּיא וְחָיִין לְמָארֵי קְשׁוֹט, בְּאוֹתָה שָׁעָה דִּכְתִיב (במדבר כ) וְרָאָה אוֹתוֹ וָחַי יָדַע מֹשֶׁה דְּרָכָיו וְהִצְדִּיק עַלָּיו אֵת הַדִּין.</p>\n<p>פָּתַח וְאָמַר, (דברים ל״ב:ד׳) הַצוּר תַמִּים פָּעָלוֹ, דָא הוּא צוּר דְּקַאָמַרִינָן (דברים ל״ב:ד׳) אֵל אֱמוּנָה וְאֵין עֲוֶל דִּכְתִיב, וְרָאָה אוֹתוֹ וָחַי. וּכְתִיב (שמואל ב כ״ב:ל״א) הָאֵל תַמִּים דַּרְכּוֹ.</p>\n<p>אָמַר ר' חִיָּיא וְהָא תָּנֵינָן, אֵל, גְּזֵרָת רַחֲמֵי הוּא כְּמָה דְאַתְּ אָמֵר (דכתיב) (במדבר כ״ג:כ״ב) אֵל מוֹצִיאָם מִמִצְרַיִם, (שמות ל״ד:ו׳) אֵל רַחוּם וְחַנּוּן. אָמַר לֵיהּ, לָאו הָכִי. דְּתָנֵינָן, שָׁלִיט רַחֲמֵי עַל דִּינָא, אֵל בִּלְחוֹדוֹי יְכוֹלֶת הֲוָה לֵיהּ וּרְשׁוּתֵּיהּ הֲוָה דִּילֵיהּ. מַאי יְכוֹלֶת, שׁוּלְטָנוּתָּא דְאֵל, אִתְגַבַּר גְּזֵירָה דִּילֵיהּ. כְּמָה דְאַתְּ אָמֵר, (בראשית ל״א:כ״ט) יֵשׁ לְאֵל יָדִי, וּרְשׁוּתָא דִּילֵיהּ יֵכוֹלֵת דְּעֵינָא בִּישָׁא. כְּמָה דְאַתְּ אָמֵר יֵשׁ לְאֵל יָדִי. אָמַר לֵיהּ, וְהָא כְּתִיב (דברים י׳:י״ז) הָאֵל הַגָּדוֹל הַגִּבּוֹר, אֵל גָּדוֹל נָצְחַא, אֵל בִּלְחוֹדוֹי נָצְחַא.</p>\n<p>וּכְתִיב (דברים ל״ב:ד׳) הַצוּר תַמִּים פָּעָלוֹ כִּי כָל דְּרָכָיו מִשְׁפָּט. הַא צוּר (דברים ל״ב:ד׳) אֵל אֱמוּנָה וְאֵין עֲוֶל, הַא נָחָשׁ עֲלֵי צוּר. נְהֶדָר לְמִילֵי קַדְמָאֵי, וּכְתִיב (איוב ח׳:ג׳) הָאֵל יֵעֲוֵּת מִשְׁפָּט, חַס וְשָׁלוֹם. אָמַר רַבִּי אֶלְעָזָר הַיְינוּ דִּכְתִיב (תהלים פ\"ה) אֶשְׁמֶעָה מָה יְדַבֵּר הָאֵל וְגוֹ'.</p>\n<p>(שמות ד׳:ד׳) וַיִשְׁלַּח יָדוֹ וַיַחֲזֵק בּוֹ וַיְהִי לְמַטֶּה בְּכַפּוֹ, כְּמָה דְאַתְּ אָמֵר (דברים כ״ז:י״ט) מַטֶּה מִשְׁפָּט, מַטֶּה כְּלַפֵּי חֶסֶד. אָמַר רַבִּי יוֹסִי שְׁנֵי מָטוֹת הָיוּ, א' שֶׁל מֹשֶׁה וְא' שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מַאי מַשְׁמַע, דִּכְתִיב (שמות ד׳:כ׳) וּמַטֵה הַאֱלהִים.</p>\n<p>דְּתָנֵינָן, בְּשָׁעָה שֶׁהָיָה נוֹטֵל מֹשֶׁה הַמַטֵה בִּרְשׁוּתוֹ, הָיָה כְּאִילוּ שֶׁלּוֹ. הֲדָא הוּא דִכְתִיב (שמות ד׳:כ׳) וַיִּקַּח מֹשֶׁה אֵת מַטֵה הָאֱלֹהִים בְּיָדוֹ, כֵּיוָן דְּאָמַר וַיִּקַּח מֹשֶׁה, אֵינִי יוֹדֵעַ שֶׁלְקַחוֹ בְּיָדוֹ. אֶלָּא מָהוּ בְּיָדוֹ, בִּרְשׁוּתוֹ בִּיְכֹלְתוֹ.</p>\n<p>וְאָמַר רַבִּי יוֹסִי בִּרְשׁוּתוֹ שֶׁל מֹשֶׁה הָיָה, עַד שֶׁהוּקַם הַמִּשְׁכָּן. כֵּיוָן שֶׁהוּקַם הַמִּשְׁכָּן, חָזַר הַמַּטֶּה לִפְנִי הַעֵדוּת וְמֹשֶׁה הָיָה נוֹטְלוֹ לַעֲשׂוֹת בּוֹ נִסִים. הֲדָא הוּא דִכְתִיב (במדבר כ׳:ט׳) וַיִּקַּח מֹשֶׁה אֵת הַמַּטֵּה מִלִפְנִי ה', כֵּיוָן שֶׁלְקַחוֹ הֲרֵי הוּא בִּרְשׁוּתוֹ וּכְּשֶׁלוֹ הָיָה.</p>\n<p>אָמַר ר' יְהוֹשֻׁעַ, אוֹתוֹ הַמַּטֵּה שֶׁל סְנָפִּירִינוֹן הָיָה, וּמִשֵׁשֶׁת יְמֵי בְּרֵאשִׁית נִבְרָא. כְּמָה דְּתָנֵינָן וְהַמִּכְתָּב וְהַמַטֵה. רַבִּי יְהוּדָה אָמַר, שֶׁל עֵץ הָיָה.</p>\n<p>מַאן דְּאָמַר שֶׁל סְנָפִּירִינוֹן הָיָה, דִּכְתִיב (יחזקאל א׳:כ״ו) כְּמַרְאֶה אֶבֶן סַפִּיר דְמוּת כִּסֵּא, וּכְתִיב (שמות ד׳:כ׳) מַטֵה הָאֱלֹהִים. וּמָאן דְּאָמַר שֶׁל עֵץ הָיָה, כְּדִכְתִיב (שמות ט״ו:כ״ה) וַיּוֹרֵהוּ ה' עֵץ וְגוֹ'</p>\n<p>שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָהוּ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּאן הֲרֵי חֹק וּמִשְׁפָּט לַעֲשׂוֹת נִסִים, חֹק וּמִשְׁפָּט. נָחָשׁ עֲלֵי צוּר דִּכְתִיב (משלי ל׳:י״ט) נָחָשׁ עֲלֵי צוּר. וְשָׁם נִסָהוּ מִשׁוּם דִּכְתִיב (שמות ט״ו:כ״ה) וַיִּמְתְּקוּ הַמַּיִם. דָּבָר אַחֵר, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּאן וּלְהָלְאָה חֹק וּמִשְׁפָּט שֶׁלּא יְהֵא נִקְדָשׁ אֶלָּא בְּמַיִם שֶׁנִמְתֶקוּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כְּתִיב, כִּי מָרִים הֵם מִכָּאן שָׁנִינוּ, יֵשׁ מַּיִם עֲכוּרִים וְיֵשׁ מַּיִם צְלוּלִים, יֵשׁ מַּיִם מָרִים וְיֵשׁ מַּיִם מְתוּקִים. וַיִצְעַק אֶל ה', לָמָה צָעַק, מִכָּאן שֶׁהָיָה בְּצַּעַר בְּאוֹתָה שָׁעָה. אָמַר לוֹ, מֹשֶׁה הַנָּחָשׁ שֶׁנֶהְפַּךְ בַּסְּנֶה עַכְשָׁיו אֶצְטָרֵךְ לְחַקְקַא לֵיהּ בַּצוּר, וְתַרְוַויְיהוּ עָמְדוּ עַל הַמַּיִם הַמָרִים. וְאוֹתָה שָׁעָה אִתְחַקַק צוּר בְּנָחָשׁ שֶׁהָיָה בּוֹ קוֹדֶם. הֲדָא הוּא דִכְתִיב (שמות ט״ו:כ״ה) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט.</p>\n<p>כַּד אֲתָא ר' אַבָּא, אָתוּ <Nonei></i>שָׁאִילּוּ קָמֵיהּ. אָמַר לְהוּ שַׁפִּיר קַאָמַר רַבִּי יְהוּדָה, וְהָכִי הוּא, וַאֲנָא אִיצְטְרִיךְ לְגַלָּאָה רָזָא דְמִלָה, וְהָא חֲזֵינָא דְּרַבִּי יְהוּדָה גָלֵי לָהּ.</p>\n<p>אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, מֹשֶׁה הַשְׁתָּא בְּמִצְרַיִם, הָיָה הַמַּטֵּה שֶׁל אַהֲרֹן לִדְחוֹת הַקַשׁ הַשׁוֹלֵט עַל יִשְׂרָאֵל בְּמִצְרַיִם. אֲבָל כְּשֶׁיָצְאוּ מִמִצְרַיִם, כַּמָה מֵקַטְרֶגֵי מְזָמְנִי עַל יִשְׂרָאֵל לִדְחוֹתָם בַּיָם, כַּמָה מַּיִם מָרִים נִזְדָמְנוּ וְקִטְרֵגוּ.</p>\n<p>בָּאוּ לַיָּם, בָּא רָהַב שָׂרוֹ שֶׁל מִצְרַיִם וְשֶׁל יָם אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה הַרֵם (את מטך) וְנְטֶה (את) יָדְךָ. כֵּיוָן דְּאָמַר הַרֵם אֵת מָטֶךָ מַהוּ וּנְטֶה אֵת יָדְךָ, אֶלָּא הַרֵם אֵת מָטֶךָ נֶגֶד רָהַב שָׂרוֹ שֶׁל מִצְרַיִם. בָּאוּ לְמָרָה, כַּמָה מַּיִם מָרִים נִזְדָמְנוּ אֶצְלָם וְנִצְטָעַר מֹשֶׁה וְצָעַק. הֲדָא הוּא דִכְתִיב (שמות ט״ו:כ״ה) וַיִצְעַק אֶל ה'.</p>\n<p>אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. מֹשֶׁה, הֲרֵי לְךָ עֵצָה בָּזֶה. הַשְׁלֵךְ הַמַּטֵּה אֶצְלָם וְיִתְחַקֶק נָחָשׁ עֲלֵי צוּר, שְׁנֵיהֶם בְּיַחַד, וְיִצוֹלוּ. הֲדָא הוּא דִכְתִיב (שם) וַיּוֹרֵהוּ ה' עֵץ וַיַּשְׁלֵךְ אֶל הַמַּיִם. עֵץ, כְּמָה דְּאִתְּמַר (קהלת י״א:ג׳) מָקוֹם שֶׁיִפּוֹל הָעֵץ, שֶׁהוּא עֵצָה, וַיַּשְׁלֵךְ אֶל הַמַּיִם. וּכְתִיב (שמות ט״ו:כ״ה) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט, נָחָשׁ עֲלֵי צוּר. וְשָׁם נִסָהוּ, עִטְרָהוּ בְּנִסִים אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּאן וּלְהָלְאָה הֲרֵי לְךָ שֶׁיַעֲמוֹד אֵצֶל הַמַּיִם הֲרֵי לְךָ לְהִתְקַדֶשׁ שְׁמִי בְּמַיִם.</p>\n<p>כְּשְׁבָּאוּ לְאֵלִים, בָּאוּ הַמַּיִם לְקַטְרֵג בָּהֶם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּמָקוֹם הַזֶּה אֵין צָרִיךְ מַטֵה. הֲרֵי יַעֲקֹב שֶׁהוּא אִילָן בְּשִׁבְעִים נֶפֶשׁ וְהוּא שִׁבְעִים תְּמָרִים וּשְׁתֵּים עֶשְׂרֵה עֵינוֹת מַּיִם, שְׁנֵים עֲשָׂר שְׁבָטִים בְּשִׁבְעִים עַמּוּדִים וְי\"ב שְׁבָטִים. כְּמָה דְאַתְּ אָמֵר (ישעיהו א׳:כ״ט) כִּי יֵבוֹשׁוֹ מְאֵילִים אֲשֶׁר חַמָדְתֶּם.</p>\n<p>מִיָּד, וַיַחֲנוּ שָׁם עַל הַמַּיִם בַּמָּקוֹם הַזֶּה שֶׁנִקְרָא אִילָן, וְהוּא אֵלִים. מַשְׁמַע דִּכְתִיב עַל הַמַּיִם, וּמִשְׁמָע דִּכְתִיב שָׁם שָׂם לוֹ וְלֹא בְּמָקוֹם אַחֵר וְשָׁם שָׁלְטוּ בְּנֵי יִשְׂרָאֵל עַל הַמַּיִם וְלא הוּצְרָךְ הַמַּטֵּה. מִכָּאן וּלְהָלְאָה אִיצְטְרִיךְ הַמָּטֵּה, בְּנָחָשׁ עֲלֵי צוּר אֵצֶל הַמַּיִם.</p>\n<p>בָּאוּ לְחוֹרֵב בָּאוּ הַמַּיִם לְקַטְרֵג, אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, (שמות ט\"ז) וְהִכִּיתָ בַּצוּר, הַמָּטֶּה אִיצְטְרִיךְ הָכָא וְהִכִּיתָ לַאֵלוּ בְּאוֹתוֹ צוּר וְלא בְּנָחָשׁ. אָמַר מֹשֶׁה יַתִּיר אִיצְטְרִיךְ הָכָא, אֲנָא חָמֵי מַּיִם דְּבָּעְיָּין לְשָׁטְפָה. אֲמַאי, (שמות ט\"ז) הִנְנִי עוֹמֵד לְפָנֶיךָ שָׁם עַל הַצוּר בְּחוֹרֵב וְהִכִּיתָ בַּצוּר.</p>\n<p>אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, עֲדַיִן בִּמְרִיבָה עֲתִידִין הַמַּיִם לְקַטְרֵג יוֹתֵר, שֶׁהֵם מַּיִם עֲכוּרִים רָעִים וּזְדוֹנִים וְיִזְדָוְּוגוּ בָּהֶם יִשְׂרָאֵל בַּגָּלוּי לְעֵינֵיהוֹן. וְאוֹתָה שָׁעָה אִיצְטְרִיךְ הַמַּטֶּה וְהִתִּיר עֲלֵיהֶם הַנָּחָשׁ בַּגָּלוּי לְעֵינֵיהֶם, וְיִתְקַדֵשׁ שְׁמִי. הֲדָא הוּא דִכְתִיב, לְהַקְדִּישֵׁנִי בְּמַיִם לְעֵינֵיהֶם. מָהוּ לְעֵינֵיהֶם, דָבָר שֶׁנִזְדָוְּוגּוּ בָּהֶם בַּגָּלוּי.</p>\n<p>תָּא חֲזֵי, הָכִי חָמָא דָּוִד. דִּכְתִיב, (תהילים קכ״ד:ב׳) לוּלֵי ה' שֶׁהָיָה לָנוּ בְּקוּם עָלֵינוּ אָדָם, זֶה פַּרְעֹה. (תהילים קכ״ד:ב׳) אֲזָי עֲבַר עַל נַפְשֵׁנוּ הַמַּיִם הַזֵּדוֹנִים כְּדְּאַמְרִינָן (תהילים קכ״ד:ז׳) נַפְשֵׁנוּ כְּצִפּוֹר נִמְלְטָה מִפַּח יוֹקְשִׁים.</p>\n<p>אָמַר רַבִּי אַבָּא, מָה רָאָה מֹשֶׁה בְּאוֹתָה שָׁעָה שֶׁלֹּא עָשָׂה בַּנָחָשׁ, אֶלָּא יִשְׂרָאֵל הָיוּ דוֹחַקִים למֹשֶׁה, תְּנָה לָנוּ מַּיִם, נִתְיָּיעֵץ וְאָמַר. קוּדְשָׁא בְּרִיךְ הוּא אָמַר לִּי, עֲמוֹד בַּנָחָשׁ וַאֲנָא חָמֵי דְאֵין גְּזֵירָה לְנָחָשׁ בְּמַיִם אֶלָּא בְּעָפָר. אָמַר רַבִּי יְהוּדָה מֵהָכָא, (בראשית ג׳:י״ד) וְעָפָר תֹאכַל כָּל יְמֵי חַיֶּיךָ מַשְׁמַע דְּעָפָר יֵיכוּל כָּל יוֹמוֹי, אֲבָל לא בְּמַיָּא. וְיִשְׂרָאֵל דַחֲקִין לִּי, וְאַף עַל גַּב דְּיִתְעֲבִיד נִיסָא, לָא יִתְעֲבִיד בְּאֲתָר דָא, אֶלָּא אִתְחַקַק בְּעַפְרָא וְלָא בְּמַיָּא. דִּכְתִיב (שמות ד׳:ג׳) וַיָשְׁלִיכֵהוּ אַרְצָה וַיְהִי לְנָחָשׁ. וְצוּר בְּדָא אִתְחַקַק בְּמַיָּא בְּמָרָה, וּכְּבָר עֲבָד נִיסָא בְּהַאי, דְּאִתְעֲבִיד זִמְנָא אַחֲרָא. דִּכְתִיב, (במדבר כ׳:י״א) וַיַּךְ אֵת הַסֶּלַע בְּמַטֵּהוּ פַּעֲמָיִם. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מֹשֶׁה (במדבר כ׳:י״א) יַעַן לא הֶאֱמַנְתֶּם בִּי לְהַקְדִּישֵׁנִי, דְּחַשָׁבְתוּן דְּלָא יָכִיל נָחָשׁ בְּמַיִם. (במדבר כ׳:י״ב) לַכֵן לֹא תַבִיאוּ:</p>"]]});
